package com.hdmapreforged;

import static com.hdmapreforged.Route.Outcome.*;

import java.util.*;
import java.util.function.*;
import java.util.regex.*;
import java.util.stream.*;
import lombok.*;

/**
 * A way past a bank first, for teleports and transport kept in the bank (setting, with the bank as last seen): to the
 * nearest of a few banks with what is carried, take out what the rest needs, and on from there with the bank's items
 * too. Taken instead of the way with what is carried only when it gets there notably sooner, or only it gets there.
 */
@RequiredArgsConstructor
final class BankDetour {
    /** How a step's detail starts when it needs something only the bank has (RouteSource names it). */
    static final String FROM_BANK = "From the bank: ";

    /** Joins the name of the teleport or transport that takes one to the bank to what is taken there ("... Castle Wars → Bank: Dramen staff"). */
    static final String TO_BANK = " → Bank: ";

    /** A step's name without {@link #TO_BANK} and what follows: what it is left out of a route by. */
    static String plain(String name) {
        int at = name == null ? -1 : name.lastIndexOf(TO_BANK);
        return at < 0 ? name : name.substring(0, at);
    }

    /** Half ticks to open the bank and take things out. */
    static final int WITHDRAW = 6;

    /**
     * Per bank, where to stand at it: beside each of its booths or chests, nearest its icon first (or the icon). The few
     * banks quickest to reach are tried, each at its first; the way in then goes where the game walks from where it comes in.
     */
    final int[][] banks;
    /** The same search with the bank's items as well. */
    final RouteRequest withBank;
    /** Half ticks it must save: the setting's tiles, run. */
    final int saves;
    /** What the rune pouch in the bank holds, by name: taken as the pouch. */
    final Map<String, Long> pouch;

    /**
     * The route for {@code request}: past a bank when its {@link RouteRequest#bank} makes it notably quicker. The way
     * without the bank gives up at {@code costLimit}, as {@link Pathfinder#find(RouteRequest, BooleanSupplier, int)}.
     */
    static Route find(Pathfinder pathfinder, RouteRequest request, BooleanSupplier cancelled, int costLimit) {
        Route plain = pathfinder.find(request, cancelled, costLimit);
        var detour = request.bank;
        if (detour == null || plain.outcome == CANCELLED || cancelled.getAsBoolean()) {
            return plain;
        }
        // Notably quicker or nothing: no search of the detour goes past what would still beat the plain way (nor the
        // caller's limit), so it costs little where it cannot win.
        long limit = Math.min(costLimit, plain.outcome == FOUND ? (long) plain.cost - detour.saves - WITHDRAW
            : Integer.MAX_VALUE);
        Route banked = limit < 0 ? null : detour.route(pathfinder, request, cancelled, (int) limit);
        boolean better = banked != null && (plain.outcome != FOUND
            || banked.cost + detour.saves <= plain.cost);
        return better && !cancelled.getAsBoolean() ? banked : plain;
    }

    /**
     * To the nearest bank, then on with the bank's items; null when no bank is reached or nothing banked is used, or
     * the whole (the bank step's {@link #WITHDRAW} besides) costs more than {@code limit}.
     */
    Route route(Pathfinder pathfinder, RouteRequest request, BooleanSupplier cancelled, int limit) {
        Route toBank = null;
        int[] stands = null;
        for (int bank : quickest(request)) {
            Route way = pathfinder.find(request.between(request.start, banks[bank][0]), cancelled, limit);
            if (way.outcome == FOUND && (toBank == null || way.cost < toBank.cost)) {
                toBank = way;
                stands = banks[bank];
            }
        }
        if (toBank == null || cancelled.getAsBoolean()) {
            return null;
        }
        int nearer = stand(pathfinder.map, (x, y, z, dx, dy) -> pathfinder.closed(Tiles.pack(x, y, z), dx, dy), stands,
            entry(toBank, stands[0]));
        if (nearer != stands[0]) {
            // Another booth or side of the same bank, where the game walks from where the way comes in.
            Route way = pathfinder.find(request.between(request.start, nearer), cancelled, limit);
            toBank = way.outcome == FOUND ? way : toBank;
        }
        int at = toBank.end >= 0 ? toBank.end : toBank.target;
        Route on = pathfinder.find(withBank.between(at, request.target), cancelled, limit - toBank.cost);
        if (on.outcome != FOUND) {
            return null;
        }
        // Only what the bank's items add (not a ladder or cave on the way, which no item opens).
        var fromBank = new HashSet<String>();
        // Not the ways back into one's house, which the plain search from inside it lacks: no item of the bank opens them.
        Stream.concat(withBank.startEdges.stream(), withBank.edges.stream()).filter(e -> !HousePlan.contains(e.to))
            .forEach(e -> fromBank.add(e.name));
        Stream.concat(request.startEdges.stream(), request.edges.stream()).forEach(e -> fromBank.remove(e.name));
        var take = new LinkedHashSet<String>();
        for (var step : on.steps) {
            String named = step.detail != null && step.detail.startsWith(FROM_BANK)
                ? step.detail.substring(FROM_BANK.length()) : null;
            // "items": the game had not named them yet.
            if (named != null && !named.equals("items")) {
                take.addAll(Arrays.asList(named.split(", ")));
            } else if (named != null || step.isJump() && fromBank.contains(step.name)) {
                take.add(taken(step));
            }
        }
        if (take.isEmpty()) {
            return null;
        }
        var taken = viaPouch(take);
        String items = String.join(", ", taken);
        var steps = new ArrayList<Route.Step>(toBank.steps);
        // The last teleport or transport on the way names what is taken at the bank (not a staircase or cave).
        for (int i = steps.size() - 1; i >= 0; i--) {
            var s = steps.get(i);
            if (s.name != null && EnumSet.of(Route.Step.Kind.TELEPORT, Route.Step.Kind.TRANSPORT, Route.Step.Kind.SHIP,
                Route.Step.Kind.HOUSE).contains(s.kind)) {
                steps.set(i, s.withName(s.name + TO_BANK + items));
                break;
            }
        }
        steps.add(new Route.Step(Route.Step.Kind.BANK, new int[]{at, at}, "Bank: " + items, null,
            WITHDRAW, 0, List.of(), null));
        for (var s : on.steps) {
            // What the steps name from the bank: the pouch's runes as the pouch, as the bank step does.
            steps.add(s.detail != null && s.detail.startsWith(FROM_BANK)
                ? s.withDetail(FROM_BANK + String.join(", ", viaPouch(Arrays.asList(
                    s.detail.substring(FROM_BANK.length()).split(", "))))) : s);
        }
        return new Route(FOUND, steps, toBank.cost + WITHDRAW + on.cost, request.target, on.end, false,
            false, toBank.nodes + on.nodes).withViaWild(toBank.viaWild || on.viaWild)
            .withKeptOut(toBank.keptOut || on.keptOut);
    }

    /** What is taken: runes the pouch holds enough of (a combination rune in it counts as its two) as "Rune pouch". */
    Set<String> viaPouch(Collection<String> take) {
        var held = new HashMap<String, Long>();
        pouch.forEach((name, n) -> {
            if (name == null) {
                return;
            }
            String lower = name.toLowerCase(Locale.ROOT);
            held.merge(lower, n, Long::sum);
            for (var c : COMBINED.get()) {
                if (lower.equals(c[0] + " rune")) {
                    held.merge(c[1] + " rune", n, Long::sum);
                    held.merge(c[2] + " rune", n, Long::sum);
                }
            }
        });
        var taken = new LinkedHashSet<String>();
        for (String t : take) {
            var m = AMOUNT.matcher(t);
            taken.add(m.matches() && enough(m, held) ? "Rune pouch" : t);
        }
        return taken;
    }

    /** Combination runes and the two runes each holds (list "combination runes"). */
    static final RouteFiles.Table<String[][]> COMBINED = new RouteFiles.Table<>(() -> Pathfinder.list(
        "combination runes", r -> r.split(" ")).stream().filter(c -> c.length > 2).toArray(String[][]::new));

    /** An item as a bank step names it: "3 × Air rune", or "Dramen staff" (one). */
    static final Pattern AMOUNT = Pattern.compile("(?:(\\d+) × )?(.+)");

    /** Whether {@code held} (by lower-case name) has as many as {@code m} (matched {@link #AMOUNT}) names. */
    static boolean enough(Matcher m, Map<String, Long> held) {
        return held.getOrDefault(m.group(2).toLowerCase(Locale.ROOT), 0L) >= (m.group(1) == null ? 1
            : Long.parseLong(m.group(1)));
    }

    /** Tiles from a booth within which a way counts as come into its bank. */
    static final int ENTRY = 8;

    /** Where {@code way} first comes within {@link #ENTRY} tiles of {@code stand} on its floor; else its end. */
    static int entry(Route way, int stand) {
        for (var step : way.steps) {
            for (int point : step.kind == Route.Step.Kind.WALK ? step.points : new int[0]) {
                if (Tiles.near(point, stand, ENTRY)) {
                    return point;
                }
            }
        }
        return way.end >= 0 ? way.end : stand;
    }

    /**
     * Of {@code stands}, where the game walks from {@code point} to use the bank: the first its search reaches (it tries
     * west, east, south, north, then the diagonals, so not always the nearest side), else the first.
     */
    static int stand(CollisionMap map, GameWalk.Shut shut, int[] stands, int point) {
        int[] walk = GameWalk.path(map, shut, point, stands);
        return walk == null ? stands[0] : walk[walk.length - 1];
    }

    /** Half ticks a guess adds for leaving the house before a teleport cast outside it. */
    static final int OUT_OF_HOUSE = 12;

    /** Banks searched for the way to one: the quickest by {@link #guess}. */
    static final int TRIED = 3;

    int[] quickest(RouteRequest request) {
        return quickest(request, Arrays.stream(banks).mapToInt(b -> b[0]).toArray(), TRIED);
    }

    /**
     * The {@code n} of {@code places} (indices) quickest to reach by a guess (no search): from where the player stands
     * (not in a house, whose plan lies far off the map) and from where each way out of it lands (a teleport, a house's
     * portal, box or glory), its time plus the run on in a straight line (a tile a half tick). Underground and above are
     * apart, so a place 6400 tiles north is not counted as near.
     */
    static int[] quickest(RouteRequest request, int[] places, int n) {
        var from = new ArrayList<int[]>();
        int start = request.start;
        if (start >= 0 && !HousePlan.contains(start)) {
            from.add(new int[]{start, 0});
        }
        // Ways into the house (from outside it) come before any way out of it: its time, then the walk in the plan.
        var in = new ArrayList<int[]>();
        for (Edge e : request.startEdges) {
            from.add(new int[]{e.to, e.cost});
            if (start >= 0 && HousePlan.contains(e.to)) {
                in.add(new int[]{e.to, e.cost});
            }
        }
        for (Edge e : request.edges) {
            // Out of one's house: its portals, the box, the glory and the like; a teleport cast once out of it (a
            // minigame teleport by the house portal).
            if (e.from >= 0 && (e.kind == Edge.Kind.TELEPORT || HousePlan.contains(e.from)
                && !HousePlan.contains(e.to))) {
                int enter = start >= 0 && !HousePlan.contains(start) ? Integer.MAX_VALUE / 4 : 0;
                for (int[] i : in) {
                    enter = Math.min(enter, i[1] + Tiles.distance(i[0], e.from) * Pathfinder.RUN);
                }
                from.add(new int[]{e.to, e.cost + (e.kind == Edge.Kind.TELEPORT ? OUT_OF_HOUSE : enter)});
            }
        }
        long[] guessed = new long[places.length];
        for (int i = 0; i < places.length; i++) {
            guessed[i] = (long) guess(from, places[i]) << 32 | i;
        }
        Arrays.sort(guessed);
        return Arrays.stream(guessed, 0, Math.min(n, places.length)).mapToInt(g -> (int) g).toArray();
    }

    /** Half ticks from the nearest of {@code from} ({tile, half ticks to get there}) to {@code place}, as the crow flies. */
    static int guess(List<int[]> from, int place) {
        int best = Integer.MAX_VALUE / 2;
        for (var f : from) {
            if (f[0] >= 0 && Tiles.y(f[0]) / 6400 == Tiles.y(place) / 6400) {
                best = Math.min(best, f[1] + Tiles.distance(f[0], place) * Pathfinder.RUN);
            }
        }
        return best;
    }

    /**
     * What a step takes from the bank when its items are not named (a house's fairy ring): "runes" for a spell, the item
     * of a teleport ("Ring of dueling"), else "items for" what it is ("items for Fairy ring").
     */
    static String taken(Route.Step step) {
        String name = step.name;
        int arrow = name.indexOf(" → ");
        name = arrow > 0 ? name.substring(0, arrow) : name;
        int colon = name.indexOf(": ");
        String what = colon > 0 ? name.substring(0, colon) : name;
        return step.category != null && step.category.endsWith("Spellbook") ? "runes"
            : step.kind == Route.Step.Kind.TELEPORT || step.kind == Route.Step.Kind.HOUSE ? what : "items for " + what;
    }
}

package com.hdmapreforged;

import lombok.*;

/**
 * One of the maps, in world tile coordinates: the game's own world maps, the map of everything, and our maps of the
 * dungeons the game's map lacks, which show the map of everything's tiles ({@code tiles}).
 */
@RequiredArgsConstructor
final class BaseMap {
    static final int SURFACE = 0, FULL = -1;

    final int id;
    final String name;
    final int minX, minY, maxX, maxY, centerX, centerY;
    /** The map whose tiles draw this one: itself, or {@link #FULL}. */
    final int tiles;
    /** The map list it is of (set by it): its region table tells on which floor it draws some ground. */
    BaseMaps maps;

    boolean contains(int x, int y) {
        return x >= minX && x < maxX && y >= minY && y < maxY;
    }

    long area() {
        return (long) (maxX - minX) * (maxY - minY);
    }

    public String toString() {
        return name;
    }
}

package com.hdmapreforged;

import static com.hdmapreforged.BaseMap.*;

import com.google.gson.*;
import java.io.*;
import java.util.*;
import java.util.function.*;
import net.runelite.api.coords.*;

/** A map version's map list (our map server's maps.json); its region table decides where bounds overlap. */
final class BaseMaps {
    final List<BaseMap> sorted;
    final Map<Integer, BaseMap> byId = new HashMap<>();
    RegionTable regions = new RegionTable();
    /** The map version they are of; null when not known. */
    String version;

    BaseMaps(List<BaseMap> maps) {
        var list = new ArrayList<>(maps);
        // Surface first, then the combined map, then alphabetical.
        list.sort(Comparator.comparingInt((BaseMap m) -> m.id == SURFACE ? 0 : m.id == FULL ? 1 : 2)
            .thenComparing(m -> m.name, String.CASE_INSENSITIVE_ORDER));
        sorted = Collections.unmodifiableList(list);
        for (var map : list) {
            byId.put(map.id, map);
            map.maps = this;
        }
    }

    /** maps.json's entries: {@code {mapId, name, bounds: [[minX, minY], [maxX, maxY]], center: [x, y], tiles}}. */
    static final class Entry {
        int mapId;
        String name;
        int[][] bounds;
        int[] center;
        /** Absent: its own. */
        Integer tiles;
    }

    /** An unreadable list gives no maps (the builders check the entries: BaseMapsTest). */
    static BaseMaps parse(Gson gson, Reader json) {
        var maps = new ArrayList<BaseMap>();
        try {
            for (var e : gson.fromJson(json, Entry[].class)) {
                // A map without a name (the sort below needs it) makes the file unusable, as one without bounds.
                maps.add(new BaseMap(e.mapId, Objects.requireNonNull(e.name), e.bounds[0][0], e.bounds[0][1], e.bounds[1][0], e.bounds[1][1],
                    e.center[0], e.center[1], e.tiles == null ? e.mapId : e.tiles));
            }
        } catch (RuntimeException e) {
            maps.clear();
        }
        return new BaseMaps(maps);
    }

    BaseMap byId(int id) {
        return byId.get(id);
    }

    BaseMap surface() {
        var surface = byId.get(SURFACE);
        return surface != null ? surface : sorted.get(0);
    }

    /** One of the maps drawing the point's region (maps may share one), or the map {@link #find} gives. */
    boolean draws(BaseMap map, int x, int y) {
        var owners = drawers(x, y);
        return map != null && map.contains(x, y)
            && (owners != null && Arrays.stream(owners).anyMatch(id -> id == map.id) || find(x, y) == map);
    }

    /** The owners of the spot's 8×8 zone where known, else the region's owners; null when not known. */
    int[] drawers(int x, int y) {
        var zone = regions.zoneOwners(x, y);
        return zone != null ? zone : regions.owners(RegionTable.regionId(x, y));
    }

    /**
     * The floor {@code on} draws a game point's ground on where the region table says it is not the point's own (the
     * Brimhaven Dungeon's raised paths, walked on floor 2, drawn on floor 1), or -1. Any map drawn with the same tiles
     * draws it there.
     */
    int drawnFloor(BaseMap on, WorldPoint game) {
        var found = on == null ? null : regions.floorOverride(game.getX(), game.getY(), game.getPlane());
        var map = found == null ? null : byId(found[0]);
        return map != null && map.tiles == on.tiles ? found[1] : -1;
    }

    /**
     * The game's floor a spot of a map's drawn floor stands for: {@code game} (where the map's moves put it), unless that
     * is no ground ({@code ground}) and a floor the region table draws on {@code drawnFloor} there is: then that floor.
     */
    WorldPoint gameFloor(BaseMap on, WorldPoint game, int drawnFloor, Predicate<WorldPoint> ground) {
        if (on == null || ground == null || ground.test(game)) {
            return game;
        }
        for (int d = 1; d < 4; d++) {
            for (int floor : new int[]{game.getPlane() - d, game.getPlane() + d}) {
                var other = floor < 0 || floor > 3 ? null : new WorldPoint(game.getX(), game.getY(), floor);
                if (other != null && drawnFloor(on, other) == drawnFloor && ground.test(other)) {
                    return other;
                }
            }
        }
        return game;
    }

    /** The map drawing a game point elsewhere when one does (the Kalphite Lair), else {@link #find(int, int)}. */
    BaseMap find(WorldPoint game) {
        int x = game.getX(), y = game.getY();
        if (HousePlan.contains(x, y)) {
            // One's house is drawn at the surface map's edge.
            return byId(SURFACE);
        }
        // The map that draws the ground of the point's floor where the zone's own map does not draw it on that floor (the
        // region table's floor lines).
        var line = regions.floorOverride(x, y, game.getPlane());
        var floor = line == null ? null : byId(line[0]);
        if (floor != null && (floor.id == FULL || floor.contains(x, y))) {
            return floor;
        }
        var drawn = WorldMapMoves.drawn(game);
        var moved = drawn == null ? null : byId(drawn.map);
        // Some moves put a place outside the bounds of the map they name.
        if (moved != null && moved.contains(drawn.point.getX(), drawn.point.getY())) {
            return moved;
        }
        var found = find(x, y);
        if (found != null && WorldMapMoves.covers(found.id, x, y)) {
            // That map shows a moved place here: the smallest other map that draws the spot.
            BaseMap other = null;
            for (var map : sorted) {
                if (map != found && map.id != FULL && map.contains(x, y) && !WorldMapMoves.covers(map.id, x, y)
                    && (other == null || map.area() < other.area())) {
                    other = map;
                }
            }
            return other != null ? other : byId(FULL);
        }
        return found;
    }

    /** Whether a map shows this game point where it is, not a moved place instead. */
    boolean drawsGame(BaseMap map, WorldPoint game) {
        if (map != null && regions.floorOverride(game.getX(), game.getY(), game.getPlane()) != null) {
            // Its floor's ground is drawn by the map the table names (and every map with the same tiles).
            return map.contains(game.getX(), game.getY()) && drawnFloor(map, game) >= 0;
        }
        return map != null && draws(map, game.getX(), game.getY())
            && !WorldMapMoves.covers(map.id, game.getX(), game.getY());
    }

    /**
     * The smallest map drawing the point's region; the map of everything where the region has none; else the smallest
     * map containing the point, and the map of everything last. Null when no map holds it.
     */
    BaseMap find(int x, int y) {
        var full = byId.get(FULL);
        boolean fullDraws = full != null && full.contains(x, y);
        var owners = drawers(x, y);
        BaseMap best = null;
        if (owners != null) {
            for (int id : owners) {
                var map = byId.get(id);
                if (map != null && map.contains(x, y) && (best == null || map.area() < best.area())) {
                    best = map;
                }
            }
            if (best != null || owners.length == 0 && fullDraws) {
                return best != null ? best : full;
            }
        }
        for (var map : sorted) {
            if (map.id != FULL && map.contains(x, y) && (best == null || map.area() < best.area())) {
                best = map;
            }
        }
        // The map of everything draws all of the game's ground: where no other map does, it shows the spot.
        return best != null ? best : fullDraws ? full : null;
    }
}

package com.hdmapreforged;

import static java.awt.RenderingHints.*;
import static javax.swing.SwingUtilities.*;
import static java.awt.Cursor.*;
import static java.lang.Math.*;

import java.awt.*;
import java.awt.Point;
import java.awt.event.*;
import java.awt.geom.*;
import java.util.*;
import java.util.function.*;
import javax.swing.*;
import javax.swing.plaf.*;
import javax.swing.text.*;
import lombok.*;
import net.runelite.api.*;

/**
 * The map over the game view: a window of its own, owned by the client's (RuneLite's own window is never changed).
 * Not drawn in the game because Stretched Mode would blur it. Takes the keyboard only while its search is typed in, or
 * for a click from another program, which it hands on to the game; never moves or resizes the client window. Swing
 * thread only.
 */
final class BigWindow {
    static final Color GRIP_DOTS = new Color(255, 255, 255, 90);
    static final int EDGE = 8;
    /** Thicker than the sides: easy to take hold of. */
    static final int BOTTOM = 12, MIN_WIDTH = 320, MIN_HEIGHT = 240;
    static final Color FRAME = new Color(30, 32, 37);
    /** By the edges a point is on (see edgesAt). */
    static final int[] CURSORS = {DEFAULT_CURSOR, W_RESIZE_CURSOR, E_RESIZE_CURSOR,
        DEFAULT_CURSOR, N_RESIZE_CURSOR, NW_RESIZE_CURSOR, NE_RESIZE_CURSOR,
        DEFAULT_CURSOR, S_RESIZE_CURSOR, SW_RESIZE_CURSOR, SE_RESIZE_CURSOR};

    final Client client;
    final MapScreen screen;
    final Consumer<String> saveBounds;
    final Predicate<KeyEvent> isMapKey;
    JWindow window;
    Canvas watchedCanvas;
    Window watchedFrame;
    /** Fractions of the game view, or null for the default. */
    Rectangle2D relative;
    boolean maximised;
    /** Focusable while another program is active: the next click decides where the keys go (see FirstClick). */
    boolean fromOutside;
    final ComponentListener follower = new ComponentAdapter() {
        public void componentMoved(ComponentEvent e) {
            place();
        }

        public void componentResized(ComponentEvent e) {
            place();
        }

        public void componentHidden(ComponentEvent e) {
            close();
        }
    };
    /** The client window going active or not: see followGame. */
    final WindowAdapter gameFocus = new WindowAdapter() {
        public void windowActivated(WindowEvent e) {
            invokeLater(BigWindow.this::followGame);
        }

        public void windowDeactivated(WindowEvent e) {
            invokeLater(BigWindow.this::followGame);
        }
    };

    BigWindow(Client client, MapScreen screen, String savedBounds, Consumer<String> saveBounds,
        Predicate<KeyEvent> isMapKey) {
        this.client = client;
        this.screen = screen;
        this.saveBounds = saveBounds;
        this.isMapKey = isMapKey;
        screen.view.windowControls = this;
        var decoded = decode(savedBounds);
        if (decoded != null) {
            relative = (Rectangle2D) decoded[0];
            maximised = (Boolean) decoded[1];
        }
        screen.setScreenLayout(MapScreen.Layout.FULL);
        screen.view.addMouseListener(new MouseAdapter() {
            public void mouseReleased(MouseEvent e) {
                invokeLater(BigWindow.this::giveKeysBack);
            }
        });
    }

    boolean isOpen() {
        return window != null && window.isVisible();
    }

    void setHostBounds(Rectangle screenBounds) {
        if (!window.getBounds().equals(screenBounds)) {
            window.setBounds(screenBounds);
            window.validate();
        }
    }

    static boolean menuOpen() {
        return MenuSelectionManager.defaultManager().getSelectedPath().length > 0;
    }

    static Rectangle onScreen(Component c) {
        return new Rectangle(c.getLocationOnScreen(), c.getSize());
    }

    void toggle() {
        if (isOpen()) {
            close();
        } else {
            open();
        }
    }

    void open() {
        Canvas canvas = client.getCanvas();
        if (canvas == null || !canvas.isShowing()) {
            return;
        }
        if (window == null) {
            window = new JWindow(getWindowAncestor(canvas));
            // A utility window: left out of the taskbar and alt-tab, raised and lowered with the game.
            window.setType(Window.Type.UTILITY);
            // Some window managers still focus it on click; then Escape and the map key must work here too.
            window.setAutoRequestFocus(false);
            // Never focusable, so the desktop (KWin) keeps the game active; only while typing (see typable).
            window.setFocusableWindowState(false);
            window.addWindowFocusListener(new WindowAdapter() {
                public void windowLostFocus(WindowEvent e) {
                    window.setFocusableWindowState(false);
                }
            });
            window.setContentPane(new JLayer<>(frame(), new FirstClick()));
        }
        watch(canvas);
        place();
        if (!window.isVisible()) {
            window.setVisible(true);
            // Some window managers place a new window themselves.
            invokeLater(this::place);
            screen.opened();
        }
    }

    void close() {
        if (window != null && window.isVisible()) {
            // No longer focusable, a focused window hands the keyboard back to the game's (setFocusableWindowState).
            window.setFocusableWindowState(false);
            window.setVisible(false);
        }
    }

    void toggleMaximised() {
        maximised = !maximised;
        save();
        place();
        screen.view.repaint();
    }

    /**
     * Escape and the map key close the map while one of its parts has the keyboard (the game sees no keys then). While
     * typing or in a menu, keys are theirs: Escape closes the menu, letters type.
     */
    boolean closeKey(KeyEvent e) {
        Object owner = e.getSource();
        if (!isOpen() || menuOpen() || owner instanceof JTextComponent && (e.getKeyCode() != KeyEvent.VK_ESCAPE
            || !((JTextComponent) owner).getText().isEmpty())) {
            return false;
        }
        if (e.getKeyCode() == KeyEvent.VK_ESCAPE || isMapKey.test(e)) {
            close();
            return true;
        }
        return false;
    }

    /** In a window kept unfocusable (see open), a click in {@code field} lets the window take the keyboard to type. */
    static void typable(JTextComponent field) {
        field.addMouseListener(new MouseAdapter() {
            public void mousePressed(MouseEvent e) {
                Window host = getWindowAncestor(field);
                if (host != null && !host.getFocusableWindowState()) {
                    host.setFocusableWindowState(true);
                    invokeLater(field::requestFocus);
                }
            }
        });
    }

    /**
     * While the game is not active (another program is), the map is focusable, so a click on it makes this program
     * active again; giveKeysBack then hands the keyboard to the game.
     */
    void followGame() {
        Window frame = watchedFrame;
        if (window != null && frame != null && !window.isFocused()) {
            fromOutside = !frame.isActive();
            window.setFocusableWindowState(fromOutside);
        }
    }

    /**
     * The first click from another program, on a card's button, a panel or the frame as on the map: the keys go back
     * to the game, or the window's first field would keep them; on a text field they stay, to type.
     */
    final class FirstClick extends LayerUI<JComponent> {
        public void installUI(JComponent c) {
            super.installUI(c);
            ((JLayer<?>) c).setLayerEventMask(AWTEvent.MOUSE_EVENT_MASK);
        }

        protected void processMouseEvent(MouseEvent e, JLayer<? extends JComponent> layer) {
            if (e.getID() == MouseEvent.MOUSE_RELEASED && fromOutside) {
                fromOutside = false;
                if (!(e.getComponent() instanceof JTextComponent)) {
                    invokeLater(BigWindow.this::giveKeysBack);
                }
            }
        }
    }

    /** After a click on the map itself, the keyboard goes back to the game. */
    void giveKeysBack() {
        Canvas canvas = watchedCanvas;
        // Open, and its window has the keyboard (its owner's last focused part gets it: setFocusableWindowState).
        if (isOpen() && window.isFocused() && !menuOpen() && canvas != null && canvas.isShowing()) {
            window.setFocusableWindowState(false);
        }
    }

    JPanel frame() {
        JPanel root = new JPanel(new BorderLayout()) {
            protected boolean processKeyBinding(KeyStroke ks, KeyEvent e, int condition, boolean pressed) {
                return pressed && closeKey(e) || super.processKeyBinding(ks, e, condition, pressed);
            }

            protected void paintComponent(Graphics graphics) {
                super.paintComponent(graphics);
                var g = (Graphics2D) graphics.create();
                g.setRenderingHint(KEY_ANTIALIASING, VALUE_ANTIALIAS_ON);
                g.setColor(GRIP_DOTS);
                PoiIcons.glyph(g, "GRIP_CORNER", getWidth() - 3, getHeight() - 3);
                g.dispose();
            }
        };
        root.setBackground(FRAME);
        root.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(new Color(255, 255, 255, 40)),
            BorderFactory.createEmptyBorder(0, EDGE - 1, BOTTOM - 1, EDGE - 1)));
        root.add(new Grip(), BorderLayout.NORTH);
        root.add(screen, BorderLayout.CENTER);
        var resizer = new Resizer(root);
        root.addMouseListener(resizer);
        root.addMouseMotionListener(resizer);
        return root;
    }

    void place() {
        Canvas canvas = watchedCanvas;
        if (window == null || canvas == null) {
            return;
        }
        if (!canvas.isShowing()) {
            close();
            return;
        }
        Rectangle view = onScreen(canvas);
        setHostBounds(maximised ? view : fit(relative, view));
    }

    /** Screen bounds for fractions of the game view (null: the default), inside the view, at least the minimum size. */
    static Rectangle fit(Rectangle2D relative, Rectangle view) {
        var r = relative != null ? relative : new Rectangle2D.Double(0.08, 0.06, 0.84, 0.88);
        int width = (int) round(r.getWidth() * view.width), height = (int) round(r.getHeight() * view.height);
        width = min(view.width, max(min(MIN_WIDTH, view.width), width));
        height = min(view.height, max(min(MIN_HEIGHT, view.height), height));
        int x = view.x + (int) round(r.getX() * view.width), y = view.y + (int) round(r.getY() * view.height);
        x = max(view.x, min(view.x + view.width - width, x));
        y = max(view.y, min(view.y + view.height - height, y));
        return new Rectangle(x, y, width, height);
    }

    void setFromScreen(Rectangle bounds) {
        Canvas canvas = watchedCanvas;
        if (canvas == null || !canvas.isShowing() || canvas.getWidth() <= 0 || canvas.getHeight() <= 0) {
            return;
        }
        Rectangle view = onScreen(canvas), fitted = fit(fraction(bounds, view), view);
        relative = fraction(fitted, view);
        maximised = false;
        setHostBounds(fitted);
    }

    /** Screen bounds as fractions of the game view. */
    static Rectangle2D fraction(Rectangle r, Rectangle view) {
        return new Rectangle2D.Double((r.x - view.x) / (double) view.width, (r.y - view.y) / (double) view.height,
            r.width / (double) view.width, r.height / (double) view.height);
    }

    void save() {
        saveBounds.accept(encode(relative, maximised));
    }

    static String encode(Rectangle2D relative, boolean maximised) {
        if (relative == null) {
            return maximised ? "max" : "";
        }
        return String.format(Locale.ROOT, "%.4f,%.4f,%.4f,%.4f%s", relative.getX(), relative.getY(), relative.getWidth(),
            relative.getHeight(), maximised ? ",max" : "");
    }

    /** {bounds or null, maximised}, or null when nothing usable was saved. */
    static Object[] decode(String saved) {
        if (saved == null || saved.trim().isEmpty()) {
            return null;
        }
        var parts = saved.trim().split(",");
        if (parts.length == 1 && "max".equals(parts[0])) {
            return new Object[]{null, true};
        }
        if (parts.length != 4 && parts.length != 5) {
            return null;
        }
        try {
            double x = Double.parseDouble(parts[0]), y = Double.parseDouble(parts[1]), w = Double.parseDouble(parts[2]);
            double h = Double.parseDouble(parts[3]);
            if (!(w > 0.05 && w <= 1 && h > 0.05 && h <= 1 && x >= -1 && x <= 1 && y >= -1 && y <= 1)) {
                return null;
            }
            return new Object[]{new Rectangle2D.Double(x, y, w, h), parts.length == 5 && "max".equals(parts[4])};
        } catch (NumberFormatException e) {
            return null;
        }
    }

    void watch(Canvas canvas) {
        if (canvas == watchedCanvas) {
            return;
        }
        unwatch();
        watchedCanvas = canvas;
        canvas.addComponentListener(follower);
        watchedFrame = getWindowAncestor(canvas);
        if (watchedFrame != null) {
            watchedFrame.addComponentListener(follower);
            watchedFrame.addWindowListener(gameFocus);
        }
    }

    void unwatch() {
        if (watchedCanvas != null) {
            watchedCanvas.removeComponentListener(follower);
        }
        if (watchedFrame != null) {
            watchedFrame.removeComponentListener(follower);
            watchedFrame.removeWindowListener(gameFocus);
        }
        watchedCanvas = null;
        watchedFrame = null;
    }

    void dispose() {
        close();
        unwatch();
        if (window != null) {
            window.dispose();
            window = null;
        }
    }

    /** A mouse drag that moves or resizes the map; saved once let go. */
    abstract class Drag extends MouseAdapter {
        Point grab;
        Rectangle start;

        void grab(MouseEvent e) {
            grab = e.getLocationOnScreen();
            start = window.getBounds();
        }

        public void mouseReleased(MouseEvent e) {
            if (grab != null) {
                grab = null;
                save();
            }
        }
    }

    final class Grip extends JComponent {
        Grip() {
            // The grip's height: 10 pixels.
            setPreferredSize(new Dimension(100, 10));
            setCursor(getPredefinedCursor(MOVE_CURSOR));
            setToolTipText(PoiType.t("t23"));
            Drag mouse = new Drag() {
                public void mousePressed(MouseEvent e) {
                    if (isLeftMouseButton(e)) {
                        grab(e);
                    }
                }

                public void mouseDragged(MouseEvent e) {
                    if (grab == null) {
                        return;
                    }
                    if (maximised) {
                        Canvas canvas = watchedCanvas;
                        if (canvas == null || !canvas.isShowing()) {
                            return;
                        }
                        // Dragging a maximised window restores it under the mouse.
                        Rectangle restored = fit(relative, onScreen(canvas));
                        double along = (grab.x - start.x) / (double) max(1, start.width);
                        start = new Rectangle(grab.x - (int) (restored.width * along), start.y, restored.width, restored.height);
                        maximised = false;
                    }
                    Point now = e.getLocationOnScreen();
                    setFromScreen(new Rectangle(start.x + now.x - grab.x, start.y + now.y - grab.y, start.width, start.height));
                }

                public void mouseClicked(MouseEvent e) {
                    if (e.getClickCount() == 2) {
                        toggleMaximised();
                    }
                }
            };
            addMouseListener(mouse);
            addMouseMotionListener(mouse);
        }

        protected void paintComponent(Graphics graphics) {
            var g = (Graphics2D) graphics.create();
            g.setRenderingHint(KEY_ANTIALIASING, VALUE_ANTIALIAS_ON);
            g.setColor(FRAME);
            g.fillRect(0, 0, getWidth(), getHeight());
            g.setColor(GRIP_DOTS);
            PoiIcons.glyph(g, "GRIP", getWidth() / 2.0, getHeight() / 2.0);
            g.dispose();
        }
    }

    @RequiredArgsConstructor
    final class Resizer extends Drag {
        final JComponent root;
        int edges;

        /** Bits: 1 left, 2 right, 4 top, 8 bottom. */
        int edgesAt(Point p) {
            int corner = EDGE * 4, w = root.getWidth(), h = root.getHeight();
            return (p.x < EDGE || p.x < corner && p.y >= h - corner ? 1 : 0)
                | (p.x >= w - EDGE || p.x >= w - corner && p.y >= h - corner ? 2 : 0)
                | (p.y < 3 ? 4 : 0)
                | (p.y >= h - BOTTOM || p.y >= h - corner && (p.x < corner || p.x >= w - corner) ? 8 : 0);
        }

        public void mouseMoved(MouseEvent e) {
            int at = edgesAt(e.getPoint());
            root.setCursor(getPredefinedCursor(at < CURSORS.length ? CURSORS[at] : DEFAULT_CURSOR));
        }

        public void mouseExited(MouseEvent e) {
            if (grab == null) {
                root.setCursor(getDefaultCursor());
            }
        }

        public void mousePressed(MouseEvent e) {
            edges = edgesAt(e.getPoint());
            if (edges != 0 && isLeftMouseButton(e)) {
                grab(e);
            }
        }

        public void mouseDragged(MouseEvent e) {
            if (grab == null) {
                return;
            }
            Point now = e.getLocationOnScreen();
            int dx = now.x - grab.x, dy = now.y - grab.y;
            Rectangle r = new Rectangle(start);
            if ((edges & 1) != 0) {
                int width = max(MIN_WIDTH, start.width - dx);
                r.x = start.x + start.width - width;
                r.width = width;
            }
            if ((edges & 2) != 0) {
                r.width = max(MIN_WIDTH, start.width + dx);
            }
            if ((edges & 4) != 0) {
                int height = max(MIN_HEIGHT, start.height - dy);
                r.y = start.y + start.height - height;
                r.height = height;
            }
            if ((edges & 8) != 0) {
                r.height = max(MIN_HEIGHT, start.height + dy);
            }
            setFromScreen(r);
        }
    }
}

package com.hdmapreforged;

import java.io.*;
import java.util.*;
import java.util.function.*;
import java.util.zip.*;
import lombok.*;

/**
 * Where one can walk, from the bundled collision.zip: per region and floor, bitsets of walkable tiles and of walls and
 * doors on the north and east edges. Immutable after loading but for one's own house ({@link #setHouse}, replaced
 * whole), so any thread may read it.
 */
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
final class CollisionMap {
    static final String RESOURCE = RouteFiles.DIR + "collision.zip";
    static final int MAGIC = 0x48444d43, WALK = 0, WALL_N = 64, WALL_E = 128, DOOR_N = 192, DOOR_E = 256, LAYERS = 320;
    static final int MAX_BIN_BYTES = 64 * 1024 * 1024, MAX_TABLE_BYTES = 16 * 1024 * 1024;

    /** By {@code region * 4 + plane}: five bitsets of 64 longs, or null. */
    final long[][] floors = new long[1 << 18][];
    /** By packed tile: "Chop-down Vines (bring an axe)". */
    final Map<Integer, String> obstacles;
    final boolean[] obstacleRegions = new boolean[1 << 16];
    /** One's own house, where no map of the game lies; replaced whole. */
    @Setter
    volatile HousePlan house;

    static CollisionMap load() throws IOException {
        try (InputStream in = RouteFiles.require(RESOURCE)) {
            return read(in);
        }
    }

    static CollisionMap read(InputStream zipped) throws IOException {
        byte[] bin = null;
        var obstacles = new HashMap<Integer, String>();
        var zip = new ZipInputStream(zipped);
        ZipEntry entry;
        while ((entry = zip.getNextEntry()) != null) {
            if ("collision.bin".equals(entry.getName())) {
                bin = RouteFiles.read(zip, MAX_BIN_BYTES, "collision.bin");
            } else if ("obstacles.tsv".equals(entry.getName())) {
                Pathfinder.rows(new ByteArrayInputStream(RouteFiles.read(zip, MAX_TABLE_BYTES, "obstacles.tsv")), 0,
                    parts -> obstacle(obstacles, parts));
            }
        }
        if (bin == null) {
            throw new IOException("No collision.bin");
        }
        var map = new CollisionMap(obstacles);
        obstacles.keySet().forEach(node -> map.obstacleRegions[region(Tiles.x(node), Tiles.y(node))] = true);
        map.decode(bin);
        return map;
    }

    void decode(byte[] bin) throws IOException {
        var in = new DataInputStream(new ByteArrayInputStream(bin));
        if (in.readInt() != MAGIC || in.readInt() != 1) {
            throw new IOException("Unknown collision data");
        }
        int count = in.readInt();
        if (count < 0 || count > 1 << 16) {
            throw new IOException("Bad region count " + count);
        }
        for (int i = 0; i < count; i++) {
            int region = in.readUnsignedShort(), mask = in.readUnsignedByte();
            for (int z = 0; z < 4; z++) {
                if ((mask & 1 << z) != 0) {
                    floors[region << 2 | z] = longs(in, LAYERS);
                }
            }
            // Ground floor water: only the development tools use it.
            in.skipBytes((mask & 16) != 0 ? 64 * 8 : 0);
        }
    }

    static long[] longs(DataInputStream in, int count) throws IOException {
        long[] longs = new long[count];
        for (int j = 0; j < count; j++) {
            longs[j] = in.readLong();
        }
        return longs;
    }

    /** The region of a tile, or -1 off the world. */
    static int region(int x, int y) {
        return (x | y) >>> 14 == 0 ? (x >> 6) << 8 | (y >> 6) : -1;
    }

    /** "x y plane <tab> name <tab> action <tab> what it takes"; bad lines are skipped. */
    static void obstacle(Map<Integer, String> obstacles, String[] parts) {
        if (parts.length < 4) {
            return;
        }
        int at = Tiles.parse(parts[0]);
        if (at < 0) {
            return;
        }
        String action = parts[2].isEmpty() ? parts[2] : Character.toUpperCase(parts[2].charAt(0)) + parts[2].substring(1);
        obstacles.put(at, action + " " + parts[1] + " (bring " + parts[3] + ")");
    }

    String obstacle(int node) {
        return isObstacle(Tiles.x(node), Tiles.y(node), node) ? obstacles.get(node) : null;
    }

    boolean isObstacle(int x, int y, int node) {
        int region = region(x, y);
        return region >= 0 && obstacleRegions[region] && obstacles.containsKey(node);
    }

    long[] layers(int x, int y, int z) {
        int region = region(x, y);
        var found = region < 0 || z < 0 || z > 3 ? null : floors[region << 2 | z];
        var plan = found == null && region >= 0 && z >= 0 && z <= 3 ? house : null;
        return plan != null ? plan.layers(region, z) : found;
    }

    static boolean bit(long[] layers, int offset, int x, int y) {
        int i = (x & 63) << 6 | (y & 63);
        return (layers[offset + (i >> 6)] & 1L << (i & 63)) != 0;
    }

    boolean walkable(int x, int y, int z) {
        return edge(x, y, z, WALK);
    }

    boolean edge(int x, int y, int z, int offset) {
        var layers = layers(x, y, z);
        return layers != null && bit(layers, offset, x, y);
    }

    boolean canStep(int x, int y, int z, int dx, int dy) {
        if (!walkable(x + dx, y + dy, z)) {
            return false;
        }
        if (dx != 0 && dy != 0) {
            // Diagonal: both straight routes around the corner must be open, and no door on the way.
            return walkable(x + dx, y, z) && walkable(x, y + dy, z) && clear(x, y, z, dx, 0) && clear(x + dx, y, z, 0, dy)
                && clear(x, y, z, 0, dy) && clear(x, y + dy, z, dx, 0);
        }
        return straightOpen(x, y, z, dx, dy);
    }

    boolean straightOpen(int x, int y, int z, int dx, int dy) {
        return !crosses(x, y, z, dx, dy, WALL_N, WALL_E);
    }

    boolean clear(int x, int y, int z, int dx, int dy) {
        return straightOpen(x, y, z, dx, dy) && !door(x, y, z, dx, dy);
    }

    boolean door(int x, int y, int z, int dx, int dy) {
        return (dx == 1 || dx == -1 || dy == 1 || dy == -1) && crosses(x, y, z, dx, dy, DOOR_N, DOOR_E);
    }

    boolean crosses(int x, int y, int z, int dx, int dy, int north, int east) {
        return dx == 1 ? edge(x, y, z, east) : dx == -1 ? edge(x - 1, y, z, east)
            : dy == 1 ? edge(x, y, z, north) : edge(x, y - 1, z, north);
    }

    /** Nearest walkable tile within {@code radius} (Chebyshev rings, then straight distance), packed, or -1. */
    int walkableNear(int x, int y, int z, int radius) {
        return nearest(x, y, z, 0, radius, x, y, null, false);
    }

    /**
     * The same, ties going farthest from {@code (awayX, awayY)} (a shortcut's near side, not a pocket between its
     * stones), and tiles {@code avoid} names (a shut-in pocket) only when no other is within reach.
     */
    int walkableNear(int x, int y, int z, int radius, int awayX, int awayY, IntPredicate avoid) {
        int plain = nearest(x, y, z, 0, radius, awayX, awayY, null, false);
        if (avoid == null || plain < 0 || !avoid.test(plain)) {
            return plain;
        }
        int open = nearest(x, y, z, 0, radius, awayX, awayY, avoid, false);
        return open >= 0 ? open : plain;
    }

    /**
     * The nearest walkable tile in rings {@code first} to {@code radius} round (x, y) that {@code avoid} does not name
     * (null: any): by straight distance, ties farthest from (awayX, awayY); {@code scanned}: the first met, west to east
     * and south to north. Packed, or -1.
     */
    int nearest(int x, int y, int z, int first, int radius, int awayX, int awayY, IntPredicate avoid, boolean scanned) {
        for (int r = first; r <= radius; r++) {
            int best = -1;
            double bestDistance = Double.MAX_VALUE;
            for (int dx = -r; dx <= r; dx++) {
                for (int dy = -r; dy <= r; dy++) {
                    if (Math.max(Math.abs(dx), Math.abs(dy)) != r || !walkable(x + dx, y + dy, z)
                        || avoid != null && avoid.test(Tiles.pack(x + dx, y + dy, z))) {
                        continue;
                    }
                    double away = (x + dx - awayX) * (double) (x + dx - awayX) + (y + dy - awayY) * (double) (y + dy - awayY);
                    double d = scanned ? 0 : (dx * dx + dy * dy) * 1e6 - away;
                    if (d < bestDistance) {
                        bestDistance = d;
                        best = Tiles.pack(x + dx, y + dy, z);
                    }
                }
            }
            if (best >= 0) {
                return best;
            }
        }
        return -1;
    }
}

package com.hdmapreforged;

import lombok.*;

/** A non-walking jump in the route graph; costs in half game ticks. */
@AllArgsConstructor(access = AccessLevel.PRIVATE)
final class Edge {
    enum Kind {
        STAIRS,
        ENTRANCE,
        TELEPORT,
        TRANSPORT,
        SHIP,
        BOARD,
        DISEMBARK,
        HOUSE
    }

    static final int ANYWHERE = -1;

    /** {@code withFrom}: the same from another start. */
    @With
    final int from;
    final int to;
    final Kind kind;
    final String name, detail;
    /** As the search weighs it: {@link #time} plus any extra the player asked for. */
    @With(AccessLevel.PRIVATE)
    final int cost;
    final int time;
    final String category;

    Edge(int from, int to, Kind kind, String name, String detail, int cost) {
        this(from, to, kind, name, detail, cost, null);
    }

    Edge(int from, int to, Kind kind, String name, String detail, int cost, String category) {
        this(from, to, kind, name, detail, Math.max(1, cost), Math.max(1, cost), category);
    }

    /** Heavier in the search only ("only use a teleport when it saves at least 10 tiles"). */
    Edge weighed(int extra) {
        return extra <= 0 ? this : withCost(cost + extra);
    }

    public String toString() {
        return kind + " " + name + " " + (from == ANYWHERE ? "anywhere" : Tiles.format(from)) + " -> " + Tiles.format(to);
    }
}

package com.hdmapreforged;

import lombok.*;
import java.util.*;

/**
 * The jumps starting (or ending) at each node, as indices into a list of edges; looked up without boxing. Immutable
 * once made.
 */
@RequiredArgsConstructor(access = AccessLevel.PRIVATE)
final class EdgeIndex {
    final IntMap slots;
    final int[][] lists;

    static EdgeIndex of(List<Edge> edges, int offset, boolean byDestination) {
        var slots = new IntMap(edges.size());
        int count = 0;
        int[] counts = new int[edges.size()];
        for (Edge e : edges) {
            int key = byDestination ? e.to : e.from;
            if (key == Edge.ANYWHERE) {
                continue;
            }
            int slot = slots.get(key);
            if (slot == IntMap.MISSING) {
                slot = count++;
                slots.put(key, slot);
            }
            counts[slot]++;
        }
        int[][] made = new int[count][];
        for (int i = 0; i < made.length; i++) {
            made[i] = new int[counts[i]];
            counts[i] = 0;
        }
        for (int i = 0; i < edges.size(); i++) {
            int key = byDestination ? edges.get(i).to : edges.get(i).from;
            if (key != Edge.ANYWHERE) {
                int slot = slots.get(key);
                made[slot][counts[slot]++] = offset + i;
            }
        }
        return new EdgeIndex(slots, made);
    }

    int[] get(int node) {
        int slot = slots.get(node);
        return slot == IntMap.MISSING ? null : lists[slot];
    }
}

package com.hdmapreforged;

import java.util.*;
import java.util.regex.*;
import lombok.*;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.*;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.*;

/**
 * The route's next fairy ring in the ring's travel log, as Shortest Path shows its own: its code in green, scrolled to.
 * Only the log's look changes; nothing is dialled or clicked.
 */
@RequiredArgsConstructor
final class FairyRingLog {
    static final int GREEN = 0x00FF00;
    /** "Fairy ring: CKS", "House fairy ring: BKS", "Fairy ring: AIR, DLR, DJQ, then AJS". */
    static final Pattern RING = Pattern.compile("airy ring: ((?:[A-Z]{3}(?:, then |, )?)+)");
    static final Pattern CODE = Pattern.compile("[A-Z]{3}");

    final RouteFeature routes;
    boolean open;
    /** The code scrolled to since the log opened, the scroll set for it, and whether it is still held (not the user's). */
    String scrolledTo;
    int scrolledY;
    boolean holding;

    /** The codes of the route's first fairy ring step, in the order dialled; empty without one. */
    static List<String> codes(Route route) {
        for (var step : route == null ? List.<Route.Step>of() : route.steps) {
            Matcher ring = step.name == null ? null : RING.matcher(step.name);
            if (ring != null && ring.find()) {
                var codes = new ArrayList<String>();
                Matcher code = CODE.matcher(ring.group(1));
                while (code.find()) {
                    codes.add(code.group());
                }
                return codes;
            }
        }
        return List.of();
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event) {
        if (event.getGroupId() == InterfaceID.FAIRYRINGS_LOG) {
            open = true;
            scrolledTo = null;
        }
    }

    @Subscribe
    public void onWidgetClosed(WidgetClosed event) {
        open &= event.getGroupId() != InterfaceID.FAIRYRINGS_LOG;
    }

    /**
     * Every frame while the log is open, as Shortest Path does: the game draws its list again (on opening, by its search
     * box's timer, on searching and sorting) with its own colours, and puts back the scroll it keeps itself (the top,
     * or where the user scrolled). So the scroll goes to the code again each time the list was drawn anew, until the user
     * scrolls; again for another code or when the log opens again.
     */
    @Subscribe
    public void onPostClientTick(PostClientTick event) {
        List<String> codes = open ? codes(routes.shown) : List.of();
        if (codes.isEmpty()) {
            return;
        }
        Client client = routes.client;
        Widget contents = client.getWidget(InterfaceID.FairyringsLog.CONTENTS);
        // Favourites' codes in green too; the list scrolls to the first code's row.
        Widget faves = client.getWidget(InterfaceID.FairyringsLog.FAVES);
        mark(faves == null ? null : faves.getStaticChildren(), codes);
        Widget[] rows = contents == null ? null : contents.getDynamicChildren();
        // None green: drawn anew since the last frame, with the game's scroll.
        boolean drawn = rows == null || Arrays.stream(rows).noneMatch(row -> row != null && row.getTextColor() == GREEN);
        Widget first = mark(rows, codes);
        if (first == null) {
            return;
        }
        if (!codes.get(0).equals(scrolledTo)) {
            scrolledTo = codes.get(0);
            holding = drawn = true;
        } else if (!drawn && contents.getScrollY() != scrolledY) {
            holding = false; // the user's own scroll
        }
        if (!holding || !drawn) {
            return;
        }
        // No client script for the scrollbar's thumb: reviewers flag running them.
        contents.setScrollY(Math.max(0, Math.min(first.getRelativeY(), contents.getScrollHeight() - contents.getHeight())));
        contents.revalidateScroll();
        // As the client keeps it: a scroll it changed after is the user's.
        scrolledY = contents.getScrollY();
    }

    /** Colours the codes among these widgets green; the first code's widget, or null. */
    static Widget mark(Widget[] widgets, List<String> codes) {
        Widget first = null;
        for (Widget widget : widgets == null ? new Widget[0] : widgets) {
            // The game writes the codes spaced out: "B K R".
            int at = widget == null ? -1 : codes.indexOf(String.valueOf(widget.getText()).replace(" ", ""));
            if (at >= 0) {
                widget.setTextColor(GREEN);
                first = at == 0 ? widget : first;
            }
        }
        return first;
    }
}

package com.hdmapreforged;

import java.util.*;
import lombok.*;

/** Entrance fees the plugin cannot check ({@code fees.tsv}), weighed as extra time so a free way wins. */
final class Fees {
    static final int NEAR = 2;

    @RequiredArgsConstructor
    static final class Fee {
        final int x, y, plane;
        /** Extra half ticks. */
        final int cost;
        final String text;
    }

    static final RouteFiles.Table<List<Fee>> FEES = new RouteFiles.Table<>(Fees::load);

    static Fee at(int x, int y, int plane) {
        return FEES.get().stream().filter(fee -> fee.plane == plane && Math.abs(fee.x - x) <= NEAR
            && Math.abs(fee.y - y) <= NEAR).findFirst().orElse(null);
    }

    static List<Fee> load() {
        return Pathfinder.table(RouteFiles.DIR + "fees.tsv", parts -> {
            var xyz = Pathfinder.ints(parts[0]);
            return new Fee(xyz[0], xyz[1], xyz[2], Integer.parseInt(parts[1].trim()), parts[2].trim());
        });
    }
}

