import net.runelite.api.coords.*;

/** The friends button at the map's bottom left, opening into the party list and a member's details. Swing thread only. */
@RequiredArgsConstructor
final class FriendsWidget implements Widget {
    @RequiredArgsConstructor
    static final class Member {
        final long id;
        final String name;
    }

    @RequiredArgsConstructor
    static final class Row {
        final String name;
        final int world;
        final WorldPoint point;
        final Color color;
        /** The party member's id. */
        final long id;
    }

    static final Color OTHER_WORLD = new Color(255, 190, 120), FRIEND = new Color(150, 150, 160);
    static final Color WORLD = new Color(190, 190, 195);
    static final Font ROW = new Font(Font.SANS_SERIF, Font.PLAIN, 13);
    static final int WIDTH = 256, LEFT = 12, ROW_HEIGHT = 22;
    static final NumberFormat AMOUNT = NumberFormat.getIntegerInstance();

    final PartyMap party;
    final MapView view;
    /** A member's details, as the sidebar paints them too. */
    final MemberPages pages;
    /** Repaints while drops rise. */
    final PartyOverlay.Ticker ticker = new PartyOverlay.Ticker(() -> FriendsWidget.this.view.repaint());
    boolean dropsMoving, open;
    long selected = -1;
    boolean folded;

    long selected() {
        return open ? selected : -1;
    }

    void show(long id) {
        open = true;
        selected = id;
    }

    static List<Row> rows(List<PartyMembers.Marker> party, List<Member> group) {
        var rows = new ArrayList<Row>();
        // One row per member, not per name shown: two not named yet are two "Party member" rows, as on the map.
        var ids = new HashSet<Long>();
        for (var marker : party) {
            if (ids.add(marker.id)) {
                rows.add(new Row(marker.name != null ? marker.name : "Party member", marker.world, marker.point,
                    PartyOverlay.color(marker.id), marker.id));
            }
        }
        for (Member member : group) {
            // Not logged in: nothing to show.
            if (member.name != null && ids.add(member.id)) {
                rows.add(new Row(member.name, 0, null, null, member.id));
            }
        }
        return rows;
    }

    public void paint(Graphics2D g, int width, int height, int bottom, Clicks clicks) {
        dropsMoving = false;
        try {
            paintWidget(g, width, bottom, clicks);
        } finally {
            ticker.painted(dropsMoving);
        }
    }

    List<Member> groupNow() {
        try {
            return party.groupMembers();
        } catch (ConcurrentModificationException e) {
            // Changed on another thread while read; the next frame has them.
            return Collections.emptyList();
        }
    }

    void paintWidget(Graphics2D g, int width, int bottom, Clicks clicks) {
        if (!party.config.partyFriendsTab()) {
            // No list to close it with: no one stays chosen (their name shown) by a click on their marker.
            selected = -1;
            return;
        }
        var rows = rows(party.members.markers(System.currentTimeMillis()), groupNow());
        if (rows.isEmpty() && !party.party.isInParty()) {
            if (party.lastParty() != null) {
                clicks.add(tab(g, bottom, clicks, "Rejoin party"), () -> party.join(view), "Join your last party again");
            }
            return;
        }
        int w = min(WIDTH, width - 24);
        var tab = tab(g, bottom, clicks, "Party · " + rows.size() + (open ? "  ▾" : "  ▴"));
        double tabTop = tab.getY();
        clicks.add(tab, () -> {
            open = !open;
            view.repaint();
        }, open ? "Close the list" : PoiType.t("t24"));
        if (!open) {
            return;
        }
        Row chosen = null;
        for (Row row : rows) {
            chosen = row.id == selected && selected >= 0 ? row : chosen;
        }
        selected = chosen != null ? selected : -1;
        if (rows.isEmpty()) {
            String text = "No one else in your party yet";
            g.setFont(ROW);
            double boxWidth = max(w, g.getFontMetrics().stringWidth(text) + 20);
            var alone = new RoundRectangle2D.Double(LEFT, tabTop - 4 - ROW_HEIGHT - 6, boxWidth,
                ROW_HEIGHT + 6, 10, 10);
            box(g, alone, CONTROL_FILL, CONTROL_EDGE);
            g.setColor(FRIEND);
            g.drawString(text, LEFT + 10, middle(alone.getCenterY(), g.getFontMetrics()));
            return;
        }
        // Opens upwards, as many rows as fit (with room for a chosen one's folded details above, so one can switch
        // between them); the last line then says how many more.
        int fit = max(1, (int) ((tabTop - 60 - (chosen != null ? 34 + MemberPages.STATUS_H : 0)) / ROW_HEIGHT));
        var shown = rows.size() > fit ? rows.subList(0, max(1, fit - 1)) : rows;
        int more = rows.size() - shown.size(), lines = shown.size() + (more > 0 ? 1 : 0);
        double listTop = tabTop - 4 - lines * ROW_HEIGHT - 6;
        var list = new RoundRectangle2D.Double(LEFT, listTop, w, lines * ROW_HEIGHT + 6, 10, 10);
        box(g, list, CONTROL_FILL, CONTROL_EDGE);
        g.setFont(ROW);
        var metrics = g.getFontMetrics();
        int mine = party.myWorld;
        for (int i = 0; i < shown.size(); i++) {
            Row row = shown.get(i);
            double top = listTop + 3 + i * ROW_HEIGHT;
            var area = new RoundRectangle2D.Double(LEFT + 3, top, w - 6, ROW_HEIGHT, 8, 8);
            if (clicks.hovered(area) || row == chosen) {
                g.setColor(CONTROL_HOVER);
                g.fill(area);
            }
            clicks.add(area, () -> {
                if (row.point != null) {
                    party.follow(view, row.id);
                }
                selected = row.id;
                view.repaint();
            }, "Look at " + row.name + " and what they carry");
            double cy = top + ROW_HEIGHT / 2.0;
            dot(g, row.color, LEFT + 10, cy - 4);
            String world = row.world > 0 ? "W" + row.world : "";
            int worldWidth = metrics.stringWidth(world);
            g.setColor(row.world > 0 && mine > 0 && row.world != mine ? OTHER_WORLD : WORLD);
            g.drawString(world, LEFT + w - 10 - worldWidth, middle(cy, metrics));
            g.setColor(row.point != null ? Color.WHITE : FRIEND);
            String name = fit(row.name, metrics, w - 38 - worldWidth);
            g.drawString(name, LEFT + 24, middle(cy, metrics));
        }
        if (more > 0) {
            double cy = listTop + 3 + shown.size() * ROW_HEIGHT + ROW_HEIGHT / 2.0;
            g.setColor(FRIEND);
            g.drawString("+" + more + " more", LEFT + 24, middle(cy, metrics));
        }
        if (chosen != null) {
            paintDetails(g, chosen, LEFT, w, listTop - 4, clicks);
        }
    }

    void paintDetails(Graphics2D g, Row row, double x0, int w, double bottomY, Clicks clicks) {
        int panelW = max(w, 4 * Orbs.WIDTH + 3 * 4 + 16), full = 30 + pages.height(panelW - 16) + 10;
        // Folded (or the map too low for all of it): the name and the orbs only.
        boolean cramped = bottomY - full < 44, compact = folded || cramped;
        int height = compact ? 30 + MemberPages.STATUS_H + 4 : full;
        double top = bottomY - height;
        var panel = new RoundRectangle2D.Double(x0, top, panelW, height, 12, 12);
        box(g, panel, CONTROL_FILL, CONTROL_EDGE);
        g.setFont(CONTROL_FONT);
        var title = g.getFontMetrics();
        if (row.point != null) {
            // The name looks at them again, as the panel stays open after one looks elsewhere.
            var name = new RoundRectangle2D.Double(x0 + 4, top + 4, panelW - (cramped ? 32 : 54), 22, 8, 8);
            if (clicks.hovered(name)) {
                g.setColor(CONTROL_HOVER);
                g.fill(name);
            }
            clicks.add(name, () -> party.follow(view, row.id), "Follow " + row.name);
        }
        dot(g, row.color, x0 + 12, top + 11);
        g.setColor(Color.WHITE);
        text(g, fit(row.name, title, panelW - 130), x0 + 26, top + 19);
        if (row.world > 0) {
            String world = "W" + row.world;
            g.setFont(ROW);
            var rowMetrics = g.getFontMetrics();
            int mine = party.myWorld;
            boolean elsewhere = mine > 0 && row.world != mine;
            double right = x0 + panelW - (cramped ? 34 : 56);
            g.setColor(elsewhere ? OTHER_WORLD : WORLD);
            text(g, world, right - rowMetrics.stringWidth(world), top + 20);
        }
        titleButton(g, clicks, title, x0 + panelW - 26, top, "×", () -> {
            selected = -1;
            view.repaint();
        }, "Close");
        if (!cramped) {
            titleButton(g, clicks, title, x0 + panelW - 48, top, folded ? "+" : "\u2013", () -> {
                folded = !folded;
                view.repaint();
            }, folded ? "Unfold" : "Fold up: the name and the orbs only");
        }
        if (compact) {
            pages.paintStatus(g, party.members.gear(row.id), x0 + 8, top + 28, panelW - 16);
            dropsMoving |= PartyOverlay.paintXp(g, party.xp(row.id), party::skill, x0 + panelW - 64, top + height - 8);
            return;
        }
        dropsMoving |= pages.paint(g, row.id, x0 + 8, top + 30, panelW - 16, clicks, view::repaint);
    }

    static RoundRectangle2D tab(Graphics2D g, int bottom, Clicks clicks, String label) {
        g.setFont(CONTROL_FONT);
        var metrics = g.getFontMetrics();
        int tabWidth = floorGroupWidth(metrics);
        double tabTop = bottom - 2 * CONTROL - 6;
        var tab = new RoundRectangle2D.Double(LEFT, tabTop, tabWidth, CONTROL, 10, 10);
        box(g, tab, clicks.hovered(tab) ? CONTROL_HOVER : CONTROL_FILL, CONTROL_EDGE);
        g.setColor(Color.WHITE);
        text(g, label, LEFT + (tabWidth - metrics.stringWidth(label)) / 2.0, middle(tabTop + CONTROL / 2.0, metrics));
        return tab;
    }

    static void dot(Graphics2D g, Color color, double x, double y) {
        g.setColor(color != null ? color : FRIEND);
        g.fill(new Ellipse2D.Double(x, y, 8, 8));
    }

    static void titleButton(Graphics2D g, Clicks clicks, FontMetrics title, double x, double top,
        String mark, Runnable action, String tip) {
        var button = new RoundRectangle2D.Double(x, top + 5, 20, 20, 8, 8);
        if (clicks.hovered(button)) {
            g.setColor(CONTROL_HOVER);
            g.fill(button);
        }
        g.setColor(Floating.LIGHT);
        g.setFont(CONTROL_FONT);
        text(g, mark, button.getCenterX() - title.stringWidth(mark) / 2.0, top + 20);
        clicks.add(button, action, tip);
    }

    static String fit(String text, FontMetrics metrics, int width) {
        if (metrics.stringWidth(text) <= width) {
            return text;
        }
        String cut = text;
        while (cut.length() > 1 && metrics.stringWidth(cut + "…") > width) {
            cut = cut.substring(0, cut.length() - 1);
        }
        return cut + "…";
    }
}

package com.hdmapreforged;

import java.awt.image.*;
import java.util.*;
import java.util.concurrent.*;
import net.runelite.api.*;
import net.runelite.api.worldmap.*;
import net.runelite.client.util.*;

/** The game's own world map icons, read from the client: drawn as the game's icons, and so our icons look like them. */
final class GameIcons {
    static final Map<Integer, BufferedImage> ELEMENT_SPRITES = new ConcurrentHashMap<>();

    static boolean hasElements() {
        return !ELEMENT_SPRITES.isEmpty();
    }

    static BufferedImage element(int id) {
        return id < 0 ? null : ELEMENT_SPRITES.get(id);
    }

    /** Map elements read per call (each client tick): all of them, hundreds, in one tick made a hitch. */
    static final int SLICE = 50;

    /**
     * Client thread only: reads up to {@link #SLICE} of {@code ids}, taking them off it; false until none are left, or
     * while the game has not loaded its data yet.
     */
    static boolean loadElements(Client client, Collection<Integer> ids) {
        var left = ids.iterator();
        for (int n = 0; n < SLICE && left.hasNext(); n++) {
            int id = left.next();
            if (!ELEMENT_SPRITES.containsKey(id)) {
                var config = config(client, id);
                if (config == null && waiting(client)) {
                    return false;
                }
                BufferedImage image = config == null ? null : icon(config);
                if (image != null) {
                    ELEMENT_SPRITES.put(id, image);
                }
            }
            left.remove();
        }
        return ids.isEmpty();
    }

    /** Null for an id the game does not know (or not yet). */
    static MapElementConfig config(Client client, int id) {
        try {
            return client.getMapElementConfig(id);
        } catch (RuntimeException e) {
            return null;
        }
    }

    /** Still null once logged in: an id gone after a game update, not worth retrying every tick. */
    static boolean waiting(Client client) {
        return client.getGameState() != GameState.LOGGED_IN;
    }

    static BufferedImage icon(MapElementConfig config) {
        var pixels = config.getMapIcon(false);
        BufferedImage image = pixels == null ? null : pixels.toBufferedImage();
        return image != null && image.getWidth() > 0 && image.getHeight() > 0 ? image : null;
    }

    /** Fairy rings: the game draws its transport arrow for them; ours, as the game draws its icons. */
    static final BufferedImage FAIRY_RING = ImageUtil.loadImageResource(GameIcons.class, "fairy_ring.png");

    /** Null when not loaded yet, or a type we draw ourselves. */
    static BufferedImage get(PoiType type) {
        return type == PoiType.FAIRY_RING ? FAIRY_RING : element(type.element);
    }

    static void clear() {
        ELEMENT_SPRITES.clear();
    }

    /** Client thread only: the types' icons ({@link #loadElements}); false while the game has not loaded its data yet. */
    static boolean load(Client client) {
        var ids = new HashSet<Integer>();
        for (var type : PoiType.values()) {
            if (type.element >= 0) {
                ids.add(type.element);
            }
        }
        return loadElements(client, ids);
    }
}

package com.hdmapreforged;

import static java.lang.Math.*;
import static com.hdmapreforged.Tiles.*;

import java.util.*;

/**
 * Walking the way the game walks: a breadth-first search over 128×128 tiles around the player with directions in a
 * fixed order, so the drawn route lies on the tiles the player really walks.
 */
final class GameWalk {
    static final int HALF = 64;
    /** Well inside the search area. */
    static final int PIECE = 48;
    static final int[] DX = {-1, 1, 0, 0, -1, 1, -1, 1};
    static final int[] DY = {0, 0, -1, 1, -1, -1, 1, 1};

    /**
     * A step the walk may not take although the ground allows it: a gate the planner keeps shut (a guild's door below
     * its level), the Wilderness a route keeps out of. Null where none is.
     */
    interface Shut {
        boolean shut(int x, int y, int z, int dx, int dy);
    }

    static boolean open(CollisionMap map, Shut shut, int x, int y, int z, int dx, int dy) {
        return map.canStep(x, y, z, dx, dy) && (shut == null || !shut.shut(x, y, z, dx, dy));
    }

    /** A route's walk as the game would take it; pieces the game cannot do as short keep the route's tiles. */
    static int[] follow(CollisionMap map, Shut shut, int[] points) {
        if (points.length < 3 || isSea(points[0])) {
            return points;
        }
        int[] out = new int[points.length * 2];
        int n = 0;
        out[n++] = points[0];
        int i = 0;
        while (i < points.length - 1) {
            int j = i + 1;
            while (j + 1 < points.length && z(points[j + 1]) == z(points[i])
                && distance(points[i], points[j + 1]) <= PIECE) {
                j++;
            }
            var piece = z(points[j]) == z(points[i]) ? path(map, shut, out[n - 1], new int[]{points[j]}) : null;
            if (piece == null || piece.length > j - i + 1 || newObstacle(map, piece, points, i, j)) {
                piece = Arrays.copyOfRange(points, i, j + 1);
            }
            if (n + piece.length > out.length) {
                out = Arrays.copyOf(out, (n + piece.length) * 2);
            }
            System.arraycopy(piece, 1, out, n, piece.length - 1);
            n += piece.length - 1;
            i = j;
        }
        return Arrays.copyOf(out, n);
    }

    /** How far ahead one run pair (straight, then diagonal) is looked for. */
    static final int RUN = 64;

    /**
     * The walk in as few runs as the ground allows, as a player walks it: from each tile to the farthest one ahead that
     * one straight run and then one diagonal run reach in as many steps, so no time changes. That is the game's walk to
     * a clicked tile in the open: its search tries west, east, south, north before the diagonals, so the path goes
     * straight along the longer axis first, then diagonally; never diagonally first. Not through a door or onto an
     * obstacle the walk kept clear of.
     */
    static int[] straighten(CollisionMap map, Shut shut, int[] points) {
        if (points.length < 3 || isSea(points[0])) {
            return points;
        }
        int[] out = new int[points.length];
        int n = 0;
        out[n++] = points[0];
        int i = 0;
        while (i < points.length - 1) {
            int[] best = null;
            int to = i + 1;
            for (int j = min(points.length - 1, i + RUN); j > i + 1 && best == null; j--) {
                best = runs(map, shut, points, i, j);
                to = j;
            }
            if (best == null) {
                out[n++] = points[i + 1];
                i++;
                continue;
            }
            System.arraycopy(best, 1, out, n, best.length - 1);
            n += best.length - 1;
            i = to;
        }
        return Arrays.copyOf(out, n);
    }

    /**
     * From {@code points[i]} to {@code points[j]} by one straight run and then one diagonal run, in exactly
     * {@code j - i} steps over walkable ground, crossing no door and stepping on no obstacle that {@code points[i..j]}
     * does not; else null.
     */
    static int[] runs(CollisionMap map, Shut shut, int[] points, int i, int j) {
        int from = points[i], to = points[j], z = z(from), dx = x(to) - x(from), dy = y(to) - y(from);
        int steps = max(abs(dx), abs(dy));
        if (z(to) != z || steps != j - i) {
            return null;
        }
        int diagonal = min(abs(dx), abs(dy)), sx = Integer.signum(dx), sy = Integer.signum(dy);
        // The straight run goes along the longer axis.
        int ax = abs(dx) > abs(dy) ? sx : 0, ay = abs(dx) > abs(dy) ? 0 : sy;
        int[] path = new int[steps + 1];
        path[0] = from;
        int x = x(from), y = y(from);
        for (int k = 0; k < steps; k++) {
            boolean diagonalStep = k >= steps - diagonal;
            int mx = diagonalStep ? sx : ax, my = diagonalStep ? sy : ay;
            if (!open(map, shut, x, y, z, mx, my) || (mx == 0 || my == 0) && map.door(x, y, z, mx, my)
                && !crossed(points, i, j, x, y, mx, my)) {
                return null;
            }
            x += mx;
            y += my;
            path[k + 1] = pack(x, y, z);
            if (newObstacle(map, new int[]{path[k + 1]}, points, i, j)) {
                return null;
            }
        }
        return path;
    }

    /** Whether {@code points[i..j]} steps from (x, y) by (mx, my) itself (so a door it opens may be crossed). */
    static boolean crossed(int[] points, int i, int j, int x, int y, int mx, int my) {
        for (int k = i; k < j; k++) {
            if (x(points[k]) == x && y(points[k]) == y && x(points[k + 1]) == x + mx
                && y(points[k + 1]) == y + my) {
                return true;
            }
        }
        return false;
    }

    /** Whether {@code piece} crosses an obstacle (vines, rocks) that {@code points[i..j]} kept clear of. */
    static boolean newObstacle(CollisionMap map, int[] piece, int[] points, int i, int j) {
        for (int t : piece) {
            if (map.isObstacle(x(t), y(t), t)
                && Arrays.stream(points, i, j + 1).noneMatch(p -> p == t)) {
                return true;
            }
        }
        return false;
    }

    /**
     * The game's walk to the first of {@code goals} its search reaches (of a bank chest's sides, the one the game walks
     * to when it is clicked), both ends included; null when none is reached.
     */
    static int[] path(CollisionMap map, Shut shut, int from, int[] goals) {
        int z = z(from), ox = x(from) - HALF, oy = y(from) - HALF, size = HALF * 2;
        boolean[] wanted = new boolean[size * size];
        for (int to : goals) {
            int tx = x(to) - ox, ty = y(to) - oy;
            if (z(to) == z && tx >= 0 && ty >= 0 && tx < size && ty < size) {
                wanted[ty * size + tx] = true;
            }
        }
        // Direction each tile was reached from; -1 not reached.
        byte[] via = new byte[size * size];
        Arrays.fill(via, (byte) -1);
        int start = HALF * size + HALF;
        via[start] = 8;
        // Each tile is queued once: no boxing, as the walk is searched many times a route.
        int[] queue = new int[size * size];
        int head = 0, tail = 0;
        queue[tail++] = start;
        int goal = wanted[start] ? start : -1;
        while (head < tail && goal < 0) {
            int cell = queue[head++], cx = cell % size, cy = cell / size;
            for (int d = 0; d < 8; d++) {
                int nx = cx + DX[d], ny = cy + DY[d];
                if (nx < 0 || ny < 0 || nx >= size || ny >= size || via[ny * size + nx] >= 0) {
                    continue;
                }
                if (goal < 0 && open(map, shut, cx + ox, cy + oy, z, DX[d], DY[d])) {
                    via[ny * size + nx] = (byte) d;
                    queue[tail++] = ny * size + nx;
                    goal = wanted[ny * size + nx] ? ny * size + nx : -1;
                }
            }
        }
        if (goal < 0) {
            return null;
        }
        // Back from the goal (into the queue, done with), then each tile put before the one after it.
        int n = 0;
        for (int cell = goal; cell != start; n++) {
            queue[n] = cell;
            int d = via[cell];
            cell = (cell / size - DY[d]) * size + (cell % size - DX[d]);
        }
        int[] path = new int[n + 1];
        path[0] = from;
        for (int k = 0; k < n; k++) {
            path[n - k] = pack(queue[k] % size + ox, queue[k] / size + oy, z);
        }
        return path;
    }
}

package com.hdmapreforged;

import java.awt.*;
import java.util.*;
import net.runelite.api.coords.*;

/** One's grave while it stands, drawn over the other icons; clicked, its card offers a route there. Swing thread. */
final class GraveMarker implements MapView.Overlay, MapView.HitLayer {
    final MapView view;
    WorldPoint at;
    Poi grave;

    GraveMarker(MapView view) {
        this.view = view;
        view.addOverlay(this);
        view.hitLayers.add(this);
    }

    /** Null when no grave stands. */
    void set(WorldPoint at) {
        if (Objects.equals(at, this.at)) {
            return;
        }
        if (grave != null && view.selected() == grave) {
            view.select(null);
        }
        this.at = at;
        grave = null;
        view.repaint();
    }

    /** Made once the map list knows the grave's map (it may stand before the map's data came), again for a new list. */
    Poi grave() {
        var on = at == null ? null : view.mapOf(at);
        if (grave == null || grave.map != on) {
            grave = on == null ? null : new Poi(PoiType.GRAVE, "Your grave", at, on, null, Needs.NONE, "Grave", null, null);
        }
        return grave;
    }

    public void paint(Graphics2D g, Projection p) {
        Point center = center(p);
        if (center != null) {
            boolean selected = view.selected() == grave;
            double size = view.iconSize(p.zoom()) * (selected ? 1.25 : 1.1);
            PoiIcons.paintCached(g, PoiType.GRAVE, 0, center.x, center.y, size, selected ? 1 : 0, false);
        }
    }

    public Poi hit(Point point, Projection p) {
        Point center = center(p);
        return center != null && center.distance(point) <= view.iconSize(p.zoom()) * 0.6 ? grave : null;
    }

    Point center(Projection p) {
        var shown = grave();
        if (shown == null || !shown.isOn(p.map())) {
            return null;
        }
        var at = p.shown(shown.location);
        return new Point((int) p.screenX(at.getX() + 0.5), (int) p.screenY(at.getY() + 0.5));
    }
}

package com.hdmapreforged;

import lombok.*;
import net.runelite.client.party.messages.*;

/** A valuable drop a party member just got, sent once to the party. Values from other clients are checked. */
@AllArgsConstructor
public class HdMapPartyDrop extends PartyMemberMessage {
    /** Item id and quantity; its worth only for picking the sender's few (each receiver prices it itself). */
    private final int i, q;
    private final transient long v;
    /** Untradeable: picked first, as receivers list them (PartyMembers.BEST). */
    private final transient boolean u;

    /** -1 when not believable. */
    int item() {
        return i >= 0 && i < HdMapPartyState.MAX_ITEM ? i : -1;
    }

    int quantity() {
        return Math.max(1, q);
    }

    boolean untradeable() {
        return u;
    }

    long value() {
        return Math.max(0, Math.min(Integer.MAX_VALUE * 100L, v));
    }
}

package com.hdmapreforged;

import net.runelite.api.coords.*;
import net.runelite.client.party.messages.*;
import net.runelite.client.util.*;

/** Where a party member is. The class name is the message type on the party server; short field names keep it small. */
public class HdMapPartyLocation extends PartyMemberMessage {
    static final int MAX_COORDINATE = 16383, MAX_NAME = 12, MAX_RAW_NAME = 64;

    private final int x, y, p;
    /** World, 0 when unknown. */
    private final int w;
    private final String n;
    /** In a house (the point is its portal); else left out, as null. */
    private final Boolean h;

    HdMapPartyLocation(WorldPoint point, int world, String name, boolean house) {
        h = house ? true : null;
        x = point == null ? -1 : point.getX();
        y = point == null ? -1 : point.getY();
        p = point == null ? 0 : point.getPlane();
        w = world;
        n = name;
    }

    static HdMapPartyLocation offline() {
        return new HdMapPartyLocation(null, 0, null, false);
    }

    WorldPoint point() {
        return plausible(x, y, p) ? new WorldPoint(x, y, p) : null;
    }

    static boolean plausible(WorldPoint point) {
        return point != null && plausible(point.getX(), point.getY(), point.getPlane());
    }

    private static boolean plausible(int x, int y, int plane) {
        return x >= 0 && y >= 0 && x <= MAX_COORDINATE && y <= MAX_COORDINATE && plane >= 0 && plane <= 3;
    }

    boolean house() {
        return Boolean.TRUE.equals(h);
    }

    int world() {
        return w > 0 && w < 1000 ? w : 0;
    }

    String name() {
        return cleaned(n, false);
    }

    /**
     * Tags stripped (and, for a name from RuneLite's own party data, any stray {@code <} as well, so none of it is
     * ever taken as HTML in a Swing label); non-breaking spaces made plain, trimmed. Null if empty, too long raw, or
     * too long after.
     */
    static String cleaned(String raw, boolean stripBrackets) {
        if (raw == null || raw.length() > MAX_RAW_NAME) {
            return null;
        }
        String name = Text.removeTags(raw);
        if (stripBrackets) {
            name = name.replace('<', ' ');
        }
        name = name.replace('\u00a0', ' ').trim();
        return name.isEmpty() || name.length() > MAX_NAME ? null : name;
    }
}

package com.hdmapreforged;

import static java.lang.Math.*;

import java.util.*;
import java.util.function.*;
import net.runelite.client.party.messages.*;

/**
 * What a party member carries, wears and can do: whole on joining and at most every {@link PartyMapRules#WHOLE_TICKS},
 * else only what changed since, so a tick's change (a hit, a rune cast, experience) is a few numbers and goes every
 * tick. Short field names keep it small; values from other clients are checked before use.
 */
public class HdMapPartyState extends PartyMemberMessage {
    static final int INVENTORY = 28, EQUIPMENT = 14, SKILLS = 24;
    /** Item ids above this are not believed. */
    static final int MAX_ITEM = 100_000;
    static final int[] SIZES = {INVENTORY, INVENTORY, EQUIPMENT, SKILLS, SKILLS, SKILLS};

    /** Whether the parts are whole; else each holds what changed as index, value pairs (null: nothing did). */
    private final boolean w;
    /** A new start (the plugin, a login, maybe another account): no gain since the state had before. */
    private final boolean n;
    /** Inventory ids (-1 empty) and quantities, worn ids by slot, real and current levels, experience per skill. */
    private final int[] i, q, e, s, b, x;
    /** Run and special attack energy, 0 to 100. */
    private final int r, p;

    HdMapPartyState(boolean whole, boolean fresh, int[][] parts, int run, int special) {
        w = whole;
        n = fresh;
        i = parts[0];
        q = parts[1];
        e = parts[2];
        s = parts[3];
        b = parts[4];
        x = parts[5];
        r = run;
        p = special;
    }

    boolean whole() {
        return w;
    }

    boolean fresh() {
        return n;
    }

    /** No longer shared (the setting turned off, the plugin stopped): a whole one without parts. */
    static HdMapPartyState unshared() {
        return new HdMapPartyState(true, true, new int[SIZES.length][], 0, 0);
    }

    boolean isUnshared() {
        return w && i == null && s == null;
    }

    /** The parts in {@link #SIZES}' order: this one's whole, or its changes onto {@code before} (null when whole). */
    int[][] parts(int[][] before) {
        IntUnaryOperator item = id -> id >= 0 && id < MAX_ITEM ? id : -1;
        IntUnaryOperator level = v -> max(0, min(255, v));
        IntUnaryOperator[] checks = {item, v -> max(0, v), item, level, level, v -> max(0, min(200_000_000, v))};
        int[][] got = {i, q, e, s, b, x};
        int[][] out = new int[SIZES.length][];
        for (int k = 0; k < out.length; k++) {
            boolean whole = w || before == null;
            out[k] = whole ? new int[SIZES[k]] : before[k].clone();
            if (whole) {
                Arrays.fill(out[k], k == 0 || k == 2 ? -1 : 0);
            }
            int[] values = got[k] == null ? new int[0] : got[k];
            for (int n = 0; n < values.length - (whole ? 0 : 1); n += whole ? 1 : 2) {
                int at = whole ? n : values[n];
                if (at >= 0 && at < out[k].length) {
                    out[k][at] = checks[k].applyAsInt(values[whole ? n : n + 1]);
                }
            }
        }
        return out;
    }

    int runEnergy() {
        return max(0, min(100, r));
    }

    int specialAttack() {
        return max(0, min(100, p));
    }

    /** What changed from {@code before} to {@code now} as index, value pairs; null when nothing did. */
    static int[] changes(int[] before, int[] now) {
        int n = 0;
        for (int k = 0; k < now.length; k++) {
            n += before[k] != now[k] ? 1 : 0;
        }
        if (n == 0) {
            return null;
        }
        int[] pairs = new int[2 * n];
        for (int k = 0, at = 0; k < now.length; k++) {
            if (before[k] != now[k]) {
                pairs[at++] = k;
                pairs[at++] = now[k];
            }
        }
        return pairs;
    }
}

