    /** A fresh one each start: nothing of a run before carries over. */
    @Inject
    Provider<RouteFeature> routes;
    RouteFeature route;

    ExecutorService io;
    /** One task at a time so results arrive in order. */
    ExecutorService dataIo;
    final AtomicInteger dataGeneration = new AtomicInteger();
    final AtomicBoolean repaintPending = new AtomicBoolean();
    Filepath home;
    TileCache tiles;
    /** The server's lists and pictures, kept once seen. */
    ServerCache serverCache;
    /** The lists our map server publishes: where NPCs stand, the shops, drops and items on the ground. */
    volatile WorldData world = WorldData.NONE;
    /** Its data version; null before the first download. */
    volatile String worldVersion;
    /** A data version whose search.json could not be used, said once in the log. */
    volatile String worldRefused;
    /** When the server was last asked for its versions (map and data, one small file). */
    volatile long versionsAsked;
    /** Asked again at most this often while the search, a card or a route uses the world facts. */
    static final long VERSIONS_ASK_MS = 60 * 60_000L;
    volatile long versionsAskMs = VERSIONS_ASK_MS;
    /** And at a login, unless asked this shortly before (the start asks too). */
    static final long LOGIN_ASK_MS = 5 * 60_000L;
    /** Since the login screen: the next LOGGED_IN is a login, not the end of a loading screen or a world hop. */
    volatile boolean loggedOut = true;
    MapServer server;
    MapScreen screen, fullScreen;
    BigWindow fullMap;
    IconLayer[] gameIcons = new IconLayer[0];
    GraveMarker[] graves = new GraveMarker[0];
    final HotkeyListener mapKey = new HotkeyListener(() -> config.openMapKey()) {
        public void keyPressed(KeyEvent e) {
            // A key that types goes to the chat, an input box or an interface taking keys, not to the map.
            if (!config.openMapKey().matches(e) || !typingInGame(e)) {
                super.keyPressed(e);
            }
        }

        public void hotkeyPressed() {
            toggleFullMap();
        }
    };
    final KeyListener escape = new Escape();

    /** Escape closes the map over the game while it is open. */
    final class Escape extends KeyAdapter implements KeyListener {
        public void keyPressed(KeyEvent e) {
            var open = fullMap;
            if (e.getKeyCode() == KeyEvent.VK_ESCAPE && open != null && open.isOpen()) {
                e.consume();
                invokeLater(open::close);
            }
        }

        /** The map may stay open over the login screen. Not the map key: it would open the map while typing a name. */
        public boolean isEnabledOnLoginScreen() {
            return true;
        }
    }
    MapPanel panel;
    MapWindow window;
    NavigationButton button;
    WorldPoint lastPlayer;
    boolean atHome;
    /** Null until a version's maps and places are shown. */
    volatile String currentVersion;
    /** A map version whose files are on the way or read, not asked for again meanwhile. Data thread. */
    String loadingVersion;
    /** What the requirements of the data shown read; null before it loads. */
    volatile Unlocks.Watched watched;
    /** Each skill's real level as last seen, so only a level gained marks unlocks for a new look. Client thread. */
    final int[] realLevels = new int[Skill.values().length];
    /** Before a map version's files, or the server's versions, are asked for again. */
    static final long RETRY_MS = 60_000, MAX_RETRY_MS = 30 * RETRY_MS;
    /** Map versions that failed in a row. Data thread. */
    int failedMaps;
    /** The latest such request waiting, stopped when the plugin stops. */
    volatile Timer retry;
    /** Counts starts and stops, so late callbacks of an earlier run do nothing. */
    final AtomicInteger life = new AtomicInteger();
    volatile String wantedVersion;
    Unlocks unlocks;
    boolean unlocksDirty = true;
    int ticks, lastUnlockTick = -UNLOCK_TICKS, lastQuestTick = -QUEST_TICKS;

    @Provides
    MapConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(MapConfig.class);
    }

    /** When this throws, RuneLite calls shutDown, which undoes only what was made. */
    protected void startUp() throws Exception {
        int started = life.incrementAndGet();
        route = routes.get();
        currentVersion = null;
        loadingVersion = null;
        failedMaps = 0;
        // Once: party drops from 10K where the old default of 100K was kept (so little came through); a value one chose stays.
        if (configManager.getConfiguration(GROUP, "partyDrops10k") == null) {
            if (config.partyDropValue() == 100_000) {
                configManager.setConfiguration(GROUP, "partyDropValue", 10_000);
            }
            configManager.setConfiguration(GROUP, "partyDrops10k", true);
        }
        // Turned on at the login screen, the next login asks; turned on in the game, the next loading screen does not.
        loggedOut = client.getGameState() != LOGGED_IN;
        io = Executors.newFixedThreadPool(4, threads("Reimagined World Map tiles", Thread.NORM_PRIORITY));
        dataIo = Executors.newSingleThreadExecutor(threads("Reimagined World Map data", Thread.NORM_PRIORITY));
        home = getPluginDirectory();
        use(developerMode);
        // Not through RuneLite's shared disk cache: ours keeps the files, and version.json must never come stale.
        var http = httpClient.newBuilder().cache(null).build();
        server = new MapServer(http, gson);
        tiles = new TileCache(http, io, home.joinSegment("map-tiles"), this::tileLoaded);
        serverCache = new ServerCache(home.joinSegment("server-cache"), io);
        tiles.configure(config.diskCacheMb());

        var itemNames = new ItemNames(clientThread, itemManager);
        screen = new MapScreen(tiles, config, this::worldInUse, itemNames, this::togglePopOut);
        fullScreen = new MapScreen(tiles, config, this::worldInUse, itemNames, () -> fullMap.close());
        fullMap = new BigWindow(client, fullScreen, config.fullMapBounds(),
            bounds -> configManager.setConfiguration(GROUP, "fullMapBounds", bounds),
            key -> config.openMapKey().matches(key));
        keyManager.registerKeyListener(escape);
        keyManager.registerKeyListener(mapKey);
        panel = new MapPanel(() -> fullMap.open(), this::togglePopOut, this::showOnMap, party,
            fullScreen::placeName);
        button = NavigationButton.builder()
            .tooltip("Reimagined World Map")
            .icon(PoiIcons.icon(16, "NAVIGATION"))
            .priority(6)
            .panel(panel)
            .build();
        sidebar(config.sidebar());
        party.start(screen.view, fullScreen.view);
        // Where the house's picture is kept per account, and the thread that reads and writes it.
        route.yourHouse.houseFolder = home.joinSegment("house");
        route.yourHouse.houseIo = io;
        route.itemNames = itemNames;
        route.start(screen, fullScreen);
        route.setSidebar(panel::showRoute, this::showOnMap);
        panel.setTours(route.sidebarTours(panel::redoTours));
        gameIcons = new IconLayer[]{gameIconLayer(screen), gameIconLayer(fullScreen)};
        graves = new GraveMarker[]{new GraveMarker(screen.view), new GraveMarker(fullScreen.view)};
        clientThread.invoke(this::checkGrave);
        var pictures = new NpcImages((id, done) -> {
            String version = tiles.version;
            serverCache.bytes("npcs", version, id + ".png", fetch -> server.npcPictureBytes(version, id, fetch),
                bytes -> done.accept(decode(bytes)));
        });
        for (var on : new MapScreen[]{screen, fullScreen}) {
            on.view.linesChoice = value -> configManager.setConfiguration(GROUP, "linesOff", value);
            on.icons.set = (key, value) -> configManager.setConfiguration(GROUP, key, value);
            on.view.checkForMap = () -> runData(this::checkForMap);
            on.setNpcPictures(pictures);
        }

        versionsAsked = System.currentTimeMillis();
        // In developer mode, against a map server on this computer, every 30 seconds.
        versionsAskMs = developerMode ? 30_000L : VERSIONS_ASK_MS;
        // The screens start empty until a map version's files are had and read on the data thread.
        runData(() -> resolveVersions(false));
        // The game's pictures of teleports and runecrafting altars: an item's, or a sprite's (~id).
        PoiIcons.load = (id, done) -> {
            if (id > 0) {
                var image = itemManager.getImage(id);
                image.onLoaded(() -> done.accept(image));
            } else {
                spriteManager.getSpriteAsync(~id, 0, done);
            }
        };
        PoiIcons.loaded = this::refreshLater;
        whenGameLoaded(started, () -> GameIcons.load(client), PoiIcons::clearCache);
    }

    void whenGameLoaded(int started, BooleanSupplier load, Runnable after) {
        clientThread.invokeLater(() -> {
            if (started != life.get()) {
                return true;
            }
            if (client.getGameState().getState() < LOGIN_SCREEN.getState() || !load.getAsBoolean()) {
                return false;
            }
            after.run();
            refreshLater();
            return true;
        });
    }

    IconLayer gameIconLayer(MapScreen on) {
        var layer = new IconLayer(on.view, config::iconSize);
        on.view.addOverlay(layer);
        on.view.hitLayers.add(layer);
        on.view.badgeCover = layer::covers;
        return layer;
    }

    /** Daemon threads called {@code name} at {@code priority}, for the plugin's own executors. */
    static ThreadFactory threads(String name, int priority) {
        return runnable -> {
            Thread thread = new Thread(runnable, name);
            thread.setDaemon(true);
            thread.setPriority(priority);
            return thread;
        };
    }

    /** Also safe after a startUp that failed half-way: only what was made is undone. */
    protected void shutDown() {
        life.incrementAndGet();
        wantedVersion = null;
        retry(null);
        GameIcons.clear();
        PoiIcons.clearCache();
        PoiIcons.load = (id, done) -> { };
        PoiIcons.loaded = () -> { };
        party.stop();
        route.stop();
        if (button != null) {
            clientToolbar.removeNavigation(button);
        }
        dock();
        keyManager.unregisterKeyListener(escape);
        keyManager.unregisterKeyListener(mapKey);
        if (fullMap != null) {
            fullMap.dispose();
        }
        dataGeneration.incrementAndGet();
        if (screen != null) {
            screen.stop();
        }
        if (fullScreen != null) {
            fullScreen.stop();
        }
        if (io != null) {
            io.shutdownNow();
        }
        if (dataIo != null) {
            dataIo.shutdownNow();
        }
        if (tiles != null) {
            tiles.clear();
        }
        lastPlayer = null;
        unlocks = null;
        unlocksDirty = true;
        watched = null;
        Arrays.fill(realLevels, 0);
        // Nothing of the data is kept while the plugin is off: the files are on disk for the next start.
        world = WorldData.NONE;
        worldVersion = null;
        currentVersion = null;
        RouteFiles.clear();
        screen = null;
        gameIcons = new IconLayer[0];
        graves = new GraveMarker[0];
        fullScreen = null;
        fullMap = null;
        if (panel != null) {
            panel.stop();
        }
        panel = null;
        button = null;
    }

    void screens(Consumer<MapScreen> change) {
        invokeLater(() -> {
            if (screen != null) {
                change.accept(screen);
                change.accept(fullScreen);
            }
        });
    }

    @Subscribe
    public void onGameTick(GameTick tick) {
        ticks++;
        Player player = client.getLocalPlayer();
        if (player == null) {
            return;
        }
        var location = playerLocation(player);
        route.tick(location);
        var home = route.home();
        var outside = route.outside();
        // On the house's plan, or in a box at its portal while that plan is not known (a friend's house).
        boolean boxed = home != null && !HousePlan.contains(home.getX(), home.getY());
        // In a house the party sees its portal (the house's own place is a copy of the game's rooms).
        party.tick(home == null ? location : boxed ? home : outside, home != null, ticks);
        var shown = home != null ? home : location;
        if (shown != null && (!shown.equals(lastPlayer) || boxed != atHome)) {
            lastPlayer = shown;
            atHome = boxed;
            screens(s -> {
                s.view.home = boxed;
                s.view.outside = outside;
                s.view.setPlayer(shown);
            });
        }
        updateUnlocks();
    }

    /** As the game's maps show it: in instances the copied real location, on a boat the boat's main-world place. */
    WorldPoint playerLocation(Player player) {
        var local = player.getLocalLocation();
        var view = player.getWorldView();
        if (local != null && view != null && !view.isTopLevel()) {
            var boat = client.getTopLevelWorldView().worldEntities().byIndex(view.getId());
            local = boat != null ? boat.transformToMainWorld(local) : null;
        }
        if (local == null) {
            return null;
        }
        var at = WorldPoint.fromLocalInstance(client, local);
        // An instance copying a place on the map (the Watchtower's top floor): that place's tile.
        var place = InstanceCopies.place(at.getX(), at.getY(), at.getPlane());
        return place == null ? at : new WorldPoint(place[0], place[1], place[2]);
    }

    void updateUnlocks() {
        boolean due = unlocksDirty && ticks - lastUnlockTick >= UNLOCK_TICKS || ticks - lastUnlockTick >= QUEST_TICKS;
        var reads = watched;
        if (!due || reads == null || client.getGameState() != LOGGED_IN) {
            return;
        }
        boolean quests = ticks - lastQuestTick >= QUEST_TICKS;
        var previous = unlocks;
        unlocks = Unlocks.capture(client, reads, unlocks, quests);
        unlocksDirty = false;
        lastUnlockTick = ticks;
        if (quests) {
            lastQuestTick = ticks;
        }
        if (unlocks.sameAs(previous)) {
            // Varbits change all the time; rebuilding the detail card for nothing made the map stutter.
            unlocks = previous;
            return;
        }
        var current = unlocks;
        screens(s -> s.setUnlocks(current));
    }

    static boolean isWorldMapOption(String option) {
        return option != null && Text.removeTags(option).toLowerCase(Locale.ROOT).contains("world map");
    }

    /** A RuneLite-only orb entry; the game's "World Map" stays in the menu. Every entry of every frame: cheap tests first. */
    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event) {
        int widget = event.getActionParam1();
        if (!isOrb(widget) || !config.orbOpensMap() || !isWorldMapOption(event.getOption())) {
            return;
        }
        ourEntryAdded = true;
        // The orb can list several map options; one entry of ours is enough.
        if (ownEntryIndex(client.getMenu().getMenuEntries()) >= 0) {
            return;
        }
        client.getMenu().createMenuEntry(-1)
            .setOption(MENU_OPTION)
            .setTarget("")
            .setType(MenuAction.RUNELITE)
            .setParam1(widget)
            .onClick(entry -> toggleFullMap());
    }

    /** Our orb entry is in this frame's menu: the sort that follows has something to do. Client thread. */
    boolean ourEntryAdded;

    /**
     * Whether the game takes typed keys as text now: an input box is open (an amount, a bank search, the world map's
     * search, the settings' search: its key handler comes with its varbit, whatever mode the server opens it in) or the
     * chat takes letters (with Key Remapping's "Press Enter to Chat" shown it takes none), also while the chat is
     * closed. The game's own chat key script ignores keys when a dialogue hides the chat's lines. Set on the client
     * thread each client tick; the key thread only reads it.
     */
    volatile boolean gameTakesText;
    /**
     * Whether an open interface takes keys itself (the jewellery box's letters, a menu's numbers): looked at on the two
     * client ticks after one opens or closes, and every fifth tick besides, as its scripts may set its key handler
     * later than it loads. On those two ticks the game gets typed keys, so a key pressed at once never opens the map
     * past the interface.
     */
    volatile boolean takesKeys;
    volatile int interfacesChanged = 2;
    int clientTicks;

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event) {
        interfacesChanged = 2;
    }

    @Subscribe
    public void onWidgetClosed(WidgetClosed event) {
        interfacesChanged = 2;
    }

    @Subscribe
    public void onClientTick(ClientTick tick) {
        boolean text = false;
        if (client.getGameState() == LOGGED_IN) {
            boolean changed = interfacesChanged > 0;
            if (changed) {
                interfacesChanged--;
            }
            if (changed || ++clientTicks % 5 == 0) {
                takesKeys = modalTakesKeys();
            }
            var chat = client.getWidget(InterfaceID.Chatbox.UNIVERSE);
            var input = client.getWidget(InterfaceID.Chatbox.INPUT);
            text = client.getFocusedInputFieldWidget() != null || client.getVarcIntValue(VarClientID.MESLAYERMODE) != 0
                || client.getVarcIntValue(VarClientID.WORLDMAP_SEARCHING) == 1
                || client.getVarbitValue(VarbitID.FLOATER_IS_SEARCHING) != 0
                && client.getWidget(InterfaceID.Settings.UNIVERSE) != null
                || chat != null && chat.getOnKeyListener() != null && input != null && shown(InterfaceID.Chatbox.CHATDISPLAY)
                && shown(InterfaceID.Chatbox.MES_LAYER_HIDE) && client.getWidget(InterfaceID.Reportabuse.UNIVERSE) == null
                && !String.valueOf(input.getText()).contains("Press Enter to Chat");
        }
        gameTakesText = text;
    }

    /** Whether a modal interface open now (not the chat, the side panels or the game view) has a key handler. */
    boolean modalTakesKeys() {
        for (WidgetNode node : client.getComponentTable()) {
            if (node.getModalMode() == WidgetModalMode.NON_MODAL) {
                continue;
            }
            Widget w;
            for (int child = 0; child < 2000 && (w = client.getWidget(node.getId(), child)) != null; child++) {
                if (w.getOnKeyListener() != null && !w.isHidden()) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Not hidden by itself; a closed chat hides only its parents. */
    boolean shown(int component) {
        var w = client.getWidget(component);
        return w != null && !w.isSelfHidden();
    }

    /**
     * Whether the game takes this key: it types a character (no Ctrl, Alt or Meta) while the game takes text or an open
     * interface takes keys.
     */
    boolean typingInGame(KeyEvent e) {
        return e.getKeyChar() != KeyEvent.CHAR_UNDEFINED && !e.isControlDown() && !e.isAltDown() && !e.isMetaDown()
            && (gameTakesText || takesKeys || interfacesChanged > 0);
    }

    void toggleFullMap() {
        invokeLater(() -> {
            if (fullMap != null) {
                fullMap.toggle();
            }
        });
    }

    /** Keeps "Reimagined Map" as the orb's left-click option, as later entries would take the top; only reorders. */
    @Subscribe
    public void onPostMenuSort(PostMenuSort event) {
        if (!ourEntryAdded || client.isMenuOpen()) {
            return;
        }
        ourEntryAdded = false;
        var entries = client.getMenu().getMenuEntries();
        int ours = ownEntryIndex(entries);
        if (ours >= 0 && ours != entries.length - 1) {
            client.getMenu().setMenuEntries(moveToTop(entries, ours));
        }
    }

    static final String MENU_OPTION = "Reimagined Map";

    static boolean isOrb(int widget) {
        return widget == InterfaceID.Orbs.ORB_WORLDMAP || widget == InterfaceID.Orbs.WORLDMAP;
    }

    static int ownEntryIndex(MenuEntry[] entries) {
        for (int i = 0; i < entries.length; i++) {
            var entry = entries[i];
            if (entry.getType() == MenuAction.RUNELITE && MENU_OPTION.equals(entry.getOption())
                && isOrb(entry.getParam1())) {
                return i;
            }
        }
        return -1;
    }

    /** The last entry is the top of the menu, which is what a left click does. */
    static MenuEntry[] moveToTop(MenuEntry[] entries, int index) {
        var reordered = new ArrayList<>(Arrays.asList(entries));
        reordered.add(reordered.remove(index));
        return reordered.toArray(new MenuEntry[0]);
    }

    @Subscribe
    public void onStatChanged(StatChanged event) {
        int skill = event.getSkill().ordinal();
        if (realLevels[skill] != event.getLevel()) {
            realLevels[skill] = event.getLevel();
            unlocksDirty = true;
        }
    }

    /** Varbits change all the time; only those (and varps) a requirement reads matter, and the teleport timers. */
    @Subscribe
    public void onVarbitChanged(VarbitChanged event) {
        var reads = watched;
        if (reads != null && (reads.watches(event.getVarbitId()) || reads.watchesVarp(event.getVarpId()))
            || event.getVarpId() == AIDE_TELE_TIMER || event.getVarpId() == SLUG2_REGIONUID) {
            unlocksDirty = true;
        }
        if (event.getVarbitId() == VarbitID.GRAVESTONE_VISIBLE
            || event.getVarpId() == GRAVESTONE_CREATION_DEATH_COORD) {
            checkGrave();
        }
    }

    /** One's grave from the game: standing while GRAVESTONE_VISIBLE is not 0 (not a flag), on the tile one died on. */
    void checkGrave() {
        int coord = client.getVarpValue(GRAVESTONE_CREATION_DEATH_COORD);
        showGrave(client.getVarbitValue(VarbitID.GRAVESTONE_VISIBLE) != 0 && coord > 0 ? WorldPoint.fromCoord(coord)
            : null);
    }

    void showGrave(WorldPoint at) {
        invokeLater(() -> {
            for (var grave : graves) {
                grave.set(at);
            }
        });
    }

    /** HD World Markers drops every plugin's tiles on a profile change, as on a logout: the route's are sent again. */
    @Subscribe
    public void onProfileChanged(ProfileChanged event) {
        route.tileMarkersCleared();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        GameState game = event.getGameState();
        if (game == LOGGED_IN) {
            unlocksDirty = true;
            lastQuestTick = ticks - QUEST_TICKS;
            if (loggedOut) {
                // A game update's new map is taken at the next login.
                loggedOut = false;
                askVersions(LOGIN_ASK_MS);
            }
        }
        if (game == LOGIN_SCREEN || game == HOPPING || game == CONNECTION_LOST) {
            route.tileMarkersCleared();
        }
        if (game == LOGIN_SCREEN) {
            loggedOut = true;
            lastPlayer = null;
            unlocks = null;
            showGrave(null);
            screens(s -> {
                s.view.setPlayer(null);
                s.setUnlocks(null);
            });
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        // The house (per account) is written as it is seen: nothing for the map's tiles.
        if (!GROUP.equals(event.getGroup())
            || Set.of("fullMapBounds", RouteFeature.HOUSE_KEY, RouteFeature.PLAN_KEY, RouteFeature.BANK_KEY)
            .contains(event.getKey())) {
            return;
        }
        tiles.configure(config.diskCacheMb());
        switch (event.getKey()) {
            case "checkMapNow":
            case "downloadMapAgain":
                // Buttons as boxes: acted on when ticked, then unticked, so no profile keeps one ticked (a profile
                // switch posts every key that differs) and an untick does nothing.
                if ("true".equals(event.getNewValue())) {
                    configManager.setConfiguration(GROUP, event.getKey(), false);
                    if (event.getKey().equals("checkMapNow")) {
                        runData(this::checkForMap);
                    } else {
                        tiles.downloadAgain();
                    }
                }
                break;
            case "followPlayer":
                screens(s -> s.view.setFollowing(config.followPlayer()));
                break;
            case "linesOff":
                screens(s -> s.view.setLinesOff(config.linesOff()));
                return;
            case "iconsOff":
                screens(s -> s.view.setIconsOff(config.iconsOff()));
                return;
            case "sidebar":
                sidebar(config.sidebar());
                return;
        }
        refreshLater();
    }

    /** The panel's button in RuneLite's sidebar (setting). */
    void sidebar(boolean shown) {
        if (shown) {
            clientToolbar.addNavigation(button);
        } else {
            clientToolbar.removeNavigation(button);
        }
    }

    void tileLoaded() {
        if (repaintPending.compareAndSet(false, true)) {
            invokeLater(() -> {
                repaintPending.set(false);
                refresh();
            });
        }
    }

    void refreshLater() {
        invokeLater(this::refresh);
    }

    void refresh() {
        if (screen != null) {
            screen.view.repaint();
            fullScreen.view.repaint();
        }
    }

    /**
     * The map server's current map version and the world facts' data version, from one small answer; at the start the
     * remembered map version shows meanwhile (nothing is shown before a version's files are had). {@code now}: while
     * running, so the remembered one is not taken again (it may be the broken one). Data thread.
     */
    void resolveVersions(boolean now) {
        var known = ServerCache.known(home.joinSegment(ServerCache.KNOWN));
        if (known != null && !now) {
            useVersion(known);
        }
        int started = life.get();
        server.versions(versions -> runData(() -> {
            loadWorld(started, versions.data);
            if (started != life.get()) {
                return;
            }
            if (versions.map == null) {
                if (wantedVersion == null) {
                    // The first start, and no answer: nothing to show until the server answers.
                    retryLater(started, RETRY_MS, () -> resolveVersions(false));
                } else if (failedMaps > 0) {
                    // A failed version's retry, and no answer: asked again, further apart.
                    retryMap(started, wantedVersion);
                } else {
                    // A start on the version remembered, and no answer: asked again (a newer version, the search's
                    // data), not only an hour on.
                    retryLater(started, RETRY_MS, () -> resolveVersions(true));
                }
                if (wantedVersion != null && currentVersion == null) {
                    screens(s -> s.view.setMapUnavailable(true));
                }
                return;
            }
            useVersion(versions.map);
        }));
    }

    /**
     * The world facts, for what shows them (the search, a card, a route): asks the server for newer versions when
     * {@link #versionsAskMs} have passed since it last did, so nothing is fetched while nothing uses them.
     */
    WorldData worldInUse() {
        askVersions(versionsAskMs);
        return world;
    }

    /** Asks the server for its versions unless it did within {@code gapMs}; a newer map or data version is taken. */
    void askVersions(long gapMs) {
        long now = System.currentTimeMillis();
        if (now - versionsAsked >= gapMs) {
            versionsAsked = now;
            runData(() -> resolveVersions(true));
        }
    }

    /**
     * The map server's search.json of {@code version} (what the search shows, worked out there), when newer than the
     * one shown; read on the data thread. Without it, the next look ({@link #worldInUse}) asks again a minute later;
     * one in another format (an older or newer map server) is not used. Either is said once in the log.
     */
    void loadWorld(int started, String version) {
        if (version == null || started != life.get() || version.equals(worldVersion)) {
            return;
        }
        String file = WorldData.FILE + ".json";
        serverCache.bytes("data", version, file, fetch -> server.data(version, WorldData.FILE, fetch),
            bytes -> runData(() -> {
                var read = bytes == null ? null : WorldData.parse(gson, bytes);
                if (started != life.get()) {
                    return;
                }
                if (read != null) {
                    world = read;
                    worldVersion = version;
                    serverCache.prune("data", version);
                    return;
                }
                if (!version.equals(worldRefused)) {
                    worldRefused = version;
                    log.warn(bytes == null ? "No {} of data version {}" : "{} of data version {} is not in format "
                        + WorldData.FORMAT, file, version);
                }
                if (bytes == null) {
                    versionsAsked = System.currentTimeMillis() - versionsAskMs + RETRY_MS;
                } else {
                    worldVersion = version;
                }
            }));
    }

    /**
     * Shows a map version once its four files are had (kept on disk once seen, else the server's): its map list with
     * its region table, its places and its route tables, read here; its tiles switch with them. Until all four are
     * usable the version shown stays, and the server is asked again ({@link #retryMap}). Data thread.
     */
    void useVersion(String version) {
        int started = life.get();
        wantedVersion = version;
        if (version.equals(currentVersion)) {
            tiles.setVersion(version);
            refreshLater();
            return;
        }
        if (version.equals(loadingVersion)) {
            // A second check while its files or its tiles' changes are on the way.
            return;
        }
        loadingVersion = version;
        var files = new ArrayList<CompletableFuture<byte[]>>();
        for (String name : MAP_FILES) {
            var file = new CompletableFuture<byte[]>();
            serverCache.bytes("maps", version, name, fetch -> server.mapFile(version, name, fetch), file::complete);
            files.add(file);
        }
        CompletableFuture.allOf(files.toArray(new CompletableFuture<?>[0])).thenRun(() -> runData(() -> {
            if (started != life.get()) {
                return;
            }
            if (!version.equals(wantedVersion) || version.equals(currentVersion)) {
                loaded(version);
                return;
            }
            // The map list, its region table, the places and the route tables.
            var got = files.stream().map(CompletableFuture::join).toArray(byte[][]::new);
            boolean all = Arrays.stream(got).allMatch(Objects::nonNull);
            var maps = got[0] == null ? null : BaseMaps.parse(gson, MapServer.text(got[0]));
            Map<String, byte[]> routeFiles = null;
            MapData data = null;
            if (all && maps != null && maps.byId(BaseMap.SURFACE) != null) {
                try {
                    var unzipped = RouteFiles.unzip(got[3]);
                    // The planner's passages: a route.zip made before them would plan with no stairs or caves.
                    Objects.requireNonNull(unzipped.get("passages.tsv"));
                    maps.regions = Objects.requireNonNull(gson.fromJson(MapServer.text(got[1]), RegionTable.class));
                    maps.version = version;
                    // Its icons are drawn where its world map moves put them: its tables for this thread's read alone,
                    // the version shown keeps its own for the planner and the screens until this one is shown.
                    RouteFiles.READING.set(unzipped);
                    try {
                        data = MapData.read(gson, MapServer.text(got[2]), maps, version);
                    } finally {
                        RouteFiles.READING.remove();
                    }
                    routeFiles = unzipped;
                } catch (IOException | RuntimeException e) {
                }
            }
            if (data == null) {
                if (all) {
                    // Complete but unusable: the kept copies are passed over once, or every retry would read them.
                    MAP_FILES.forEach(name -> serverCache.stale.add("maps/" + version + "/" + name));
                }
                if (currentVersion == null) {
                    screens(s -> s.view.setMapUnavailable(true));
                }
                loaded(version);
                retryMap(started, version);
                return;
            }
            switchVersion(version, maps, data, routeFiles, started);
        }));
    }

    /** The load of {@code version} ended: shown, unusable or passed over. Data thread. */
    void loaded(String version) {
        if (version.equals(loadingVersion)) {
            loadingVersion = null;
        }
    }

    /**
     * A player's "Check for a new map": asks the server now. After failures the backoff starts over, so a click while
     * the server is down does not push the next retry further away. Data thread.
     */
    void checkForMap() {
        if (failedMaps > 0) {
            failedMaps = 1;
        }
        resolveVersions(true);
    }

    /**
     * Asks the server for its versions after an unusable {@code version}, as it may have replaced it: at once, then
     * 1, 2, 4... minutes apart, up to {@link #MAX_RETRY_MS}. Data thread.
     */
    void retryMap(int started, String version) {
        long gap = failedMaps == 0 ? 0 : Math.min(MAX_RETRY_MS, RETRY_MS << Math.min(failedMaps - 1, 5));
        failedMaps++;
        retryLater(started, gap, () -> {
            if (version.equals(wantedVersion)) {
                resolveVersions(true);
            }
        });
    }

    /** Runs {@code task} on the data thread after {@code delayMs} unless the plugin stopped meanwhile. */
    void retryLater(int started, long delayMs, Runnable task) {
        Timer timer = new Timer((int) delayMs, e -> runData(() -> {
            if (started == life.get()) {
                task.run();
            }
        }));
        timer.setRepeats(false);
        retry(timer);
        timer.start();
    }

    /** The waiting request becomes {@code next}; the one before is stopped. */
    void retry(Timer next) {
        Timer previous = retry;
        retry = next;
        if (previous != null) {
            previous.stop();
        }
    }

    void switchVersion(String version, BaseMaps maps, MapData data, Map<String, byte[]> routeFiles, int started) {
        var cache = tiles;
        String current = cache.version;
        if (current != null && !current.equals(version)) {
            // The tiles of the version in use carry over, but for those the server says changed.
            // On the data thread: the upgrade may remove many files, too long for OkHttp's shared callback threads.
            server.changes(version, current, changes -> runData(() -> {
                // A later run has its own tiles, and another version wanted keeps the folder shown.
                if (started != life.get()) {
                    return;
                }
                if (!version.equals(wantedVersion)) {
                    loaded(version);
                    return;
                }
                if (changes != null && changes.from.equals(current)) {
                    cache.upgrade(current, version, changes.changed, changes.removed);
                }
                publish(version, maps, data, routeFiles, started);
            }));
            return;
        }
        publish(version, maps, data, routeFiles, started);
    }

    /**
     * A version's tiles, maps, places and route tables to the screens, the planner and the requirements read; only now
     * is it remembered for the next start and are the other versions' kept files removed. Data thread.
     */
    void publish(String version, BaseMaps maps, MapData data, Map<String, byte[]> routeFiles, int started) {
        loaded(version);
        // Before the needs below: its gates and shortcuts are among them.
        RouteFiles.use(routeFiles);
        tiles.setVersion(version);
        int generation = dataGeneration.incrementAndGet();
        currentVersion = version;
        failedMaps = 0;
        ServerCache.remember(home.joinSegment(ServerCache.KNOWN), version);
        serverCache.prune("maps", version);
        serverCache.prune("npcs", version);
        screens(s -> s.view.setMapUnavailable(false));
        // The places' needs and those of the bundled gates and shortcuts: a quest not watched counts as done.
        var reads = new Unlocks.Watched(Stream.concat(Poi.flatten(data.pois).stream().flatMap(poi -> Stream.concat(
            poi.members().stream().map(member -> member.needs), poi.links().stream().map(link -> link.needs))),
            RouteSource.fixedNeeds().stream()).collect(Collectors.toList()));
        // Quest start icons show their quest's state.
        data.icons.stream().filter(icon -> icon.poi.type == PoiType.QUEST_START)
            .forEach(icon -> reads.add(icon.poi.name));
        watched = reads;
        route.setIcons(data.icons);
        clientThread.invokeLater(() -> unlocksDirty = true);
        var elements = data.icons.stream().filter(icon -> icon.element >= 0).map(icon -> icon.element)
            .collect(Collectors.toCollection(HashSet::new));
        whenGameLoaded(started, () -> GameIcons.loadElements(client, elements), () -> { });
        invokeLater(() -> {
            if (screen != null && generation == dataGeneration.get()) {
                // The game's icons with the data they belong to: a found shop is selected among them, a found passage
                // shown by the game's icon for that way in.
                for (var layer : gameIcons) {
                    layer.setIcons(data.icons);
                }
                screen.setData(maps, data);
                fullScreen.setData(maps, data);
            }
        });
        refreshLater();
        route.loadPlanner();
    }

    void runData(Runnable task) {
        TileCache.execute(dataIo, task);
    }

    void togglePopOut() {
        if (window != null) {
            dock();
            return;
        }
        window = new MapWindow(screen, this::dock);
        window.setVisible(true);
    }

    void dock() {
        var closing = window;
        window = null;
        if (closing != null) {
            closing.dispose();
        }
    }

    void showOnMap(WorldPoint point) {
        if (fullMap == null) {
            return;
        }
        fullMap.open();
        fullScreen.view.focus(point);
    }
}

package com.hdmapreforged;

import java.awt.*;
import java.awt.event.*;
import java.util.function.*;
import javax.swing.*;
import javax.swing.event.*;
import javax.swing.text.*;
import lombok.*;

/**
 * A text field that shows a grey hint while it is empty and not typed in, and a cross at its right end while it holds
 * text: clicked, it empties the field.
 */
@RequiredArgsConstructor
final class HintField extends JTextField {
    static final Color HINT = new Color(150, 150, 150);
    /** Width of the cross's part at the right end. */
    static final int CROSS = 18;

    final Supplier<String> hint;
    /** Run once the cross has emptied the field. */
    Runnable cleared = () -> {};

    {
        addMouseListener(new MouseAdapter() {
            public void mousePressed(MouseEvent e) {
                if (!getText().isEmpty() && e.getX() >= getWidth() - getInsets().right) {
                    setText("");
                    cleared.run();
                }
            }
        });
    }

    /** Typed text stays left of the cross. */
    public Insets getInsets() {
        var i = super.getInsets();
        return new Insets(i.top, i.left, i.bottom, i.right + CROSS);
    }

    protected void paintComponent(Graphics g) {
        super.paintComponent(g);
        boolean empty = getText().isEmpty();
        if (empty && isFocusOwner()) {
            return;
        }
        var g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        g2.setColor(HINT);
        if (empty) {
            var m = g2.getFontMetrics();
            g2.drawString(hint.get(), getInsets().left + 2, (getHeight() + m.getAscent() - m.getDescent()) / 2);
        } else {
            PoiIcons.glyph(g2, "CLEAR", getWidth() - getInsets().right + CROSS / 2, getHeight() / 2);
        }
        g2.dispose();
    }

    static void onEdit(JTextComponent field, Runnable edited) {
        field.getDocument().addDocumentListener(new DocumentListener() {
            public void insertUpdate(DocumentEvent e) {
                edited.run();
            }

            public void removeUpdate(DocumentEvent e) {
                edited.run();
            }

            public void changedUpdate(DocumentEvent e) {
                edited.run();
            }
        });
    }

    /** A key of a focused field: {@code action} when {@code when} holds, else the key is left to the window. */
    static void bind(JComponent field, int key, String name, Runnable action, BooleanSupplier when) {
        field.getInputMap().put(KeyStroke.getKeyStroke(key, 0), name);
        field.getActionMap().put(name, new AbstractAction() {
            public boolean isEnabled() {
                return when.getAsBoolean();
            }

            public void actionPerformed(ActionEvent e) {
                action.run();
            }
        });
    }
}

package com.hdmapreforged;

import static com.hdmapreforged.Tiles.*;

import java.io.*;
import java.util.*;
import java.util.stream.*;
import java.util.zip.*;

/**
 * One's own house as last seen there: where one can walk and what stands where. Its tiles are at {@link #X},
 * {@link #Y} plus the house's own place (its south-west room at chunk 2, wherever the game loads it), where no map of
 * the game lies, so routes walk through it like anywhere else ({@link CollisionMap#setHouse}); the surface map draws
 * it at {@link #DRAWN_X}, {@link #DRAWN_Y}. Immutable.
 */
final class HousePlan {
    static final int X = 12800, Y = 12800;
    /** The game's scene, 104 tiles square: the house lies within it. */
    static final int SIZE = 104;
    /** Where the world map draws it: the surface map's empty west edge. */
    static final int DRAWN_X = 896, DRAWN_Y = 3000, TILES = SIZE * SIZE;

    /**
     * Per floor, per tile (x * SIZE + y): 1 walkable, 2 wall north, 4 wall east, 8 door north, 16 door east, 32 part of
     * a thing west of it, 64 part of a thing south of it.
     */
    final byte[][] tiles;
    /** What stands where (by node): the portals, jewellery box, stairs and such, by their names in the game. */
    final Map<Integer, String> things;
    /** Where one arrives: north of the exit portal. */
    final int arrival;
    /** Per region of the plan (2 × 2) and floor: {@link CollisionMap}'s layers. */
    final long[][] layers = new long[16][];

    HousePlan(byte[][] tiles, Map<Integer, String> things, int arrival) {
        this.tiles = tiles;
        this.things = Collections.unmodifiableMap(new LinkedHashMap<>(things));
        this.arrival = arrival;
        for (int z = 0; z < 4; z++) {
            for (int i = 0; i < TILES; i++) {
                int x = i / SIZE, y = i % SIZE, bit = (x & 63) << 6 | (y & 63);
                for (int k = 0; k < 5; k++) {
                    if ((tiles[z][i] & 1 << k) != 0) {
                        int at = ((x >> 6) * 2 + (y >> 6)) * 4 + z;
                        if (layers[at] == null) {
                            layers[at] = new long[320];
                        }
                        layers[at][k * 64 + (bit >> 6)] |= 1L << (bit & 63);
                    }
                }
            }
        }
    }

    /** Only floor one can walk to from these nodes stays walkable: grass beyond the walls is not the house. */
    static void keepReachable(byte[][] tiles, List<Integer> from) {
        boolean[][] reached = new boolean[4][TILES];
        var queue = new ArrayDeque<Integer>();
        for (int node : from) {
            reach(tiles, reached, queue, contains(node) ? (x(node) - X) * SIZE + y(node) - Y : -1, z(node));
        }
        while (!queue.isEmpty()) {
            int at = queue.poll();
            for (int n : steps(tiles[at / TILES], at % TILES)) {
                reach(tiles, reached, queue, n, at / TILES);
            }
        }
        for (int z = 0; z < 4; z++) {
            for (int i = 0; i < TILES; i++) {
                tiles[z][i] &= reached[z][i] ? ~0 : ~1;
            }
        }
    }

    static void reach(byte[][] tiles, boolean[][] reached, ArrayDeque<Integer> queue, int i, int z) {
        if (i >= 0 && z >= 0 && z < 4 && !reached[z][i] && (tiles[z][i] & 1) != 0) {
            reached[z][i] = true;
            queue.add(z * TILES + i);
        }
    }

    /**
     * Where one stands to use a thing: on it (a glory on a wall), else each free tile beside its tiles with no wall
     * between (a portal against a wall is used from its room, not the next); the game walks to the first its search
     * reaches ({@link GameWalk#path}). Its tiles east and north of the first are marked 32 and 64; empty none.
     */
    int[] approach(int node) {
        int z = z(node), x0 = x(node) - X, y0 = y(node) - Y;
        if (!contains(node) || (tiles[z][x0 * SIZE + y0] & 1) != 0) {
            return contains(node) ? new int[]{node} : new int[0];
        }
        int w = 1, h = 1;
        while (x0 + w < SIZE && (tiles[z][(x0 + w) * SIZE + y0] & 32) != 0) {
            w++;
        }
        while (y0 + h < SIZE && (tiles[z][x0 * SIZE + y0 + h] & 64) != 0) {
            h++;
        }
        var sides = IntStream.builder();
        for (int i = 0; i < w * h; i++) {
            int at = (x0 + i / h) * SIZE + y0 + i % h;
            for (int n : steps(tiles[z], at)) {
                if (n >= 0 && (tiles[z][n] & 1) != 0) {
                    sides.add(pack(X + n / SIZE, Y + n % SIZE, z));
                }
            }
        }
        return sides.build().toArray();
    }

    /**
     * The tiles one steps to from {@code i} (north, east, south, west), -1 where a wall is: walls stand on a tile's
     * north and east edges, and doors let one through.
     */
    static int[] steps(byte[] floor, int i) {
        int x = i / SIZE, y = i % SIZE;
        return new int[]{y < SIZE - 1 && (floor[i] & 2) == 0 ? i + 1 : -1, x < SIZE - 1 && (floor[i] & 4) == 0 ? i + SIZE
            : -1, y > 0 && (floor[i - 1] & 2) == 0 ? i - 1 : -1, x > 0 && (floor[i - SIZE] & 4) == 0 ? i - SIZE : -1};
    }

    static int node(int sceneX, int sceneY, int plane) {
        return pack(X + sceneX, Y + sceneY, plane);
    }

    static boolean contains(int node) {
        return contains(x(node), y(node));
    }

    static boolean contains(int x, int y) {
        return x >= X && x < X + SIZE && y >= Y && y < Y + SIZE;
    }

    long[] layers(int region, int z) {
        int dx = (region >> 8) - (X >> 6), dy = (region & 255) - (Y >> 6);
        return dx < 0 || dx > 1 || dy < 0 || dy > 1 ? null : layers[(dx * 2 + dy) * 4 + z];
    }

    /** As kept per account: the tiles deflated in Base64, the arrival, then per thing "node TAB name". */
    String encode() {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (DeflaterOutputStream out = new DeflaterOutputStream(bytes)) {
            for (var floor : tiles) {
                out.write(floor);
            }
        } catch (IOException e) {
            return null;
        }
        StringBuilder text = new StringBuilder(Base64.getEncoder().encodeToString(bytes.toByteArray()))
            .append('\n').append(arrival);
        things.forEach((node, name) -> text.append('\n').append(node).append('\t').append(name));
        return text.toString();
    }

    /** Null when unreadable; things off the plan are left out. */
    static HousePlan decode(String text) {
        var lines = text.split("\n");
        try (InflaterInputStream in = new InflaterInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(lines[0])))) {
            var all = in.readNBytes(4 * TILES + 1);
            int arrival = Integer.parseInt(lines[1]);
            if (all.length != 4 * TILES || !contains(arrival)) {
                return null;
            }
            byte[][] tiles = new byte[4][];
            for (int z = 0; z < 4; z++) {
                tiles[z] = Arrays.copyOfRange(all, z * TILES, (z + 1) * TILES);
            }
            var things = new LinkedHashMap<Integer, String>();
            for (int i = 2; i < lines.length; i++) {
                var parts = lines[i].split("\t", 2);
                int node = Integer.parseInt(parts[0]);
                if (parts.length == 2 && contains(node) && parts[1].length() <= 2000) {
                    things.put(node, parts[1]);
                }
            }
            return new HousePlan(tiles, things, arrival);
        } catch (RuntimeException | IOException e) {
            return null;
        }
    }
}

package com.hdmapreforged;

import java.util.*;
import java.util.stream.*;

/** The house panel's choices to and from the house scan's words ("box:ornate", "glory", "xeric", "portal:Varrock"). */
final class HouseSettings {
    static final String PORTAL = "portal:";
    static final String NEXUS = "nexus:";
    /** The jewellery box tiers, as in "box:ornate". */
    static final String[] BOXES = {"none", "basic", "fancy", "ornate"};
    /** Both a spirit tree and a fairy ring: a spiritual fairy tree, or each in a superior garden of its own. */
    static final String BOTH = "spirit tree+fairy ring";
    /** The superior gardens' teleports: none, fairy ring, spirit tree, both. */
    static final String[] GARDENS = {"", "fairy ring", "spirit tree", BOTH};
    /** What {@link #BOTH} is: its fairy ring and its spirit tree. */
    static final List<String> PARTS = List.of(GARDENS[1], GARDENS[2]);
    /** The Achievement Gallery's mounted amulets, as the scan names them, and their teleports' group. */
    static final String[] MOUNTED = {"glory", "xeric", "digsite"};
    static final String[] MOUNTED_GROUPS = {"Amulet of glory", "Xeric's talisman", "Digsite pendant"};

    /** Whether a house with these features has this one ("both" has a spirit tree and a fairy ring). */
    static boolean has(Set<String> features, String feature) {
        return features.contains(feature)
            || features.contains(BOTH) && (GARDENS[1].equals(feature) || GARDENS[2].equals(feature));
    }

    /** {@code box}: a tier (any case), else none; {@code mounted}: of {@link #MOUNTED}. */
    static Set<String> features(String box, Set<String> mounted, int garden, boolean obelisk, String portals,
        String nexus) {
        var features = new LinkedHashSet<String>();
        String tier = box == null ? "none" : box.toLowerCase(Locale.ROOT);
        if (!tier.equals("none") && Set.of(BOXES).contains(tier)) {
            features.add("box:" + tier);
        }
        for (String amulet : MOUNTED) {
            if (mounted != null && mounted.contains(amulet)) {
                features.add(amulet);
            }
        }
        if (garden > 0 && garden < GARDENS.length) {
            features.add(GARDENS[garden]);
        }
        if (obelisk) {
            // In a superior garden of its own: a house may have several.
            features.add("obelisk");
        }
        add(features, PORTAL, portals);
        add(features, NEXUS, nexus);
        return features;
    }

    static String box(Set<String> features) {
        return BOXES[last(features, "box:", BOXES)];
    }

    static void add(Set<String> features, String prefix, String places) {
        for (String place : places == null ? new String[0] : places.split("[,;\\n]")) {
            if (!place.trim().isEmpty()) {
                features.add(prefix + place.trim());
            }
        }
    }

    /** Which of {@link #GARDENS}. */
    static int garden(Set<String> features) {
        return last(features, "", GARDENS);
    }

    /** The last of {@code choices} after the first (none) that the features have, with {@code prefix}; else 0. */
    static int last(Set<String> features, String prefix, String[] choices) {
        for (int i = choices.length - 1; i > 0; i--) {
            if (features.contains(prefix + choices[i])) {
                return i;
            }
        }
        return 0;
    }

    /** As the panel shows them: "Varrock, Falador"; {@code prefix} {@link #PORTAL} or {@link #NEXUS}. */
    static String places(Set<String> features, String prefix) {
        return features.stream().filter(f -> f.startsWith(prefix)).map(f -> f.substring(prefix.length()))
            .collect(Collectors.joining(", "));
    }
}

package com.hdmapreforged;

import java.util.*;
import lombok.*;
import lombok.experimental.*;

/**
 * The player-owned house is an instance far from its town, so routes start from its ways out: the exit portal and,
 * in the player's own house only, the portals and such seen there. Teleporting in or building mode means one's own
 * house; entering by a house portal may be a friend's. Client thread only.
 */
@Accessors(fluent = true)
final class HouseTracker {
    /** By varbit 2187 (POH_HOUSE_LOCATION). */
    static final RouteFiles.Table<int[][]> PORTALS = new RouteFiles.Table<>(() -> Pathfinder.list("house portals",
        p -> Arrays.copyOf(Pathfinder.ints(p), 2)).toArray(int[][]::new));
    static final int PORTAL_RADIUS = 12;
    /** How long a choice at a house portal is kept: the walk to the portal, not a later visit. */
    static final int CHOICE_TICKS = 30;

    @Getter
    boolean inside;
    int lastOutside = -1;
    @Getter
    int exit = -1;
    boolean own;
    /** Varbit 2187: the town of one's own house. */
    int location;
    /** The scene is to be looked through: the house's objects load before the tick that finds the player inside. */
    boolean scan;
    /** Building mode shows empty hotspots (door and stair spaces): not looked through then. */
    boolean building;
    /** Chosen at a house portal: above 0 one's own house, below 0 a friend's; counts down to 0 every tick. */
    int chosen;
    final Set<String> features = new LinkedHashSet<>();
    boolean featuresChanged;

    static boolean isTemplate(int x, int y) {
        // Where the game copies its rooms from.
        return x >= 1856 && x <= 2047 && y >= 7040 && y <= 7119;
    }

    static int portal(int location) {
        var portals = PORTALS.get();
        return location > 0 && location < portals.length ? Tiles.pack(portals[location][0], portals[location][1], 0) : -1;
    }

    static int portalNear(int node) {
        var portals = PORTALS.get();
        for (int i = 1; i < portals.length; i++) {
            if (Tiles.z(node) == 0 && Math.abs(Tiles.x(node) - portals[i][0]) <= PORTAL_RADIUS
                && Math.abs(Tiles.y(node) - portals[i][1]) <= PORTAL_RADIUS) {
                return i;
            }
        }
        return 0;
    }

    /** Every tick. */
    void update(int node, boolean instance, int houseLocation, boolean buildingMode) {
        location = houseLocation;
        building = buildingMode;
        boolean nowInside = instance && node >= 0 && isTemplate(Tiles.x(node), Tiles.y(node));
        if (nowInside && !inside) {
            int entered = lastOutside >= 0 ? portalNear(lastOutside) : 0;
            // Through a house portal: maybe a friend's house, unless the player chose their own there. Not known
            // where from (started in a house): not taken for one's own, or a friend's house would be kept as it.
            own = lastOutside >= 0 && (entered <= 0 || chosen > 0);
            exit = portal(own ? houseLocation : entered);
            scan = true;
            // A choice counts for one entry: back at the portal, a friend's house may be next.
            chosen = 0;
        }
        if (nowInside && buildingMode && !own) {
            own = true;
            scan = true;
        }
        if (!nowInside && node >= 0 && !instance) {
            lastOutside = node;
        }
        chosen -= Integer.signum(chosen);
        inside = nowInside;
    }

    boolean own() {
        return inside && own;
    }

    /** The portal of one's own house, -1 while its town is not known. */
    int portal() {
        return portal(location);
    }

    /** Whether to look through the scene for the house's features now: once per visit or reload of one's own house. */
    boolean takeScan() {
        boolean due = scan && own() && !building;
        scan &= !due;
        return due;
    }

    /** At a house portal: "Home", "Build mode" or "Go to your house" (true), or a friend's house (false). */
    void chose(boolean ownHouse) {
        chosen = ownHouse ? CHOICE_TICKS : -CHOICE_TICKS;
    }

    /** Looked through too early (building mode's spaces still there): again next tick. */
    void scanAgain() {
        scan = true;
    }

    /** The scene loaded again: building mode, or a teleport from a friend's house (only one's own is reached so). */
    void reloaded() {
        if (inside && !own) {
            own = true;
            exit = portal(location);
        }
        scan = inside;
    }

    /** Remembered only in the player's own house, not in building mode (its empty spaces); true when this added one. */
    boolean seen(String objectName) {
        String feature = !own() || building || objectName == null ? null : feature(objectName);
        boolean added = feature != null && features.add(feature);
        featuresChanged |= added;
        return added;
    }

    static String feature(String objectName) {
        String n = objectName.trim(), lower = n.toLowerCase(Locale.ROOT);
        if (lower.endsWith(" space")) {
            // Building mode's empty spaces ("Jewellery box space"): nothing built there.
            return null;
        }
        if (lower.startsWith("portal nexus: ")) {
            // A place of the nexus, as the scan names it: apart from the portals.
            return "nexus:" + n.substring("portal nexus: ".length()).trim();
        }
        if (lower.endsWith(" portal") && !lower.startsWith("exit") && !lower.equals("portal") && !lower.contains("nexus")) {
            return "portal:" + n.substring(0, n.length() - " portal".length()).trim();
        }
        if (lower.contains("jewellery box")) {
            return lower.startsWith("ornate") ? "box:ornate" : lower.startsWith("fancy") ? "box:fancy" : "box:basic";
        }
        return lower.equals("fairy ring") || lower.equals("spirit tree") || lower.equals("obelisk") ? lower
            : lower.equals("spiritual fairy tree") ? "spirit tree+fairy ring"
            : lower.contains("amulet of glory") ? "glory" : lower.contains("xeric's talisman") ? "xeric"
            : lower.contains("digsite pendant") ? "digsite" : null;
    }

    Set<String> features() {
        return Collections.unmodifiableSet(features);
    }

    void restore(Set<String> saved) {
        features.clear();
        var known = Pathfinder.list("house features");
        for (String f : saved) {
            // Without the map version's list (not come yet, or an older version) all are kept, as they are saved back.
            if (f.startsWith("portal:") || f.startsWith("nexus:") || f.startsWith("box:") || known.isEmpty()
                || known.contains(f)) {
                features.add(f);
            }
        }
        featuresChanged = false;
    }

    boolean takeChanged() {
        boolean changed = featuresChanged;
        featuresChanged = false;
        return changed;
    }

    void replaceFeatures(Collection<String> known) {
        features.clear();
        features.addAll(known);
        featuresChanged = false;
    }

    void reset() {
        inside = false;
        lastOutside = -1;
        exit = -1;
        own = false;
        location = 0;
        scan = false;
        chosen = 0;
        replaceFeatures(Set.of());
    }
}

package com.hdmapreforged;

import static com.hdmapreforged.PoiType.*;
import static java.lang.Math.*;

import lombok.*;
import java.awt.*;
import java.awt.geom.*;
import java.awt.image.*;
import java.util.*;
import java.util.List;
import java.util.function.*;
import net.runelite.api.coords.*;
import com.hdmapreforged.MapData.Icon;

/**
 * Draws the game's own map icons (their sprites, {@link GameIcons}) where places.json puts them, hoverable and
 * clickable; only the hovered or selected one gets a ring. Where one stands on an icon of ours for the same thing,
 * ours is not drawn ({@link #covers}); one for a way in stands for the planner's passage there too, ringed when that is
 * selected. They are at least 15 px, more where the map enlarges its most detailed tiles, centred 1.5 of the tiles'
 * pixels left of and above their spot's south-west corner, from tile level 0 in; the ground floor shows every floor's
 * above ground and where the game's map draws a place's floors flat (Keldagrim), upper floors only their own.
 */
@RequiredArgsConstructor
final class IconLayer implements MapView.Overlay, MapView.HitLayer {
    static final double ICON_PIXELS = 15;

    final MapView view;
    /** By 64×64 region, so a frame or mouse move only looks near the view. */
    Map<Integer, List<Icon>> byRegion = new HashMap<>();
    /** One icon per spot with a game sprite, by region. */
    Map<Integer, List<Icon>> drawnByRegion = new HashMap<>();
    Map<Poi, List<Icon>> byPoi = new IdentityHashMap<>();
    /**
     * Game sprites scaled once per element and size, as zooming goes back and forth between a few sizes: made again at
     * each change of size, the first frame of each drew some 400 new images (60 ms on an accelerated pipeline).
     */
    final Map<Long, BufferedImage> scaled = new HashMap<>();
    /** Past about 4 MB of sprites (1 << 20 pixels) the sizes kept start again. */
    int scaledPixels;
    /** Made this frame: at a new size the rest are drawn at a size made before, and follow in the next frames. */
    int madeNow;
    boolean later;
    static final int MADE_PER_FRAME = 48;
    /** Our icons standing on a game icon of the same thing, and our passages on the game's icon for that way in. */
    Map<Poi, Icon> covering = new IdentityHashMap<>();
    /** Icons made for the game's icons (not ours), for their labels. */
    Map<Poi, Icon> created = new IdentityHashMap<>();

    /** The size our icons are drawn at; the game's are drawn as large. */
    final IntSupplier size;

    /**
     * As large as ours at a zoom, never smaller than {@link #ICON_PIXELS} times the tiles' scale (above 1 where the map
     * enlarges its most detailed tiles), in whole times the game's 15 pixels: the nearest, at least once. Pixel art
     * stays even: at 20 a 15-pixel icon had every third pixel doubled, and made smaller it was smoothed.
     */
    double drawnSize(Projection projection) {
        return drawnSize(projection.zoom(), size.getAsInt());
    }

    /** The same for a zoom and the icon size set: our pixel-art icons (the game's pictures) are drawn as large. */
    static double drawnSize(double zoom, int iconSize) {
        double wanted = max(ICON_PIXELS * scale(zoom), iconSize * MapView.iconScale(zoom));
        return ICON_PIXELS * max(1, round(wanted / ICON_PIXELS));
    }

    static int region(int x, int y) {
        return (x >> 6) << 16 | (y >> 6) & 0xffff;
    }

    List<List<Icon>> near(Map<Integer, List<Icon>> grid, Projection p,
        double left, double top, double right, double bottom) {
        double scale = p.screenX(1) - p.screenX(0), x0 = p.screenX(0), y0 = p.screenY(0);
        int minX = (int) floor((left - x0) / scale) - 1, maxX = (int) ceil((right - x0) / scale) + 1;
        int maxY = (int) ceil((y0 - top) / scale) + 1, minY = (int) floor((y0 - bottom) / scale) - 1;
        var found = new ArrayList<List<Icon>>();
        if ((long) (maxX - minX) * (maxY - minY) > 4_000_000_000L) {
            found.addAll(grid.values());
            return found;
        }
        for (int rx = minX >> 6; rx <= maxX >> 6; rx++) {
            for (int ry = minY >> 6; ry <= maxY >> 6; ry++) {
                var list = grid.get(rx << 16 | ry & 0xffff);
                if (list != null) {
                    found.add(list);
                }
            }
        }
        return found;
    }

    /** Swing thread only. */
    void setIcons(List<Icon> icons) {
        var made = new IdentityHashMap<Poi, Icon>();
        var cover = new IdentityHashMap<Poi, Icon>();
        var grid = new HashMap<Integer, List<Icon>>();
        var drawnGrid = new HashMap<Integer, List<Icon>>();
        var poiIcons = new IdentityHashMap<Poi, List<Icon>>();
        var spots = new HashSet<Long>();
        for (var icon : icons) {
            // Ours standing on the game's icon for it: the game's is drawn instead, once its sprite is there.
            (icon.own ? cover : made).put(icon.poi, icon);
            int key = region(icon.drawn.getX(), icon.drawn.getY());
            grid.computeIfAbsent(key, k -> new ArrayList<>()).add(icon);
            poiIcons.computeIfAbsent(icon.poi, k -> new ArrayList<>(1)).add(icon);
            if (icon.poi.type == FAIRY_RING && icon.kind != null && icon.kind.startsWith("Fairy ring")) {
                // Ours, not the game's transport arrow: kept, as the game's is read only for elements not had. Only a
                // ring's own key: two in Zanaris stand on the Transportation key that boats and the like share.
                GameIcons.ELEMENT_SPRITES.put(icon.element, GameIcons.FAIRY_RING);
            }
            long spot = (long) icon.drawn.getX() << 32 | (long) icon.drawn.getY() << 2 | icon.drawn.getPlane();
            if (icon.element >= 0 && spots.add(spot)) {
                drawnGrid.computeIfAbsent(key, k -> new ArrayList<>()).add(icon);
            }
        }
        // A passage of ours chosen (in the search, among a kind's places) rings the game's icon for that way in rather
        // than being drawn over it ("Mining Guild basement" drew the game's dungeon icon, an exclamation mark, on the
        // map link). A click on the game's icon still selects the game's own place, which knows where its link leads.
        for (var icon : icons) {
            for (var poi : icon.covers) {
                if (cover.putIfAbsent(poi, icon) == null) {
                    poiIcons.computeIfAbsent(poi, k -> new ArrayList<>(1)).add(icon);
                }
            }
        }
        covering = cover;
        created = made;
        byRegion = grid;
        drawnByRegion = drawnGrid;
        byPoi = poiIcons;
        scaled.clear();
        scaledPixels = 0;
        view.searchExtras = new ArrayList<>(made.keySet());
        view.repaint();
    }

    /** {@code last}: the hovered and selected, drawn after the rest so none lies over them. */
    void paintLarger(Graphics2D g, Projection projection, List<Icon> last) {
        if (!showsAny(projection)) {
            return;
        }
        double drawn = drawnSize(projection);
        int px = (int) round(drawn);
        if (px <= 0) {
            return;
        }
        double r = drawn / 2 + 1;
        madeNow = 0;
        later = false;
        for (var list : near(drawnByRegion, projection, -r, -r, projection.width() + r,
            projection.height() + r)) {
            for (var icon : list) {
                double sx = projection.screenX(icon.drawn.getX()), sy = projection.screenY(icon.drawn.getY());
                if (!(sx < -r - 2 || sy < -r - 2 || sx > projection.width() + r + 2 || sy > projection.height() + r + 2
                    || last.contains(icon))) {
                    paintIcon(g, projection, icon, px, drawn);
                }
            }
        }
        for (var icon : last) {
            paintIcon(g, projection, icon, px, drawn);
        }
        if (later) {
            view.repaint();
        }
    }

    void paintIcon(Graphics2D g, Projection projection, Icon icon, int px, double drawn) {
        if (!onView(icon, projection) || hidden(icon)) {
            return;
        }
        BufferedImage sprite = sized(icon.element, px, view.locked(icon.poi));
        if (sprite == null) {
            return;
        }
        var c = center(icon, projection);
        g.drawImage(sprite, (int) round(c.getX() - sprite.getWidth() / 2.0),
            (int) round(c.getY() - sprite.getHeight() / 2.0), null);
        Color dot = view.filter.questStatus ? quest(icon) : null;
        if (dot != null) {
            var spot = PlayerMarker.circle(c.getX() + drawn * 0.35, c.getY() + drawn * 0.35, max(3, drawn * 0.18));
            g.setColor(dot);
            g.fill(spot);
            g.setColor(Color.BLACK);
            g.draw(spot);
        }
    }

    /**
     * A game sprite at {@code px}: itself at its own size, else enlarged by whole times, once per size. Past a frame's
     * share, one already made at the next size down or up stands in: at a change of size making all at once drew some
     * 400 new images in one frame (55 ms on an accelerated pipeline, which uploads each).
     */
    BufferedImage sized(int element, int px, boolean locked) {
        BufferedImage sprite = GameIcons.element(element);
        if (sprite == null) {
            return null;
        }
        if (locked) {
            // Its own sizes, apart from the sprite's.
            sprite = PoiIcons.locked(sprite);
            element = ~element;
        }
        int own = max(sprite.getWidth(), sprite.getHeight()), times = max(1, round((float) px / own));
        if (times == 1) {
            return sprite;
        }
        BufferedImage cached = scaled.get(key(element, times));
        if (cached != null) {
            return cached;
        }
        if (madeNow >= MADE_PER_FRAME) {
            BufferedImage near = scaled.getOrDefault(key(element, times - 1), scaled.get(key(element, times + 1)));
            if (near != null || times == 2) {
                later = true;
                return near != null ? near : sprite;
            }
        }
        madeNow++;
        int w = sprite.getWidth() * times, h = sprite.getHeight() * times;
        BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
        var g = out.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
        g.drawImage(sprite, 0, 0, w, h, null);
        g.dispose();
        scaledPixels += w * h;
        if (scaledPixels > 1 << 20) {
            scaled.clear();
            scaledPixels = w * h;
        }
        scaled.put(key(element, times), out);
        return out;
    }

    static long key(int element, int times) {
        return (long) times << 32 | element & 0xffffffffL;
    }

    static int tileLevel(double zoom) {
        return (int) max(TileCache.MIN_ZOOM, min(TileCache.MAX_ZOOM, ceil(zoom - 1e-6)));
    }

    /**
     * Of the zoom's own tile level, not the coarser one a large window draws past the memory cap: our tiles hold no
     * icons for the sprites to cover, and following that level drew them up to twice as large, unevenly.
     */
    static double scale(double zoom) {
        return pow(2, zoom - tileLevel(zoom));
    }

    boolean shows(Icon icon, Projection projection) {
        return showsAny(projection) && onView(icon, projection) && !hidden(icon);
    }

    /** A quest start icon's dot (see {@link Unlocks#questColor}), else null. */
    Color quest(Icon icon) {
        var unlocks = view.unlocks;
        return icon.poi.type != QUEST_START || unlocks == null ? null : unlocks.questColor(icon.poi.name);
    }

    /** Its kind hidden in the Icons panel, or a finished quest's start hidden. */
    boolean hidden(Icon icon) {
        return view.iconsOff.contains(icon.toggle) || quest(icon) == Color.GREEN && view.filter.hideCompleted;
    }

    boolean showsAny(Projection projection) {
        // From tile level 0 on.
        return projection.map() != null && tileLevel(projection.zoom()) >= 0;
    }

    /** On the map in view and its floor, or on the ground floor's view a floor drawn flat on it. */
    static boolean onView(Icon icon, Projection projection) {
        var map = projection.map();
        return (map.id == BaseMap.FULL || icon.map == map)
            && (icon.drawn.getPlane() == projection.plane()
                // Ground floor tiles show the floors above; underground only where the game's map draws a place's
                // floors flat (Keldagrim's houses), floors on one spot being other places elsewhere.
                || projection.plane() == 0 && (icon.drawn.getY() < MapView.UNDERGROUND_Y || icon.flat));
    }

    /** {@link #covers} for a frame, the settings read once. */
    Predicate<Poi> covers(Projection projection) {
        if (!showsAny(projection)) {
            return poi -> false;
        }
        return poi -> {
            var icon = covering.get(poi);
            return icon != null && !view.iconsOff.contains(icon.toggle) && GameIcons.element(icon.element) != null
                && onView(icon, projection);
        };
    }

    static Point2D center(Icon icon, Projection projection) {
        // -1.5 pixels at the tile level's own size.
        double offset = -1.5 * scale(projection.zoom());
        return new Point2D.Double(projection.screenX(icon.drawn.getX()) + offset,
            projection.screenY(icon.drawn.getY()) + offset);
    }

    public Poi hit(Point point, Projection projection) {
        var icon = iconAt(point, projection);
        return icon == null ? null : icon.poi;
    }

    /** The game icon under a point, nearest middle wins; null if none. */
    Icon iconAt(Point point, Projection projection) {
        if (!showsAny(projection)) {
            return null;
        }
        double reach = drawnSize(projection) / 2 + 1;
        Icon best = null;
        double bestDistance = reach;
        for (var list : near(byRegion, projection, point.x - reach - 8, point.y - reach - 8,
            point.x + reach + 8, point.y + reach + 8)) {
            for (var icon : list) {
                double sx = projection.screenX(icon.drawn.getX()), sy = projection.screenY(icon.drawn.getY());
                if (abs(sx - point.x) > reach + 4 || abs(sy - point.y) > reach + 4
                    || !onView(icon, projection) || hidden(icon)) {
                    continue;
                }
                var c = center(icon, projection);
                double d = c.distance(point);
                if (d <= bestDistance) {
                    best = icon;
                    bestDistance = d;
                }
            }
        }
        return best;
    }

    public Point2D labelAnchor(Poi poi, Projection projection) {
        var c = iconCenter(poi, projection);
        return c == null ? null : new Point2D.Double(c.getX(), c.getY() + drawnSize(projection) / 2 + 5);
    }

    public Point2D iconCenter(Poi poi, Projection projection) {
        var icon = created.get(poi);
        if (icon == null && covers(projection).test(poi)) {
            icon = covering.get(poi);
        }
        return icon == null ? null : center(icon, projection);
    }

    /** Draws the game's sprites once read from the client; then rings the hovered and selected. */
    public void paint(Graphics2D g, Projection projection) {
        var ofSelected = byPoi.getOrDefault(view.selected(), Collections.emptyList());
        var ringed = new ArrayList<>(byPoi.getOrDefault(view.hovered(), Collections.emptyList()));
        // The selected's last, on top. A passage's is the game's icon for it, which may be the one hovered.
        ringed.removeAll(ofSelected);
        ringed.addAll(ofSelected);
        if (GameIcons.hasElements()) {
            paintLarger(g, projection, ringed);
        }
        // A pixel ring following the icon's outline, enlarged with it: yellow round the selected, white round the hovered.
        double times = max(1, round(drawnSize(projection) / ICON_PIXELS)), r = (ICON_PIXELS / 2 + 4) * times;
        for (var icon : ringed) {
            if (!shows(icon, projection)) {
                continue;
            }
            var c = center(icon, projection);
            if (c.getX() < -r || c.getY() < -r || c.getX() > projection.width() + r || c.getY() > projection.height() + r) {
                continue;
            }
            var sprite = GameIcons.element(icon.element);
            if (sprite != null) {
                PoiIcons.pixels(g, PoiIcons.outline(sprite, PoiIcons.RINGS[ofSelected.contains(icon) ? 1 : 2], times),
                    c.getX(), c.getY(), times);
            }
        }
    }
}

package com.hdmapreforged;

import java.awt.*;
import java.awt.image.*;
import java.util.*;
import java.util.function.*;
import javax.swing.*;
import lombok.*;

/** The map's Icons panel: how icons show, and each kind of icon on or off by itself, under its group. Swing thread. */
@RequiredArgsConstructor
final class IconPanel {
    final MapConfig config;
    /** Builds the panel again where it shows. */
    final Runnable changed;
    /** Writes a setting (the plugin's ConfigManager). */
    BiConsumer<String, Object> set = (key, value) -> { };
    /** Each group's kinds on the map, by name, with a picture to know them by. */
    final Map<Layer, Map<String, Supplier<BufferedImage>>> kinds = new EnumMap<>(Layer.class);
    /** Groups unfolded. */
    final Set<Layer> open = EnumSet.noneOf(Layer.class);

    void setData(MapData data) {
        kinds.clear();
        for (var poi : Poi.flatten(data.pois)) {
            for (var member : data.hidden.contains(poi) ? Collections.<Poi>emptyList() : poi.members()) {
                add(member.type.layer, member.toggle(), () -> {
                    var picture = PoiIcons.picture(member.picture);
                    return picture != null ? picture : PoiIcons.image(member.type, 15);
                });
            }
        }
        for (var icon : data.icons) {
            add(icon.group, icon.toggle, () -> {
                var sprite = GameIcons.element(icon.element);
                return sprite != null ? sprite : PoiIcons.image(icon.poi.type, 15);
            });
        }
        changed.run();
    }

    void add(Layer group, String name, Supplier<BufferedImage> picture) {
        kinds.computeIfAbsent(group, k -> new TreeMap<>(String.CASE_INSENSITIVE_ORDER)).putIfAbsent(name, picture);
    }

    Set<String> off() {
        return new TreeSet<>(Arrays.asList(config.iconsOff().split("\n")));
    }

    void save(Set<String> off) {
        off.remove("");
        set.accept("iconsOff", String.join("\n", off));
        changed.run();
    }

    JComponent section(int width) {
        var panel = SearchResults.column();
        panel.add(check("Quest status", PoiType.t("t26"),
            config.questStatus(), on -> set.accept("questStatus", on)));
        panel.add(check("Hide completed quests", "No quest start icons for finished quests",
            config.hideCompletedQuests(), on -> set.accept("hideCompletedQuests", on)));
        panel.add(check("Mark what I can't use", PoiType.t("t27"), config.markLocked(), on -> set.accept("markLocked", on)));
        panel.add(check("Only what I can use", PoiType.t("t28"), config.onlyUsable(), on -> set.accept("onlyUsable", on)));
        var size = new JSpinner(new SpinnerNumberModel(Math.max(10, Math.min(40, config.iconSize())), 10, 40, 1));
        size.setMaximumSize(size.getPreferredSize());
        size.addChangeListener(e -> set.accept("iconSize", size.getValue()));
        panel.add(TourPanel.row(TourPanel.text("Icon size", Floating.LIGHT, 60), size));
        var off = off();
        kinds.forEach((group, named) -> {
            boolean unfolded = open.contains(group);
            var fold = SearchResults.link(unfolded ? "▾" : "▸", () -> {
                if (!open.remove(group)) {
                    open.add(group);
                }
                changed.run();
            }, 12);
            var all = check(group.title + " (" + named.size() + ")", "Every kind below on or off",
                named.keySet().stream().noneMatch(off::contains), on -> {
                    // As saved now: the other map's panel may have changed it meanwhile.
                    var now = off();
                    now.removeAll(named.keySet());
                    if (!on) {
                        now.addAll(named.keySet());
                    }
                    save(now);
                });
            SearchResults.bold(all);
            SearchResults.add(panel, 6, TourPanel.row(fold, all));
            (unfolded ? named : Map.<String, Supplier<BufferedImage>>of()).forEach((name, picture) -> {
                var image = picture.get();
                var icon = new JLabel(new ImageIcon(image.getWidth() > 17
                    ? image.getScaledInstance(15, 15, Image.SCALE_SMOOTH) : image));
                icon.setBorder(BorderFactory.createEmptyBorder(0, 16, 0, 0));
                panel.add(TourPanel.row(icon, check(name, null, !off.contains(name), on -> {
                    var now = off();
                    if (on) {
                        now.remove(name);
                    } else {
                        now.add(name);
                    }
                    save(now);
                })));
            });
        });
        return panel;
    }

    /** {@code text} may be a kind's name from places.json: never rendered as HTML. */
    static JCheckBox check(String text, String tip, boolean on, Consumer<Boolean> action) {
        var box = new JCheckBox((String) null, on);
        box.putClientProperty("html.disable", Boolean.TRUE);
        box.setText(text);
        box.setOpaque(false);
        box.setFocusable(false);
        box.setForeground(Floating.LIGHT);
        box.setToolTipText(tip);
        box.setAlignmentX(Component.LEFT_ALIGNMENT);
        box.addActionListener(e -> action.accept(box.isSelected()));
        return box;
    }
}

package com.hdmapreforged;

import static javax.swing.Box.*;
import static com.hdmapreforged.PoiType.*;
import static com.hdmapreforged.SearchResults.*;

import java.awt.*;
import java.util.*;
import java.util.List;
import java.util.function.*;
import javax.swing.*;
import javax.swing.Timer;
import lombok.*;
import net.runelite.api.coords.*;
import net.runelite.client.ui.*;
import net.runelite.client.util.*;

/** Details of the selected icon (requirements, destinations, links), or the teleports nearest a chosen point. */
final class InfoCard extends Fitted {
    static final int MAX_LINKS = 60;
    static final Color MET = new Color(110, 200, 110), MISSING = new Color(230, 110, 100);

    final MapView map;
    final Supplier<WorldData> world;
    final ItemNames itemNames;
    final MapConfig config;
    Poi poi;
    WorldPoint nearestTo;
    List<Poi> nearest = new ArrayList<>();
    int textWidth = 160;
    IntFunction<JComponent> route;
    /** The route's steps take milliseconds to build: while the card is hidden they wait, built once it shows. */
    boolean routeStale;
    @Setter
    Runnable onRebuilt = () -> { };

    InfoCard(MapView map, Supplier<WorldData> world, ItemNames itemNames, MapConfig config) {
        // As JPanel(); a page down keeps 16 pixels of the page before.
        super(new FlowLayout(), 16);
        this.map = map;
        this.world = world;
        this.itemNames = itemNames;
        this.config = config;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(ColorScheme.DARKER_GRAY_COLOR);
        setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
        // Shown again (the map opened, the card unfolded): the route's steps that waited are built now.
        addHierarchyListener(e -> {
            if (routeStale && route != null && isShowing()) {
                routeStale = false;
                refill(routeHolder, route);
            }
        });
        refresh();
    }

    void setTextWidth(int width) {
        textWidth = width;
        refresh();
    }

    List<ItemSources.Ware> wares;
    /** The shop a shop icon stands for, for its shopkeeper's picture. */
    WorldData.Shop shop;
    @Setter
    Consumer<String> itemSearch;
    @Setter
    NpcImages npcPictures = new NpcImages((id, done) -> done.accept(null));

    Consumer<Tour.Stop> stopAdder;

    void setStopAdder(Consumer<Tour.Stop> stopAdder) {
        this.stopAdder = stopAdder;
        refresh();
    }

    Consumer<WorldPoint> router;

    void setRouter(Consumer<WorldPoint> router) {
        this.router = router;
        refresh();
    }

    void show(Poi poi) {
        this.poi = poi;
        nearestTo = null;
        shop = poi != null && poi.type == PoiType.SHOP ? world.get().shop(poi.location) : null;
        wares = shop == null ? null : world.get().wares(poi.location);
        if (poi != null) {
            var ids = new ArrayList<Integer>();
            poi.members().forEach(member -> ids.addAll(Requirements.itemIds(member.needs.items)));
            poi.links().forEach(link -> ids.addAll(Requirements.itemIds(link.needs.items)));
            // The wares' prices.
            if (wares != null) {
                wares.forEach(ware -> ids.add(ware.itemId));
            }
            if (!ids.isEmpty()) {
                itemNames.resolve(ids, () -> {
                    if (this.poi == poi) {
                        refresh();
                    }
                });
            }
        }
        refresh();
    }

    /** A route step passed rebuilds only the route: not the search list beside it, nor details that hide it. */
    void setRoute(IntFunction<JComponent> route, boolean show) {
        boolean had = this.route != null;
        this.route = route;
        if (show && route != null) {
            poi = null;
            nearestTo = null;
        } else if (poi != null || nearestTo != null) {
            return;
        } else if (had && route != null && routeHolder.getParent() == this && !isShowing()) {
            // Built once the card shows.
            routeStale = true;
            return;
        } else if (had && route != null && refill(routeHolder, route)) {
            return;
        }
        refresh();
    }

    /** The route again in place of a place or extra shown since (the map opened while one is walked). */
    void showRoute() {
        if (route != null) {
            setRoute(route, true);
        }
    }

    void setExtra(IntFunction<JComponent> extra) {
        this.extra = extra;
        if (extra != null) {
            poi = null;
            nearestTo = null;
        }
        refresh();
    }

    /**
     * A background update of {@code old}: taken only while it is still the card's extra, re-rendered only while shown
     * (no place's details open over it), never closing anything.
     */
    boolean updateExtra(IntFunction<JComponent> old, IntFunction<JComponent> now) {
        if (extra == null || extra != old) {
            return false;
        }
        extra = now;
        if (poi == null && nearestTo == null && !refill(extraHolder, now)) {
            refresh();
        }
        return true;
    }

    IntFunction<JComponent> extra;
    /** The extra and the route shown each in a holder of its own, so one can change without the other. */
    final JPanel extraHolder = column(), routeHolder = column();

    /** {@code holder} holding {@code section} alone, at the card's text width. */
    JPanel fill(JPanel holder, IntFunction<JComponent> section) {
        holder.removeAll();
        holder.add(section.apply(textWidth));
        return holder;
    }

    /** Only {@code holder} built again, while the card shows it; false when the card must be built whole. */
    boolean refill(JPanel holder, IntFunction<JComponent> section) {
        if (holder.getParent() != this || waiting != null) {
            return false;
        }
        fill(holder, section);
        revalidate();
        repaint();
        onRebuilt.run();
        return true;
    }

    void showNearest(WorldPoint point, List<Poi> found) {
        map.select(null);
        poi = null;
        nearestTo = point;
        nearest = new ArrayList<>(found);
        refresh();
    }

    /** Not while the map animates: building a card with many rows made the map's flight stutter. */
    void refresh() {
        if (!map.animator.isRunning()) {
            if (waiting != null) {
                waiting.stop();
                waiting = null;
            }
            rebuildNow();
        } else if (waiting == null) {
            // Until then only the name, so the old selection's buttons cannot be used.
            removeAll();
            if (poi != null) {
                JLabel title = bold(plain(poi.name));
                title.setForeground(Color.WHITE);
                title.setAlignmentX(Component.LEFT_ALIGNMENT);
                add(title);
            }
            revalidate();
            repaint();
            waiting = new Timer(40, e -> {
                if (!map.animator.isRunning()) {
                    refresh();
                }
            });
            waiting.start();
        }
    }

    Timer waiting;

    void rebuildNow() {
        removeAll();
        if (nearestTo != null) {
            buildNearest();
        } else if (poi == null && (extra != null || route != null)) {
            if (extra != null) {
                add(fill(extraHolder, extra));
            }
            if (extra != null && route != null) {
                add(createVerticalStrut(8));
                var line = new JSeparator();
                line.setAlignmentX(Component.LEFT_ALIGNMENT);
                add(line);
                add(createVerticalStrut(4));
            }
            if (route != null) {
                routeStale = !isShowing();
                add(routeStale ? routeHolder : fill(routeHolder, route));
            }
        } else if (poi == null) {
            add(grey(PoiType.t("t12")));
        } else {
            buildDetails();
        }
        revalidate();
        repaint();
        onRebuilt.run();
    }

    void buildNearest() {
        add(text("Nearest teleports to this spot", Color.WHITE, true));
        add(grey(PoiType.t("t13")));
        if (nearest.isEmpty()) {
            add(grey("None on this map."));
        }
        for (var found : nearest) {
            JLabel entry = link(found.name + "  (" + found.location.distanceTo2D(nearestTo) + " tiles)", () -> map.focus(found));
            entry.setIcon(new ImageIcon(PoiIcons.image(found.type, 12)));
            add(entry);
        }
    }

    void buildDetails() {
        JLabel title = text(poi.name, Color.WHITE, true);
        title.setIcon(new ImageIcon(PoiIcons.image(poi.type, 16)));
        title.setIconTextGap(6);
        add(title);
        String where = poi.type.displayName + (poi.map != null ? " · " + poi.map.name : "")
            + (poi.location.getPlane() > 0 ? " · floor " + poi.location.getPlane() : "");
        var dot = poi.type == QUEST_START && map.unlocks != null ? map.unlocks.questColor(poi.name) : null;
        where += dot == null ? "" : dot == Color.GREEN ? " · Finished" : dot == Color.YELLOW ? " · Started"
            : " · Not started";
        add(grey(where));

        var buttons = new ArrayList<JButton>();
        var inside = MapView.mapBelow(poi);
        if (inside != null) {
            buttons.add(button(inside.map.id == BaseMap.SURFACE ? "Go out" : "Go in", () -> map.goIn(inside)));
        }
        var target = poi;
        if (router != null) {
            buttons.add(tip(button("Route", () -> router.accept(target.location)),
                "A route from where you are to here"));
        }
        if (stopAdder != null) {
            buttons.add(tip(button("+ Stop", () -> stopAdder.accept(Tour.Stop.place(
                target.name, target.location))), PoiType.t("t14")));
        }
        buttons.add(button("Wiki", () -> LinkBrowser.browse(
            Wiki.searchUrl(poi.wikiQuery != null ? poi.wikiQuery : poi.name))));
        // Slimmer than usual, so more share a row.
        buttons.forEach(button -> button.setMargin(new Insets(2, 6, 2, 6)));
        add(createVerticalStrut(6));
        add(wrapLabels(buttons, 4, textWidth + 70));
        if (extra != null) {
            add(createVerticalStrut(4));
            add(link("← Back to the search results", () -> map.select(null)));
        }

        if (poi.note != null) {
            add(createVerticalStrut(6));
            add(text(poi.note, new Color(255, 200, 120), false));
        }

        if (!poi.nearby().isEmpty()) {
            boolean teleports = poi.nearby().stream().allMatch(p -> p.type == TELEPORT);
            heading(teleports ? "Teleports that land here" : "Also here");
            for (var other : poi.nearby()) {
                for (var member : other.members()) {
                    addMember(member, member.type == TELEPORT || teleports ? ""
                        : "  (" + member.type.displayName + ")");
                }
            }
        }

        if (poi.type == PoiType.SHOP) {
            buildWares();
        }

        var members = poi.members();
        if (members.size() > 1) {
            heading("Ways to get here (" + members.size() + ")");
            for (var member : members) {
                addMember(member, "");
            }
        }
        var own = Requirements.describe(poi.needs, itemNames);
        if (members.size() <= 1 && !own.isEmpty()) {
            heading("Requirements");
            addRequirements(own, "");
        }

        var links = poi.links();
        var ownLines = new HashSet<String>();
        own.forEach(line -> ownLines.add(line.text));
        if (!links.isEmpty()) {
            heading(poi.type.isRandomDestination() ? "Can send you to (" + links.size() + ")"
                : PoiType.NETWORKS.contains(poi.type) ? "Travel to (" + links.size() + ")" : "Leads to");
            String type = poi.type.displayName.toLowerCase(Locale.ROOT);
            // A box as the Icons panel's, in the card's smaller grey text.
            var lines = IconPanel.check("Show lines on the map", "Draw lines from this " + type
                + " to where it leads; remembered for every " + type, map.linesShown(poi.type),
                on -> map.setLinesShown(target.type, on));
            lines.setFont(FontManager.getRunescapeSmallFont());
            lines.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            add(lines);
            for (int i = 0; i < links.size() && i < MAX_LINKS; i++) {
                var link = links.get(i);
                boolean usable = usable(link.needs);
                if (!usable && config.onlyUsable()) {
                    continue;
                }
                String label = link.label + (link.map != null && link.map != poi.map && !link.label.contains(link.map.name)
                    ? "  (" + link.map.name + ")" : "");
                JLabel entry = link((usable ? "" : "✗ ") + label, () -> goTo(link));
                if (!usable) {
                    entry.setToolTipText("You do not meet a requirement for this trip");
                }
                add(entry);
                // Only what this trip needs beyond the stop's own requirements, listed above.
                var tripNeeds = Requirements.describe(link.needs, itemNames);
                tripNeeds.removeIf(line -> ownLines.contains(line.text));
                addRequirements(tripNeeds, "    ");
            }
        }

        var group = groupOf(poi);
        if (!group.isEmpty()) {
            String kind = poi.group.toLowerCase(Locale.ROOT).endsWith("teleports") ? poi.group : poi.group + " teleports";
            heading("Other " + kind + " (" + group.size() + ")");
            for (int i = 0; i < group.size() && i < MAX_LINKS; i++) {
                var other = group.get(i);
                add(link(shortName(other), () -> map.focus(other)));
            }
        }
    }

    boolean usable(Needs needs) {
        return map.unlocks() == null || map.unlocks().usable(needs);
    }

    void addMember(Poi member, String kind) {
        boolean usable = usable(member.needs);
        if (!usable && config.onlyUsable()) {
            return;
        }
        add(text((usable ? "" : "✗ ") + member.name + kind, usable ? Color.WHITE : MISSING, false));
        addRequirements(Requirements.describe(member.needs, itemNames), "    ");
    }

    void buildWares() {
        if (wares == null || wares.isEmpty()) {
            return;
        }
        if (shop != null && shop.npc >= 0) {
            JLabel keeper = pictureIcon(NpcImages.LARGE);
            npcPictures.show(shop.npc, keeper);
            add(pictureRow(keeper, grey(shop.name)));
        }
        heading("Sells (" + wares.size() + ")");
        add(choice(new String[][]{{"shop", "Shop order"}, {"stock", "Stock"}, {"name", "Name"},
            {"price", "Price"}}, wareSort, sort -> {
                wareSort = sort;
                refresh();
            }, textWidth));
        var sorted = new ArrayList<>(wares);
        sorted.sort(ItemSources.wareOrder(wareSort, itemNames::price));
        for (var ware : sorted) {
            JLabel icon = pictureIcon(PICTURE);
            itemNames.picture(ware.itemId, icon);
            // The name, like a drop's in the search panel, looks the item up in the plugin: where else it comes from.
            Runnable wiki = () -> LinkBrowser.browse(Wiki.pageUrl(ware.item));
            Runnable open = itemSearch != null ? () -> itemSearch.accept(ware.item) : wiki;
            String onWiki = "Open " + ware.item + " on the wiki";
            JComponent name = tip(bold(link(ware.item, open)),
                itemSearch != null ? "Where else to get " + ware.item : onWiki);
            int price = itemNames.price(ware.itemId);
            JPanel line = panel(new FlowLayout(FlowLayout.LEFT, 0, 0));
            line.add(tip(grey(dotted(ItemSources.stockText(ware.stock),
                price >= 0 ? "GE " + gp(price) : null) + " · "),
                PoiType.t("t15")));
            line.add(tip(link("Wiki", wiki), onWiki));
            add(createVerticalStrut(3));
            add(clickableRow(pictureRow(icon, name, line), open));
        }
    }

    /** How a shop's wares are ordered; kept from one shop to the next. */
    String wareSort = "shop";

    void addRequirements(List<Requirements.Line> lines, String indent) {
        var unlocks = map.unlocks();
        for (var line : lines) {
            Boolean met = unlocks == null ? null : unlocks.met(line);
            String mark = met == null ? "• " : met ? "✓ " : "✗ ";
            Color color = met == null ? Color.WHITE : met ? MET : MISSING;
            add(text(indent + mark + line.text, color, false));
        }
    }

    List<Poi> groupOf(Poi poi) {
        var group = new ArrayList<Poi>();
        if (poi.type != TELEPORT || poi.group == null) {
            return group;
        }
        for (var other : map.pois()) {
            var member = other.memberOf(poi.group);
            if (other != poi && other.type == TELEPORT && member != null && map.usable(member.needs)) {
                group.add(other);
            }
        }
        return group;
    }

    String shortName(Poi poi) {
        var member = poi.memberOf(this.poi.group);
        String name = member != null ? member.name : poi.name;
        int colon = name.indexOf(':');
        return colon > 0 ? name.substring(colon + 1).trim() : name;
    }

    void goTo(Poi.Link link) {
        for (var other : map.pois()) {
            if (other != poi && other.type == poi.type && other.location.getPlane() == link.point.getPlane()
                && other.location.distanceTo2D(link.point) <= 12) {
                map.focus(other);
                return;
            }
        }
        map.focus(link.point);
    }

    /** A heading as the search panel's. */
    void heading(String text) {
        add(createVerticalStrut(8));
        add(SearchResults.heading(text, textWidth));
        add(createVerticalStrut(2));
    }

    /** Names as they are (places, party members): a leading {@code <html>} must not render as HTML (remote images). */
    static JLabel plain(String text) {
        JLabel label = new JLabel();
        label.putClientProperty("html.disable", Boolean.TRUE);
        label.setText(text);
        return label;
    }

    JLabel grey(String text) {
        return text(text, SOFT, false);
    }

    /** As the search panel's, without the space between lines of a list. */
    JLabel text(String text, Color color, boolean bold) {
        return SearchResults.text(text, color, bold ? Font.BOLD : Font.PLAIN, bold ? 1 : 0, textWidth);
    }

    JLabel link(String text, Runnable action) {
        return clickable(text(text, LINK, false), action, true);
    }

    static String escape(String text) {
        return RouteFeature.RouteText.escape(text).replace("\n", "<br>");
    }
}

package com.hdmapreforged;

import java.util.*;

/** Instances whose template copies a place on the map ({@code route/instance_copies.tsv}): their tiles as that place's. */
final class InstanceCopies {
    static final RouteFiles.Table<List<int[]>> COPIES = new RouteFiles.Table<>(InstanceCopies::load);

    static List<int[]> load() {
        return Pathfinder.table(RouteFiles.DIR + "instance_copies.tsv", parts -> {
            var min = Pathfinder.ints(parts[0]);
            var max = Pathfinder.ints(parts[1]);
            var by = Pathfinder.ints(parts[2]);
            return new int[]{min[0], min[1], max[0], max[1], by[0], by[1]};
        });
    }

    /** The place's tile for a template tile ({@code x y plane}), or null when no known copy holds it. */
    static int[] place(int x, int y, int plane) {
        for (var c : COPIES.get()) {
            if (x >= c[0] && y >= c[1] && x <= c[2] && y <= c[3]) {
                return new int[]{x - c[4], y - c[5], plane};
            }
        }
        return null;
    }

    /** The template tile for a tile of a copied place, or null when no known copy holds it: what the game draws there. */
    static int[] template(int x, int y, int plane) {
        for (var c : COPIES.get()) {
            if (x >= c[0] - c[4] && y >= c[1] - c[5] && x <= c[2] - c[4] && y <= c[3] - c[5]) {
                return new int[]{x + c[4], y + c[5], plane};
            }
        }
        return null;
    }

}

package com.hdmapreforged;

import java.util.*;

/** Int keys to int values in open addressing arrays, for the search's hot loop (no boxing). Not thread-safe. */
final class IntMap {
    /** Returned for a missing key; never a key itself. */
    static final int MISSING = Integer.MIN_VALUE;
    int[] keys, values;
    int size, mask;

    IntMap(int capacity) {
        allocate(Integer.highestOneBit(Math.max(16, capacity) - 1) << 1);
    }

    void allocate(int n) {
        keys = new int[n];
        Arrays.fill(keys, MISSING);
        values = new int[n];
        mask = n - 1;
        size = 0;
    }

    int slot(int key) {
        int h = key * 0x9E3779B9, i = (h ^ h >>> 16) & mask;
        while (keys[i] != MISSING && keys[i] != key) {
            i = (i + 1) & mask;
        }
        return i;
    }

    int get(int key) {
        int i = slot(key);
        return keys[i] == MISSING ? MISSING : values[i];
    }

    void put(int key, int value) {
        int i = slot(key);
        if (keys[i] == MISSING) {
            if ((size + 1) * 2 > keys.length) {
                grow();
                i = slot(key);
            }
            keys[i] = key;
            size++;
        }
        values[i] = value;
    }

    void grow() {
        var oldKeys = keys;
        var oldValues = values;
        allocate(oldKeys.length * 2);
        for (int i = 0; i < oldKeys.length; i++) {
            if (oldKeys[i] != MISSING) {
                put(oldKeys[i], oldValues[i]);
            }
        }
    }
}

package com.hdmapreforged;

import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import javax.swing.*;
import lombok.*;
import net.runelite.client.callback.*;
import net.runelite.client.game.*;
import net.runelite.client.util.*;

/**
 * Item names for requirement lists, and the Grand Exchange prices the client knows; looked up on the client thread,
 * read from Swing.
 */
@RequiredArgsConstructor
final class ItemNames implements IntFunction<String>, SearchResults.Prices {
    final ClientThread clientThread;
    final ItemManager itemManager;
    final Map<Integer, String> names = new ConcurrentHashMap<>();
    final Map<Integer, Integer> prices = new ConcurrentHashMap<>();
    /**
     * Id to when it was last looked up: a name not found is tried again after 30 seconds (the game's item data may not
     * have been ready), a price after 10 minutes (prices move).
     */
    final Map<Integer, Long> looked = new ConcurrentHashMap<>();
    static final long RETRY_MS = 30_000;
    /** More than a big shop sells; the game's own image cache keeps only 128 for every plugin. */
    static final int IMAGES = 512;
    /** The pictures of the items shown last, so a list built again never asks the game again. Swing thread. */
    final Map<Integer, AsyncBufferedImage> images = new LruMap<>(16, IMAGES);

    public int price(int id) {
        Integer price = prices.get(id);
        return price == null ? -1 : price;
    }

    /** Shows the game's picture of an item in {@code label}, once loaded. */
    void picture(int id, JLabel label) {
        images.computeIfAbsent(id, itemManager::getImage).addTo(label);
    }

    public String apply(int id) {
        String name = names.get(id);
        return name != null || !looked.containsKey(id) ? name : "Item " + id;
    }

    /** Client thread. */
    String lookUp(int id) {
        try {
            var item = itemManager.getItemComposition(id);
            String name = item == null ? null : item.getName();
            return name == null || name.isEmpty() || "null".equals(name) ? null : name;
        } catch (RuntimeException e) {
            return null;
        }
    }

    boolean wanted(int id, long now) {
        Long at = looked.get(id);
        return at == null || now - at >= (names.containsKey(id) ? 10 * 60_000 : RETRY_MS);
    }

    /** Client thread. */
    int lookUpPrice(int id) {
        try {
            return (int) Math.min(Integer.MAX_VALUE, Math.max(0, itemManager.getItemPrice(id)));
        } catch (RuntimeException e) {
            return 0;
        }
    }

    public void resolve(Collection<Integer> ids, Runnable done) {
        // Previews run without a client.
        long now = System.currentTimeMillis();
        if (clientThread == null || ids.stream().noneMatch(id -> wanted(id, now))) {
            return;
        }
        clientThread.invoke(() -> {
            long at = System.currentTimeMillis();
            for (int id : ids) {
                if (!wanted(id, at)) {
                    continue;
                }
                String name = names.containsKey(id) ? null : lookUp(id);
                if (name != null) {
                    names.put(id, name);
                }
                prices.put(id, lookUpPrice(id));
                looked.put(id, at);
            }
            SwingUtilities.invokeLater(done);
        });
    }
}

package com.hdmapreforged;

import lombok.*;
import java.util.*;
import java.util.regex.*;
import java.util.stream.*;

/**
 * Items carried and runes a worn staff gives without limit: what a route may use. The bank only through a
 * {@link BankDetour} (setting), as {@link #plus}. Immutable.
 */
@RequiredArgsConstructor(access = AccessLevel.PRIVATE)
final class ItemSnapshot {
    /** Compiled once: a split on a pattern compiles it on every call, and requests check hundreds of columns. */
    static final Pattern ALL = Pattern.compile("&&");
    static final Pattern ANY = Pattern.compile("\\|\\|");
    static final int AIR = 556, WATER = 555, EARTH = 557, FIRE = 554;
    /** Combination runes (steam, mist, dust, smoke, mud, lava) by id, with the two runes each counts as. */
    static final RouteFiles.Table<Map<Integer, int[]>> COMBINATIONS = new RouteFiles.Table<>(() -> Pathfinder.list(
        "combination rune ids", Pathfinder::ints).stream().filter(c -> c.length > 2)
        .collect(Collectors.toMap(c -> c[0], c -> new int[]{c[1], c[2]}, (a, b) -> a)));

    static final ItemSnapshot NONE = new ItemSnapshot(Map.of(), Set.of());
    static final ItemSnapshot EVERYTHING = new ItemSnapshot(Map.of(), Set.of());

    final Map<Integer, Long> carried;
    final Set<Integer> unlimited;

    /** Whether {@code other} carries the same (an inventory that changed back and forth is no change). */
    boolean sameAs(ItemSnapshot other) {
        return other != null && carried.equals(other.carried);
    }

    /**
     * Whether {@code other} carries the same of these items as far as anything asks for them ({@code most}: the most of
     * each any way needs; a rune cast with enough left is no change), and the same staff's runes.
     */
    boolean sameFor(ItemSnapshot other, Map<Integer, Long> most) {
        return other != null && unlimited.equals(other.unlimited) && most.entrySet().stream().allMatch(e ->
            Math.min(carried.getOrDefault(e.getKey(), 0L), e.getValue())
                == Math.min(other.carried.getOrDefault(e.getKey(), 0L), e.getValue()));
    }

    static ItemSnapshot of(Map<Integer, Long> carried, Set<Integer> unlimited) {
        return new ItemSnapshot(Map.of(), Collections.unmodifiableSet(new HashSet<>(unlimited))).plus(carried);
    }

    /** These items and {@code more} (a bank's), with the same staff's runes. */
    ItemSnapshot plus(Map<Integer, Long> more) {
        var all = new HashMap<Integer, Long>(carried);
        more.forEach((id, n) -> add(all, id, n));
        return new ItemSnapshot(Collections.unmodifiableMap(all), unlimited);
    }

    static void add(Map<Integer, Long> into, int id, long quantity) {
        into.merge(id, quantity, Long::sum);
        var parts = COMBINATIONS.get().get(id);
        if (parts != null) {
            for (int part : parts) {
                into.merge(part, quantity, Long::sum);
            }
        }
    }

    static Set<Integer> runesFromWeapon(String name) {
        var runes = new HashSet<Integer>();
        String n = name == null ? "" : name.toLowerCase(Locale.ROOT);
        if (!n.contains("staff") && !n.contains("tome of") && !n.contains("wand") || n.contains("(empty)")
            || n.contains("uncharged")) {
            return runes;
        }
        // The words that give each rune.
        var words = Pathfinder.list("staff runes");
        int[] ids = {AIR, WATER, EARTH, FIRE};
        for (int i = 0; i < Math.min(ids.length, words.size()); i++) {
            if (Arrays.stream(words.get(i).split(" ")).anyMatch(w -> !w.isEmpty() && n.contains(w))) {
                runes.add(ids[i]);
            }
        }
        return runes;
    }

    /**
     * Whether what is carried meets a column like {@code "556=3&&563=1"}. A token that is no item id counts as met:
     * only a certainly missing item rules out.
     */
    boolean has(String column) {
        if (this == EVERYTHING || column == null || column.trim().isEmpty()) {
            return true;
        }
        for (String all : ALL.split(column)) {
            boolean any = false, judged = false;
            for (String alternative : ANY.split(all)) {
                var parts = alternative.trim().split("=");
                String token = parts[0].trim();
                if (token.isEmpty()) {
                    continue;
                }
                long quantity = 1;
                if (parts.length > 1) {
                    try {
                        quantity = Long.parseLong(parts[1].trim());
                    } catch (NumberFormatException e) {
                        // One then.
                    }
                }
                Integer id = token.length() <= 9 && token.chars().allMatch(Character::isDigit) ? Integer.valueOf(token)
                    : null;
                if (id == null) {
                    any = true;
                    continue;
                }
                judged = true;
                any |= unlimited.contains(id) || carried.getOrDefault(id, 0L) >= quantity;
            }
            if (judged && !any) {
                return false;
            }
        }
        return true;
    }
}

