 * joined without a user click: "Rejoin party" rejoins the remembered last one.
 */
@RequiredArgsConstructor(onConstructor_ = @Inject)
public final class PartyMap {
    static final String LAST_KEY = "partyLast";
    static final List<Class<? extends WebsocketMessage>> MESSAGES =
        List.of(HdMapPartyLocation.class, HdMapPartyState.class, HdMapPartyDrop.class);

    // The constructor takes these in this order.
    final Client client;
    final PartyService party;
    final WSClient wsClient;
    final EventBus eventBus;
    final ConfigManager configManager;
    final MapConfig config;
    final ItemManager itemManager;
    final SkillIconManager skillIcons;
    final ClientThread clientThread;
    final SpriteManager spriteManager;

    final PartyMembers members = new PartyMembers();
    final Throttle throttle = new Throttle();
    final PartyOverlay overlay = new PartyOverlay(this);
    /** The overlay's: repaints the views while drops rise. */
    final PartyOverlay.Ticker ticker = new PartyOverlay.Ticker(this::repaint);
    /**
     * Each view's party list; Swing thread only. The plugin makes its views anew at each start, so a stop leaves them
     * as they are.
     */
    final Map<MapView, FriendsWidget> widgets = new LinkedHashMap<>();
    volatile int myWorld;
    /** The party this plugin joined for the user, or null. */
    volatile String joinedCode;
    volatile long lastChange = Long.MIN_VALUE / 2;
    Timer idleCheck;
    volatile boolean sentOnline;
    volatile Long outSince;

    volatile boolean gearChanged = true;
    /** The members as last read without a clash with the websocket thread. */
    volatile List<Member> lastGroup = Collections.emptyList();
    final Map<Long, BufferedImage> itemImages = new ConcurrentHashMap<>();

    void start(MapView... maps) {
        running = true;
        // The party dropped what we shared when we stopped: whole again at once, and theirs asked for anew.
        gearChanged = true;
        wholeNext.set(true);
        if (party.isInParty()) {
            party.send(new UserSync());
        }
        MESSAGES.forEach(wsClient::registerMessage);
        eventBus.register(this);
        for (int id : Orbs.SPRITES) {
            spriteManager.getSpriteAsync(id, 0, image -> {
                sprites.put(id, image);
                repaint();
            });
        }
        outSince = client.getGameState() == GameState.LOGGED_IN ? null : System.currentTimeMillis();
        SwingUtilities.invokeLater(() -> {
            for (var view : maps) {
                var widget = new FriendsWidget(this, view, new MemberPages(this));
                view.addOverlay(overlay);
                view.menus.add((popup, point) -> contribute(popup, view));
                view.clickCatcher = (at, projection) -> {
                    long best = memberAt(at, projection);
                    if (best < 0) {
                        return false;
                    }
                    widget.show(best);
                    follow(view, best);
                    repaint();
                    return true;
                };
                var pointing = new MouseAdapter() {
                    public void mouseMoved(MouseEvent e) {
                        long now = memberAt(e.getPoint(), view.projection());
                        if (now != hoveredMember) {
                            hoveredMember = now;
                            view.repaint();
                        }
                    }

                    public void mouseExited(MouseEvent e) {
                        if (hoveredMember >= 0) {
                            hoveredMember = -1;
                            view.repaint();
                        }
                    }
                };
                view.addMouseMotionListener(pointing);
                view.addMouseListener(pointing);
                widgets.put(view, widget);
                view.addWidget(widget);
            }
            // Leaves a party we rejoined after long logged out, as RuneLite's Party plugin does.
            idleCheck = new Timer(30_000, e -> {
                if (leaveIdle(joinedCode, party.getPartyPassphrase(), outSince, System.currentTimeMillis())) {
                    leave();
                }
            });
            idleCheck.start();
        });
    }

    /** Between start and stop: a drop's callback after it would outlive the members' clear. */
    volatile boolean running;

    void stop() {
        running = false;
        try {
            sendOffline();
        } catch (RuntimeException e) {
        }
        if (config.partyShareGear()) {
            unshare();
        }
        fresh.set(true);
        sidebarNews = null;
        eventBus.unregister(this);
        MESSAGES.forEach(wsClient::unregisterMessage);
        members.clear();
        throttle.reset();
        itemImages.clear();
        sprites.clear();
        SwingUtilities.invokeLater(() -> {
            if (idleCheck != null) {
                idleCheck.stop();
                idleCheck = null;
            }
            widgets.values().forEach(widget -> widget.ticker.stop());
            widgets.clear();
            ticker.stop();
            if (leaveOnShutdown(joinedCode, party.getPartyPassphrase())) {
                party.changeParty(null);
            }
            joinedCode = null;
        });
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        myWorld = client.getWorld();
    }

    volatile long hoveredMember = -1;

    long memberAt(Point at, Projection projection) {
        long best = -1;
        double bestDistance = 14;
        for (var marker : markers()) {
            // Where the map draws them, which can differ from the game.
            var shown = projection.shown(marker.point);
            if (!projection.shows(marker.point)) {
                continue;
            }
            double d = at.distance(projection.screenX(shown.getX() + 0.5), projection.screenY(shown.getY() + 0.5));
            if (d < bestDistance) {
                bestDistance = d;
                best = marker.id;
            }
        }
        return best;
    }

    final Map<Integer, BufferedImage> sprites = new ConcurrentHashMap<>();
    /** The sidebar's and the map's pictures of what members share. */
    BufferedImage skill(int ordinal) {
        var skills = Skill.values();
        return ordinal < 0 || ordinal >= Math.min(SKILLS, skills.length) ? null
            : skillIcons.getSkillImage(skills[ordinal], true);
    }

    BufferedImage sprite(int id) {
        return sprites.get(id);
    }

    /** The sidebar's party list. */
    List<Row> rows() {
        // Whether the map draws them or not: the list says where they are.
        return FriendsWidget.rows(members.markers(System.currentTimeMillis()), groupMembers());
    }

    /** Has the maps follow a member. */
    void follow(long id) {
        widgets.keySet().forEach(view -> follow(view, id));
    }

    /** Follows a member clicked: the map keeps them in view as they move. Swing thread. */
    void follow(MapView view, long id) {
        Supplier<WorldPoint> at = () -> markers().stream().filter(m -> m.id == id).map(m -> m.point).findFirst()
            .orElse(null);
        if (at.get() != null) {
            view.follow(at);
        }
    }

    List<Member> groupMembers() {
        var list = new ArrayList<Member>();
        if (!party.isInParty()) {
            return list;
        }
        List<PartyMember> all;
        long me;
        try {
            // The websocket thread changes this list while we read it on the Swing thread (the local member too is
            // looked up in it).
            all = new ArrayList<>(party.getMembers());
            var local = party.getLocalMember();
            me = local == null ? -1 : local.getMemberId();
        } catch (ConcurrentModificationException | ArrayIndexOutOfBoundsException e) {
            return new ArrayList<>(lastGroup);
        }
        for (var member : all) {
            if (member != null && member.getMemberId() != me) {
                // RuneLite names a member "<unknown>" until they log in and send their name.
                String name = member.getDisplayName();
                list.add(new Member(member.getMemberId(),
                    name == null || name.startsWith("<") ? null : PartyMembers.clean(name)));
            }
        }
        lastGroup = List.copyOf(list);
        return list;
    }

    List<PartyMembers.Marker> markers() {
        return config.partyShowMembers() ? members.markers(System.currentTimeMillis()) : Collections.emptyList();
    }

    void tick(WorldPoint location, boolean house, int tick) {
        if (!members.isEmpty() && tick % 5 == 0) {
            // Markers fade over minutes: every few seconds is enough (animations have their own ticker).
            repaint();
        }
        // Run and special attack energy alone are no reason to send; a whole one when due is, also when idle (a member who
        // missed one gets it).
        if ((gearChanged || tick - wholeTick >= WHOLE_TICKS) && party.isInParty() && config.partyShareGear()) {
            gearChanged = false;
            var state = state(tick);
            if (state != null) {
                party.send(state);
            }
        }
        if (party.isInParty() && config.partyShareLocation() && throttle.shouldSend(location, tick)) {
            Player player = client.getLocalPlayer();
            party.send(new HdMapPartyLocation(location, client.getWorld(),
                player == null || player.getName() == null ? null : Text.removeTags(player.getName()), house));
            sentOnline = true;
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        GameState state = event.getGameState();
        if (state == GameState.LOGGED_IN) {
            outSince = null;
        } else if (state == GameState.LOGIN_SCREEN) {
            if (outSince == null) {
                outSince = System.currentTimeMillis();
            }
            // The next login may be another account: a fresh whole one.
            fresh.set(true);
            sendOffline();
            throttle.reset();
            myWorld = 0;
        } else if (state == GameState.HOPPING) {
            // The same tile on another world: sent at once, not only with the next heartbeat.
            throttle.force();
        }
    }

    void sendOffline() {
        if (sentOnline && party.isInParty()) {
            party.send(HdMapPartyLocation.offline());
        }
        sentOnline = false;
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!GROUP.equals(event.getGroup()) || !event.getKey().startsWith("party")) {
            return;
        }
        if ("partyShareLocation".equals(event.getKey()) && !config.partyShareLocation() && party.isInParty()
            && client.getGameState() == GameState.LOGGED_IN) {
            party.send(HdMapPartyLocation.offline());
            sentOnline = false;
        }
        if ("partyShareGear".equals(event.getKey()) && party.isInParty()) {
            // Off: the party drops what it showed; on again: a fresh whole one, at the next tick.
            fresh.set(true);
            gearChanged = true;
            if (!config.partyShareGear()) {
                unshare();
            }
        }
        throttle.force();
        repaint();
    }

    // Party events arrive on the websocket thread.

    @Subscribe
    public void onHdMapPartyLocation(HdMapPartyLocation message) {
        if (isLocal(message.getMemberId())) {
            return;
        }
        members.update(message.getMemberId(), message.point(), message.world(), message.name(),
            message.house(), System.currentTimeMillis());
        memberDetails(message.getMemberId());
        repaint();
    }

    /** RuneLite's party data (its Party plugin sends where one is), for members without this plugin. */
    @Subscribe
    public void onPartyData(PartyData message) {
        if (message.getCoord() == null || isLocal(message.getMemberId())) {
            return;
        }
        var point = WorldPoint.fromCoord(message.getCoord());
        if (!HdMapPartyLocation.plausible(point)) {
            return;
        }
        if (members.updateFromCore(message.getMemberId(), point, System.currentTimeMillis())) {
            memberDetails(message.getMemberId());
            repaint();
        }
    }

    @Subscribe
    public void onUserJoin(UserJoin event) {
        sendWhole();
    }

    /** A member (re)started and asks for everyone's: sent whole, the location too. */
    @Subscribe
    public void onUserSync(UserSync event) {
        sendWhole();
    }

    void sendWhole() {
        throttle.force();
        gearChanged = true;
        // The next goes whole (read on the client thread, which alone has sent).
        wholeNext.set(true);
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event) {
        int id = event.getContainerId();
        if (id == InventoryID.INV || id == InventoryID.WORN) {
            gearChanged = true;
        }
    }

    @Subscribe
    public void onStatChanged(StatChanged event) {
        gearChanged = true;
    }

    @Subscribe
    public void onHdMapPartyState(HdMapPartyState message) {
        if (!isLocal(message.getMemberId())) {
            members.state(message.getMemberId(), message, System.currentTimeMillis());
            repaint();
        }
    }

    @Subscribe
    public void onNpcLootReceived(NpcLootReceived event) {
        shareDrops(event.getItems());
    }

    @Subscribe
    public void onPlayerLootReceived(PlayerLootReceived event) {
        shareDrops(event.getItems());
    }

    void shareDrops(Collection<ItemStack> items) {
        // Untradeables go only with drop sharing on: turned off, nothing is shared.
        boolean untradeables = config.partyShareUntradeables();
        if (!party.isInParty() || !config.partyShareDrops()) {
            return;
        }
        var valuable = new ArrayList<HdMapPartyDrop>();
        for (ItemStack stack : items) {
            long value = itemManager.getItemPriceWithSource(stack.getId(), false) * stack.getQuantity();
            boolean untradeable = untradeables && !tradeable(stack.getId());
            // A lower value saved before the setting had its minimum still reads back as it was.
            if (value >= Math.max(MIN_DROP_VALUE, config.partyDropValue()) || untradeable) {
                valuable.add(new HdMapPartyDrop(stack.getId(), stack.getQuantity(), value, untradeable));
            }
        }
        // Only the best few, as the receivers order them (PartyMembers.BEST: untradeables first); the map shows no more.
        valuable.sort(Comparator.comparing((HdMapPartyDrop d) -> !d.untradeable()).thenComparingLong(d -> -d.value()));
        for (var drop : valuable.subList(0, Math.min(valuable.size(), MAX_DROPS_PER_LOOT))) {
            party.send(drop);
        }
    }

    boolean tradeable(int item) {
        return itemManager.getItemComposition(itemManager.canonicalize(item)).isTradeable();
    }

    @Subscribe
    public void onHdMapPartyDrop(HdMapPartyDrop message) {
        int item = message.item();
        if (isLocal(message.getMemberId()) || item < 0) {
            return;
        }
        // Only items the game has, valued by our own prices; not once stopped (it would outlive the clear).
        clientThread.invoke(() -> {
            if (item < client.getItemCount() && running) {
                long value = itemManager.getItemPriceWithSource(item, false) * message.quantity();
                // An untradeable one shows by name, as it has no price.
                String name = tradeable(item) ? null : itemManager.getItemComposition(item).getName();
                members.loot(message.getMemberId(), new PartyMembers.Loot(item, message.quantity(), value,
                    System.currentTimeMillis(), name));
                repaint();
            }
        });
    }

    /** The parts last sent (in {@link HdMapPartyState#SIZES}' order); when sent whole. Client thread. */
    int[][] sent;
    int wholeTick = Integer.MIN_VALUE / 2;
    /** The next one goes whole: for a newcomer; and fresh, as after a start or a login. Set anywhere, taken once. */
    final AtomicBoolean wholeNext = new AtomicBoolean(), fresh = new AtomicBoolean(true);

    /** The party drops what we shared: after any whole state the client thread is sending (else it would come back). */
    void unshare() {
        clientThread.invokeLater(() -> {
            if (party.isInParty()) {
                party.send(unshared());
            }
        });
    }

    /** What one carries, wears and can do as it is now: whole when due, else what changed; null when nothing did. */
    HdMapPartyState state(int tick) {
        int[] quantities = new int[INVENTORY], levels = new int[SKILLS], boosted = new int[SKILLS];
        int[] experience = new int[SKILLS];
        var skills = Skill.values();
        for (int k = 0; k < Math.min(skills.length, SKILLS); k++) {
            levels[k] = client.getRealSkillLevel(skills[k]);
            boosted[k] = client.getBoostedSkillLevel(skills[k]);
            experience[k] = client.getSkillExperience(skills[k]);
        }
        int[][] now = {items(InventoryID.INV, quantities), quantities, items(InventoryID.WORN, new int[EQUIPMENT]),
            levels, boosted, experience};
        if (Arrays.stream(experience).allMatch(x -> x == 0)) {
            // Logging in, before the game sent the stats: not a state (every account has Hitpoints experience).
            return null;
        }
        boolean first = fresh.getAndSet(false), joined = wholeNext.getAndSet(false);
        boolean whole = sent == null || first || joined || tick - wholeTick >= WHOLE_TICKS;
        var parts = new int[now.length][];
        boolean any = whole;
        for (int k = 0; k < now.length; k++) {
            parts[k] = whole ? now[k] : changes(sent[k], now[k]);
            any |= parts[k] != null;
        }
        if (!any) {
            return null;
        }
        sent = now;
        wholeTick = whole ? tick : wholeTick;
        // Run and special attack energy go along, not alone: running changes them most ticks.
        return new HdMapPartyState(whole, first, parts, client.getEnergy() / 100,
            client.getVarpValue(VarPlayerID.SA_ENERGY) / 10);
    }

    /** Item ids (-1 where empty) and quantities of a container, as many as {@code quantities} holds. */
    int[] items(int container, int[] quantities) {
        int[] ids = new int[quantities.length];
        Arrays.fill(ids, -1);
        var items = client.getItemContainer(container);
        Item[] all = items == null ? new Item[0] : items.getItems();
        for (int k = 0; k < Math.min(all.length, ids.length); k++) {
            ids[k] = all[k].getId();
            quantities[k] = all[k].getQuantity();
        }
        return ids;
    }

    BufferedImage item(int id, int quantity) {
        long key = (long) id << 32 | quantity;
        if (itemImages.size() > 512 && !itemImages.containsKey(key)) {
            itemImages.clear();
        }
        return itemImages.computeIfAbsent(key, k -> {
            var image = itemManager.getImage(id, quantity, quantity > 1);
            image.onLoaded(this::repaint);
            return image;
        });
    }

    @Subscribe
    public void onUserPart(UserPart event) {
        members.remove(event.getMemberId());
        repaint();
    }

    @Subscribe
    public void onPartyChanged(PartyChanged event) {
        if (event.getPartyId() != null && event.getPassphrase() != null && !event.getPassphrase().isEmpty()) {
            // Whoever joined it (this plugin or RuneLite's Party panel).
            configManager.setConfiguration(GROUP, LAST_KEY, event.getPassphrase());
        }
        String ours = joinedCode;
        if (ours != null && !ours.equals(event.getPassphrase())) {
            // A party joined by hand is the user's own and never left for them.
            joinedCode = null;
        }
        members.clear();
        throttle.reset();
        throttle.force();
        repaint();
    }

    @Subscribe
    public void onPartyMemberAvatar(PartyMemberAvatar event) {
        members.avatar(event.getMemberId(), event.getImage());
        repaint();
    }

    boolean isLocal(long memberId) {
        var local = party.getLocalMember();
        return local != null && local.getMemberId() == memberId;
    }

    void memberDetails(long memberId) {
        try {
            var member = party.getMemberById(memberId);
            if (member != null) {
                members.name(memberId, member.getDisplayName());
                BufferedImage avatar = member.getAvatar();
                if (avatar != null) {
                    members.avatar(memberId, avatar);
                }
            }
        } catch (ConcurrentModificationException e) {
            // The next message fills this in.
        }
    }

    void repaint() {
        SwingUtilities.invokeLater(() -> {
            for (var view : widgets.keySet()) {
                view.followMember();
                view.repaint();
            }
            var news = sidebarNews;
            if (news != null) {
                news.run();
            }
        });
    }

    /** The sidebar's, told of members' news. */
    volatile Runnable sidebarNews;

    /** A member's experience drops rising now. */
    List<PartyMembers.Drop> xp(long id) {
        return members.drops(id, System.currentTimeMillis());
    }

    void contribute(JPopupMenu popup, MapView view) {
        var friends = new JMenu("Party");
        String current = party.getPartyPassphrase();
        for (var marker : markers()) {
            String name = marker.name != null ? marker.name : "party member";
            friends.add("Show " + name + (marker.stale() ? " (" + PartyOverlay.ago(marker.ageMillis) + ")" : ""))
                .addActionListener(a -> view.focus(marker.point));
        }
        if (friends.getMenuComponentCount() > 0) {
            friends.addSeparator();
        }
        if (current != null) {
            friends.add("Leave party").addActionListener(a -> leave());
        } else if (lastParty() != null) {
            friends.add("Rejoin party").addActionListener(a -> join(view));
        }
        if (friends.getMenuComponentCount() == 0) {
            friends.add(t("dJoinHint")).setEnabled(false);
        }
        popup.addSeparator();
        popup.add(friends);
    }

    String lastParty() {
        String last = configManager.getConfiguration(GROUP, LAST_KEY);
        return last == null || last.trim().isEmpty() ? null : last.trim();
    }

    /** Rejoins the last party. */
    void join(Component view) {
        String code = lastParty();
        if (code == null) {
            return;
        }
        long now = System.currentTimeMillis();
        String current = party.getPartyPassphrase();
        switch (PartyMapRules.join(code, client.getGameState() == GameState.LOGGED_IN, current, lastChange, now)) {
            case ALREADY_IN:
            case INVALID_CODE:
                return;
            case NOT_LOGGED_IN:
                tell(view, t("dLogInFirst"));
                return;
            case TOO_SOON:
                tell(view, t("dTooSoon"));
                return;
            case CONFIRM_LEAVE_OTHER:
                if (JOptionPane.showConfirmDialog(view, t("dLeaveOther"),
                    "Reimagined World Map", JOptionPane.YES_NO_OPTION) != JOptionPane.YES_OPTION) {
                    return;
                }
                break;
            default:
                break;
        }
        lastChange = now;
        joinedCode = code;
        party.changeParty(code);
    }

    static void tell(Component to, String message) {
        JOptionPane.showMessageDialog(to, message, "Reimagined World Map", JOptionPane.INFORMATION_MESSAGE);
    }

    void leave() {
        lastChange = System.currentTimeMillis();
        joinedCode = null;
        party.changeParty(null);
    }
}

package com.hdmapreforged;

import java.util.*;
import net.runelite.api.coords.*;

/**
 * Party decisions, free of RuneLite services for testing. Joining is always the user's own action: RuneLite rejects
 * auto-joined parties.
 */
final class PartyMapRules {
    /** Party Hotkeys waits this long between party changes; so do we. */
    static final long CHANGE_COOLDOWN_MILLIS = 5_000;
    /** RuneLite's Party plugin leaves after 30 minutes logged out; we do the same for a party we rejoined. */
    static final long IDLE_LEAVE_MILLIS = 30 * 60_000;
    /** Every tick something changed, as RuneLite's own Party plugin sends its status. */
    static final int MIN_SEND_TICKS = 1;
    /**
     * What one carries, wears and can do goes whole at most once a minute (some 600 bytes), else every tick as only
     * what changed (a fight changes it most ticks: a few numbers); a member that missed the whole one gets the next.
     */
    static final int WHOLE_TICKS = 100, MAX_DROPS_PER_LOOT = 4;
    /** Sent at least this often while standing still, so newcomers and fading work. */
    static final int HEARTBEAT_TICKS = 50;

    enum Join {
        JOIN,
        ALREADY_IN,
        CONFIRM_LEAVE_OTHER,
        NOT_LOGGED_IN,
        INVALID_CODE,
        TOO_SOON,
    }

    static Join join(String code, boolean loggedIn, String passphrase, long lastChange, long now) {
        return code == null ? Join.INVALID_CODE : code.equals(passphrase) ? Join.ALREADY_IN
            : !loggedIn ? Join.NOT_LOGGED_IN : now - lastChange < CHANGE_COOLDOWN_MILLIS ? Join.TOO_SOON
            : passphrase != null ? Join.CONFIRM_LEAVE_OTHER : Join.JOIN;
    }

    /** Only a party this plugin joined; parties the user joined elsewhere are never left. */
    static boolean leaveIdle(String joinedCode, String passphrase, Long outSince, long now) {
        return leaveOnShutdown(joinedCode, passphrase) && outSince != null
            && now - outSince >= IDLE_LEAVE_MILLIS;
    }

    static boolean leaveOnShutdown(String joinedCode, String passphrase) {
        return joinedCode != null && joinedCode.equals(passphrase);
    }

    /** {@link #shouldSend} runs on the client thread; party events reset and force it from other threads. */
    static final class Throttle {
        WorldPoint lastSent;
        int lastTick = Integer.MIN_VALUE / 2;
        volatile boolean forced;

        void force() {
            forced = true;
        }

        synchronized void reset() {
            lastSent = null;
            lastTick = Integer.MIN_VALUE / 2;
            forced = false;
        }

        synchronized boolean shouldSend(WorldPoint point, int tick) {
            if (point == null) {
                return false;
            }
            int since = tick - lastTick;
            boolean moved = !Objects.equals(point, lastSent), due = forced || since >= HEARTBEAT_TICKS || moved;
            if (!due || since < MIN_SEND_TICKS) {
                return false;
            }
            lastSent = point;
            lastTick = tick;
            forced = false;
            return true;
        }
    }
}

package com.hdmapreforged;

import java.awt.image.*;
import java.util.*;
import java.util.function.*;
import java.util.stream.*;
import lombok.*;
import net.runelite.api.coords.*;

/** Last known location of each party member: written from network threads, read on Swing, so all synchronized. */
final class PartyMembers {
    /** Heartbeats come every 30 s; after this without news the marker fades. */
    static final long FRESH_MILLIS = 75_000, FADE_MILLIS = 5 * 60_000;
    /** After this without news the member is left off the map (probably crashed). */
    static final long GONE_MILLIS = 30 * 60_000;
    static final float MIN_ALPHA = 0.4f;
    /** The core Party plugin's location messages are coarser; ours win while they keep coming. */
    static final long OWN_MESSAGE_PRIORITY_MILLIS = 60_000;

    @RequiredArgsConstructor
    static final class Marker {
        final long id;
        final String name;
        final WorldPoint point;
        final int world;
        final BufferedImage avatar;
        final long ageMillis;
        final float alpha;
        /** In a house, at its portal. */
        final boolean house;

        boolean stale() {
            return ageMillis > FRESH_MILLIS;
        }
    }

    static final class Member {
        String name;
        WorldPoint point;
        boolean house;
        int world;
        BufferedImage avatar;
        long updated, ownUpdated = Long.MIN_VALUE / 2;
    }

    final Map<Long, Member> members = new HashMap<>();
    final Map<Long, Gear> gear = new HashMap<>();

    static final class Gear {
        final int[] inventory, quantities, equipment, levels, boosted;
        /** Experience per skill (a gear made in a test may leave it null). */
        final int[] experience;
        /** 0 to 100. */
        final int run, special;
        final long at;

        /** A whole message's, or a message's changes onto {@code before}. */
        Gear(HdMapPartyState message, Gear before, long at) {
            int[][] parts = message.parts(message.whole() || before == null ? null : new int[][]{before.inventory,
                before.quantities, before.equipment, before.levels, before.boosted, before.experience});
            inventory = parts[0];
            quantities = parts[1];
            equipment = parts[2];
            levels = parts[3];
            boosted = parts[4];
            experience = parts[5];
            run = message.runEnergy();
            special = message.specialAttack();
            this.at = at;
        }
    }

    @RequiredArgsConstructor
    static final class Drop {
        final int skill, amount;
        final long at;
    }

    static final long DROP_MS = 2200;
    static final int MAX_DROPS = 16;
    final Map<Long, List<Drop>> drops = new HashMap<>();

    /** What a member got since first seen this session: experience by skill, the drops they shared. */
    static final class Session {
        final long[] xp = new long[HdMapPartyState.SKILLS];
        long value;
        /** The most valuable drops, most first; the latest, newest first. */
        final List<Loot> top = new ArrayList<>(), latest = new ArrayList<>();

        /** The skills most gained, most first, at most {@code n}. */
        int[] best(int n) {
            return IntStream.range(0, xp.length).filter(k -> xp[k] > 0).boxed()
                .sorted(Comparator.comparingLong(k -> -xp[k])).limit(n).mapToInt(Integer::intValue).toArray();
        }

        Session copy() {
            var copy = new Session();
            System.arraycopy(xp, 0, copy.xp, 0, xp.length);
            copy.value = value;
            copy.top.addAll(top);
            copy.latest.addAll(latest);
            return copy;
        }
    }

    /** Drops kept in a session's lists. */
    static final int SESSION_DROPS = 5;
    final Map<Long, Session> sessions = new HashMap<>();

    /** What a member got this session; null while nothing yet. */
    synchronized Session session(long id) {
        var session = sessions.get(id);
        return session == null || session.top.isEmpty() && Arrays.stream(session.xp).allMatch(x -> x == 0) ? null
            : session.copy();
    }

    /** Each member's experience last heard (each state tells it), for its drops. */
    final Map<Long, int[]> experience = new HashMap<>();

    /**
     * A member's state: whole, or changes onto the one had (none had: the next whole one comes within a minute); a
     * fresh one starts their experience anew (no burst of gains from another account), an unshared one drops it all.
     */
    synchronized void state(long id, HdMapPartyState message, long at) {
        Gear before = gear.get(id);
        if (message.fresh() || message.isUnshared()) {
            experience.remove(id);
        }
        if (message.isUnshared()) {
            gear.remove(id);
        } else if (message.whole() || before != null) {
            gear(id, new Gear(message, before, at));
        }
    }

    synchronized void gear(long id, Gear shared) {
        gear.put(id, shared);
        experience(id, shared.experience, shared.at);
    }

    /** What a member's experience became: the gain since last heard rises as drops and adds to the session. */
    synchronized void experience(long id, int[] now, long at) {
        int[] before = now == null ? null : experience.put(id, now);
        if (before != null) {
            var list = drops.computeIfAbsent(id, k -> new ArrayList<>());
            var session = sessions.computeIfAbsent(id, k -> new Session());
            for (int k = 0; k < Math.min(now.length, session.xp.length); k++) {
                int gained = now[k] - before[k];
                if (gained > 0 && gained < 5_000_000) {
                    list.add(new Drop(k, gained, at));
                    session.xp[k] += gained;
                }
            }
            // Kept short whoever reads it.
            list.removeIf(d -> at - d.at > DROP_MS);
            if (list.size() > MAX_DROPS) {
                list.subList(0, list.size() - MAX_DROPS).clear();
            }
        }
    }

    @RequiredArgsConstructor
    static final class Loot {
        final int item, quantity;
        final long value, at;
        /** An untradeable drop's name, else null. */
        final String name;
    }

    static final long LOOT_MS = 3500;
    /** Untradeables first (a pet, a clue: no price), then the most valuable; as the sender picks its few too. */
    static final Comparator<Loot> BEST = Comparator.comparing((Loot l) -> l.name == null).thenComparingLong(l -> -l.value);
    final Map<Long, List<Loot>> loot = new HashMap<>();

    synchronized void loot(long id, Loot drop) {
        var session = sessions.computeIfAbsent(id, k -> new Session());
        session.value += drop.value;
        session.latest.add(0, drop);
        // An untradeable seen before adds to it (Tokkul kill after kill is one entry); at most two of them stand first
        // (a pet, a clue: worth nothing in coins, they would drop off the list), then the most valuable.
        var same = drop.name == null ? null
            : session.top.stream().filter(l -> l.item == drop.item).findFirst().orElse(null);
        session.top.remove(same);
        session.top.add(same == null ? drop : new Loot(drop.item, same.quantity + drop.quantity, 0, drop.at, drop.name));
        session.top.sort(BEST);
        var ordered = new ArrayList<Loot>();
        session.top.stream().filter(l -> l.name != null).limit(2).forEach(ordered::add);
        session.top.stream().filter(l -> l.name == null).forEach(ordered::add);
        session.top.clear();
        session.top.addAll(ordered);
        for (var kept : List.of(session.latest, session.top)) {
            if (kept.size() > SESSION_DROPS) {
                kept.subList(SESSION_DROPS, kept.size()).clear();
            }
        }
        var list = loot.computeIfAbsent(id, k -> new ArrayList<>());
        list.removeIf(l -> drop.at - l.at > LOOT_MS);
        list.add(drop);
        // A big pile shows its best few.
        if (list.size() > 4) {
            list.sort(BEST);
            list.subList(4, list.size()).clear();
        }
    }

    synchronized List<Loot> loot(long id, long now) {
        return recent(loot.get(id), l -> now - l.at > LOOT_MS);
    }

    /** A copy without the old ones, which go. */
    static <T> List<T> recent(List<T> list, Predicate<T> old) {
        if (list == null) {
            return Collections.emptyList();
        }
        list.removeIf(old);
        return new ArrayList<>(list);
    }

    synchronized List<Drop> drops(long id, long now) {
        return recent(drops.get(id), d -> now - d.at > DROP_MS);
    }

    synchronized Gear gear(long id) {
        return gear.get(id);
    }

    /** A location from our own message; a null point means they left the game. */
    synchronized void update(long id, WorldPoint point, int world, String name, boolean house, long now) {
        Member member = members.computeIfAbsent(id, k -> new Member());
        // From a version that sent the house's room template (far off any map): its last spot outside, in a house.
        boolean template = point != null && HouseTracker.isTemplate(point.getX(), point.getY());
        member.point = template ? member.point : point;
        member.house = house || template;
        member.world = world;
        if (name != null) {
            member.name = name;
        }
        member.updated = now;
        member.ownUpdated = now;
    }

    /** A location from RuneLite's Party plugin, used only while no recent message of ours came. */
    synchronized boolean updateFromCore(long id, WorldPoint point, long now) {
        Member member = members.computeIfAbsent(id, k -> new Member());
        if (now - member.ownUpdated < OWN_MESSAGE_PRIORITY_MILLIS) {
            return false;
        }
        member.point = point;
        member.house = false;
        member.updated = now;
        return true;
    }

    /** From RuneLite's party data, when the member's own messages carry none. */
    synchronized void name(long id, String name) {
        Member member = members.get(id);
        name = clean(name);
        if (member != null && member.name == null && name != null) {
            member.name = name;
        }
    }

    /** Never HTML in a Swing label; null when nothing is left. */
    static String clean(String name) {
        return HdMapPartyLocation.cleaned(name, true);
    }

    synchronized void avatar(long id, BufferedImage avatar) {
        Member member = members.get(id);
        if (member != null) {
            member.avatar = avatar;
        }
    }

    synchronized void remove(long id) {
        List.of(members, gear, drops, loot, sessions, experience).forEach(m -> m.remove(id));
    }

    synchronized void clear() {
        List.of(members, gear, drops, loot, sessions, experience).forEach(Map::clear);
    }

    synchronized boolean isEmpty() {
        return members.isEmpty();
    }

    /** Oldest news first so the freshest end up on top. */
    synchronized List<Marker> markers(long now) {
        var markers = new ArrayList<Marker>();
        for (var entry : members.entrySet()) {
            Member member = entry.getValue();
            long age = Math.max(0, now - member.updated);
            if (member.point == null || age > GONE_MILLIS) {
                continue;
            }
            markers.add(new Marker(entry.getKey(), member.name, member.point, member.world, member.avatar, age, alpha(age),
                member.house));
        }
        markers.sort((a, b) -> Long.compare(b.ageMillis, a.ageMillis));
        return Collections.unmodifiableList(markers);
    }

    /** Full until FRESH_MILLIS, then fading linearly to MIN_ALPHA over FADE_MILLIS. */
    static float alpha(long ageMillis) {
        return ageMillis <= FRESH_MILLIS ? 1f
            : (float) (1 - Math.min(1, (ageMillis - FRESH_MILLIS) / (double) FADE_MILLIS) * (1 - MIN_ALPHA));
    }
}

package com.hdmapreforged;

import static java.awt.AlphaComposite.*;
import static java.lang.Math.*;
import static com.hdmapreforged.PlayerMarker.circle;
import static com.hdmapreforged.MapView.text;

import java.awt.*;
import java.awt.geom.*;
import java.awt.image.*;
import java.util.*;
import java.util.List;
import java.util.function.*;
import javax.swing.Timer;
import lombok.*;
import net.runelite.api.coords.*;
import com.hdmapreforged.PartyMembers.Marker;

/** Party members on the map: a disc (or avatar) with their initial; name and world when pointed at or clicked. */
@RequiredArgsConstructor
final class PartyOverlay implements MapView.Overlay {
    /** Distinct from the player's yellow and the icon colours. */
    static final Color[] COLORS = Arrays.stream(new int[]{0x40c8ff, 0xff69b4, 0x5ae678, 0xff8c3c, 0xaa82ff, 0x3ce6d2,
        0xff5a5a, 0xc8e650}).mapToObj(Color::new).toArray(Color[]::new);
    static final Color LABEL_BACKGROUND = new Color(20, 20, 24, 200);
    static final Font NAME_FONT = PlayerMarker.FONT, SMALL_FONT = MapView.SMALL_FONT;

    final PartyMap party;

    /**
     * Repaints ~30 times a second while something moves, instead of asking for a frame from inside paint (which never
     * lets the map rest); stops by itself once nothing moved for a moment. Swing thread only.
     */
    static final class Ticker {
        static final int FRAME_MS = 33;
        static final long LINGER_MS = 200;
        final Timer timer;
        long lastMoving;

        Ticker(Runnable repaint) {
            timer = new Timer(FRAME_MS, e -> {
                if (System.currentTimeMillis() - lastMoving > LINGER_MS) {
                    ((Timer) e.getSource()).stop();
                    return;
                }
                repaint.run();
            });
        }

        void painted(boolean moving) {
            if (moving) {
                lastMoving = System.currentTimeMillis();
                timer.start(); // no-op while running
            }
        }

        void stop() {
            timer.stop();
        }
    }

    static Color color(long id) {
        long mixed = id * 0x9E3779B97F4A7C15L;
        return COLORS[(int) ((mixed >>> 33) % COLORS.length)];
    }

    public void paint(Graphics2D g, Projection projection) {
        var all = party.markers();
        if (all.isEmpty()) {
            party.ticker.painted(false);
            return;
        }
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        boolean rising = false;
        for (var marker : all) {
            if (!projection.shows(marker.point)) {
                continue;
            }
            var at = projection.shown(marker.point);
            double x = projection.screenX(at.getX() + 0.5), y = projection.screenY(at.getY() + 0.5);
            // Only the clicked member and the one under the mouse show a name.
            paintMarker(g, projection, marker, at, x, y, party.myWorld,
                party.widgets.values().stream().anyMatch(w -> w.selected() == marker.id), marker.id == party.hoveredMember);
            rising |= paintLoot(g, projection, marker, x, y);
            rising |= x > -120 && x < projection.width() + 120 && y > -80 && y < projection.height() + 80
                && paintXp(g, party.xp(marker.id), party::skill, x + 14, y - 6);
        }
        party.ticker.painted(rising);
    }

    static final Color UNTRADEABLE = new Color(240, 210, 120);

    /** "1.2M", "450K", as Ground Items writes values. */
    static String shortValue(long value) {
        return value >= 1_000_000_000 ? String.format(Locale.ROOT, "%.1fB", value / 1e9)
            : value >= 10_000_000 ? value / 1_000_000 + "M"
            : value >= 1_000_000 ? String.format(Locale.ROOT, "%.1fM", value / 1_000_000.0) : value / 1000 + "K";
    }

    /** A sum of coins: under a thousand as it is, else as {@link #shortValue}. */
    static String coins(long value) {
        return value < 1000 ? FriendsWidget.AMOUNT.format(value) : shortValue(value);
    }

    /** Drops rising above the marker, newest lowest; true while any shows. */
    boolean paintLoot(Graphics2D g, Projection projection, Marker marker, double x, double y) {
        var showing = party.members.loot(marker.id, System.currentTimeMillis());
        if (showing.isEmpty()) {
            return false;
        }
        // Off screen: nothing to keep the map drawing for.
        if (x < -120 || x > projection.width() + 120 || y < -40 || y > projection.height() + 40 + 22 * showing.size() + 60) {
            return false;
        }
        long now = System.currentTimeMillis();
        var layer = (Graphics2D) g.create();
        try {
            layer.setFont(NAME_FONT);
            var metrics = layer.getFontMetrics();
            for (int k = 0; k < showing.size(); k++) {
                var drop = showing.get(k);
                double t = min(1, (now - drop.at) / (double) PartyMembers.LOOT_MS), rise = 1 - pow(1 - t, 3);
                float alpha = (float) (t < 0.75 ? 1 : 1 - (t - 0.75) / 0.25);
                layer.setComposite(getInstance(SRC_OVER, max(0, alpha)));
                double top = y - 22 - (showing.size() - 1 - k) * 22 - rise * 50;
                String text = drop.name != null ? drop.name : shortValue(drop.value);
                BufferedImage icon = party.item(drop.item, drop.quantity);
                int iconW = icon == null ? 0 : 26;
                double width = iconW + metrics.stringWidth(text) + 10, left = x - width / 2;
                layer.setColor(new Color(20, 20, 24, 190));
                layer.fill(new RoundRectangle2D.Double(left, top - 12, width, 22, 10, 10));
                if (icon != null) {
                    layer.drawImage(icon, (int) left + 2, (int) top - 12, 26, 22, null);
                }
                // Ground Items' colours for a value: medium, high, insane.
                TextSprites.shadowed(layer, text, (float) (left + iconW + 5), (float) top + 3,
                    drop.name != null ? UNTRADEABLE : drop.value >= 10_000_000 ? new Color(255, 102, 178)
                    : drop.value >= 1_000_000 ? new Color(153, 255, 153) : new Color(102, 178, 255));
            }
        } finally {
            layer.dispose();
        }
        return true;
    }

    /**
     * Experience drops rising from (x, y) as the game's own do, newest lowest, each skill's icon before its amount (beside
     * every member's marker, and in the sidebar's party list); true while any shows.
     */
    static boolean paintXp(Graphics2D g, List<PartyMembers.Drop> showing, IntFunction<BufferedImage> icons, double x,
        double y) {
        if (showing.isEmpty()) {
            return false;
        }
        long now = System.currentTimeMillis();
        var layer = (Graphics2D) g.create();
        try {
            layer.setFont(SMALL_FONT);
            for (int k = 0; k < showing.size(); k++) {
                var drop = showing.get(k);
                double t = min(1, (now - drop.at) / (double) PartyMembers.DROP_MS);
                layer.setComposite(getInstance(SRC_OVER,
                    (float) max(0, t < 0.7 ? 1 : 1 - (t - 0.7) / 0.3)));
                double top = y - (showing.size() - 1 - k) * 15 - (1 - pow(1 - t, 3)) * 30;
                BufferedImage icon = icons.apply(drop.skill);
                String amount = "+" + FriendsWidget.AMOUNT.format(drop.amount);
                float tx = (float) x + (icon == null ? 0 : 15);
                // A backdrop, so it reads over the map or a page.
                layer.setColor(new Color(20, 20, 24, 170));
                layer.fill(new RoundRectangle2D.Double(x - 2, top - 12, tx - x + layer.getFontMetrics().stringWidth(amount)
                    + 5, 15, 6, 6));
                if (icon != null) {
                    layer.drawImage(icon, (int) x, (int) top - 11, 13, 13, null);
                }
                TextSprites.shadowed(layer, amount, tx, (float) top, Color.WHITE);
            }
        } finally {
            layer.dispose();
        }
        return true;
    }

    static void paintMarker(Graphics2D g, Projection projection, Marker marker, WorldPoint at, double x,
        double y, int myWorld, boolean chosen, boolean hover) {
        if (x < -40 || y < -40 || x > projection.width() + 40 || y > projection.height() + 40) {
            return;
        }
        float alpha = marker.alpha;
        boolean otherFloor = at.getPlane() != projection.plane();
        if (otherFloor) {
            alpha *= 0.6f;
        }
        var layer = (Graphics2D) g.create();
        try {
            layer.setComposite(getInstance(SRC_OVER, alpha));
            Color color = color(marker.id);
            double r = 7.5;
            var disc = circle(x, y, r);
            if (marker.house) {
                PlayerMarker.box(layer, x, y, r, color);
                layer.setFont(NAME_FONT);
                text(layer, "House", x - layer.getFontMetrics().stringWidth("House") / 2.0, y - r - 12);
            }
            layer.setColor(RouteFeature.alpha(color, 60));
            layer.fill(circle(x, y, r + 5));
            if (marker.avatar != null) {
                Shape clip = layer.getClip();
                layer.clip(disc);
                layer.drawImage(marker.avatar, (int) round(x - r), (int) round(y - r),
                    (int) round(r * 2), (int) round(r * 2), null);
                layer.setClip(clip);
            } else {
                layer.setColor(color);
                layer.fill(disc);
                String initial = marker.name == null || marker.name.isEmpty() ? "?"
                    : marker.name.substring(0, 1).toUpperCase(Locale.ROOT);
                layer.setFont(NAME_FONT);
                var metrics = layer.getFontMetrics();
                layer.setColor(new Color(15, 15, 20));
                text(layer, initial, x - metrics.stringWidth(initial) / 2.0, y + metrics.getAscent() / 2.0 - 1.5);
            }
            // White: gold would read as the local player's yellow marker.
            ring(layer, disc, 2f, Color.WHITE);
            ring(layer, circle(x, y, r + 2), 1f, color);
            if (chosen) {
                ring(layer, circle(x, y, r + 5), 3f, Color.WHITE);
                ring(layer, circle(x, y, r + 8), 2f, color);
            }
            if (chosen || hover) {
                paintLabel(layer, marker, x, y + r + 4, color, otherFloor,
                    marker.world > 0 && myWorld > 0 && marker.world != myWorld);
            }
        } finally {
            layer.dispose();
        }
    }

    static void ring(Graphics2D g, Shape shape, float width, Color color) {
        g.setStroke(new BasicStroke(width));
        g.setColor(color);
        g.draw(shape);
    }

    static void paintLabel(Graphics2D g, Marker marker, double x, double top, Color color,
        boolean otherFloor, boolean otherWorld) {
        String name = marker.name != null ? marker.name : "Party member";
        String detail = detail(marker, otherFloor, otherWorld);
        g.setFont(NAME_FONT);
        var nameMetrics = g.getFontMetrics();
        int nameWidth = nameMetrics.stringWidth(name);
        var smallMetrics = g.getFontMetrics(SMALL_FONT);
        int detailWidth = detail == null ? 0 : smallMetrics.stringWidth(detail);
        int width = max(nameWidth, detailWidth) + 10;
        int height = nameMetrics.getHeight() + (detail == null ? 0 : smallMetrics.getHeight()) + 2;
        double left = x - width / 2.0;
        var box = new RoundRectangle2D.Double(left, top, width, height, 8, 8);
        g.setColor(LABEL_BACKGROUND);
        g.fill(box);
        ring(g, box, 1f, color);
        double textLeft = x - nameWidth / 2.0;
        float baseline = (float) (top + 1 + nameMetrics.getAscent());
        g.setColor(Color.WHITE);
        text(g, name, textLeft, baseline);
        if (detail != null) {
            g.setFont(SMALL_FONT);
            g.setColor(otherWorld ? FriendsWidget.OTHER_WORLD : Floating.LIGHT);
            text(g, detail, x - detailWidth / 2.0, top + 1 + nameMetrics.getHeight() + smallMetrics.getAscent());
        }
    }

    /** "World 330 · floor 1 · 3 min ago", leaving out what is not worth saying. */
    static String detail(Marker marker, boolean otherFloor, boolean otherWorld) {
        var text = new StringJoiner(" · ");
        if (otherWorld) {
            text.add("World " + marker.world);
        }
        if (otherFloor) {
            text.add("floor " + marker.point.getPlane());
        }
        if (marker.stale()) {
            text.add(ago(marker.ageMillis));
        }
        return text.length() == 0 ? null : text.toString();
    }

    static String ago(long millis) {
        long minutes = millis / 60_000;
        return minutes < 1 ? (millis / 1000) + " s ago" : minutes + " min ago";
    }
}

package com.hdmapreforged;

import static com.hdmapreforged.GameWalk.*;
import static java.util.stream.Collectors.*;
import static com.hdmapreforged.RouteFiles.*;
import static com.hdmapreforged.IntMap.MISSING;
import static com.hdmapreforged.Route.Outcome.*;
import static java.lang.Math.*;
import static com.hdmapreforged.Tiles.*;

import com.hdmapreforged.Route.*;
import java.io.*;
import java.nio.charset.*;
import java.util.*;
import java.util.function.*;
import java.util.stream.*;
import lombok.*;

/**
 * A* over tiles, sea blocks and jumps ({@link Edge}); costs in half ticks. The heuristic stays a lower bound by folding
 * underground y onto the surface (y − 6400) and bounding far/cheap jumps with a backward search over the jumps alone.
 * Beside it a flood runs back from the goal over the same ways ({@link Backward}): the first side to run out of nodes
 * settles whether the goal is in reach at all, so a target shut off from the player (a quest's door, an island, an
 * instance) is proved out of reach after its own small area instead of after the whole world. Thread-safe: each search
 * keeps its own state; the maps are immutable (one's house is swapped whole).
 */
final class Pathfinder {
    /** Half ticks. */
    static final int RUN = 1, WALK = 2, DOOR = 2;
    /** Vines, jungle or a web: needs a tool, so walking around is better. */
    static final int OBSTACLE = 10, SAIL = CELL;
    static final String UNKNOWN_NEEDS = PoiType.t("dUnknownNeeds");
    static final int SNAP_RADIUS = 12, LONG_JUMP = 24, BLOCK = 8;
    static final int[] DX = {1, -1, 0, 0, 1, 1, -1, -1};
    static final int[] DY = {0, 0, 1, -1, 1, -1, 1, -1};

    final CollisionMap map;
    final SeaMap sea;
    /** Every passage the planner knows besides the request's: stairs, entrances, map links and the like. */
    final List<Edge> passages;
    /** The passages that are Agility shortcuts, which a request adds only for a player who meets them. */
    final List<ShortcutPassage> shortcutPassages;
    final EdgeIndex passagesByOrigin;
    /** Where the Agility shortcuts start (shortcuts.tsv, the game's passages that are one): ways out for {@link #pocket}. */
    final IntMap shortcutStarts = new IntMap(1024);
    final EdgeIndex passagesByDestination;
    /** The jumps the heuristic must know when a tile costs a half tick (running, sailing) and when it costs one. */
    final List<Edge> heuristicPassages, walkingPassages;
    /**
     * Walking steps a gates.tsv row between two neighbouring tiles closes (a guild's door, which the game's collision has
     * as an ordinary door): per origin tile, a bit per direction of {@link #DX}; the row's own edge opens the step to
     * players who meet its needs. Read only after the constructor.
     */
    final IntMap closedSteps = new IntMap(64);
    /** The heuristic's jump bounds as last worked out, by goal and the request's jumps: re-plans and a tour's stops. */
    final Map<List<Integer>, int[][]> bounds = Collections.synchronizedMap(new LruMap<>(32, BOUNDS_KEPT));
    /** Enough for a tour's stops (up to 12) and the player's own target. */
    static final int BOUNDS_KEPT = 16;

    Pathfinder(CollisionMap map, SeaMap sea) {
        this.map = map;
        this.sea = sea;
        var edges = new ArrayList<Edge>();
        var atShortcuts = new ArrayList<ShortcutPassage>();
        var ways = ShortcutPassage.allWays();
        // The map version's passages as its build worked them out (BuildPassages), in its order, which breaks ties in
        // the search (a route.zip made before passages.tsv is not used: HdMapReforgedPlugin.useVersion). The Agility shortcuts among them are added only
        // to requests whose player meets one of their ways.
        table(DIR + "passages.tsv", c -> {
            int at = parse(c[1]), to = parse(c[2]);
            if (c[0].equals("S")) {
                shortcutStarts.put(at, 0);
            } else if (c[0].equals("C")) {
                closedSteps.put(at, Integer.parseInt(c[2]));
            } else if (c[0].equals("P") && min(at, to) >= 0) {
                var e = new Edge(at, to, Edge.Kind.valueOf(c[3]), c[7], c[6].equals("?") ? UNKNOWN_NEEDS
                    : c[6].isEmpty() ? null : c[6], Integer.parseInt(c[4]));
                if (c[5].isEmpty()) {
                    edges.add(e);
                } else {
                    atShortcuts.add(new ShortcutPassage(e, Arrays.stream(ints(c[5])).mapToObj(ways::get)
                        .collect(toUnmodifiableList())));
                }
            }
            return null;
        });
        shortcutPassages = Collections.unmodifiableList(atShortcuts);
        passages = Collections.unmodifiableList(edges);
        passagesByOrigin = EdgeIndex.of(edges, 0, false);
        passagesByDestination = EdgeIndex.of(edges, 0, true);
        heuristicPassages = edges.stream().filter(e -> shortCut(e, RUN)).collect(toUnmodifiableList());
        walkingPassages = edges.stream().filter(e -> shortCut(e, WALK)).collect(toUnmodifiableList());
    }

    /** Lists the planner and its texts use (the map version's lists.tsv): by name, its items; the first of a name. */
    static final Table<Map<String, List<String>>> LISTS = new Table<>(() -> rows(
        DIR + "lists.tsv").stream().collect(toMap(c -> c[0], c -> List.of(c).subList(1, c.length),
        (a, b) -> a)));

    /** A list by its name; empty while the map version has none. */
    static List<String> list(String name) {
        return LISTS.get().getOrDefault(name, List.of());
    }

    /** A list's items as {@code parse} reads them; an item it cannot read (throws, gives null) is left out. */
    static <T> List<T> list(String name, Function<String, T> parse) {
        return each(list(name), parse);
    }

    /** A list of "key=value" items as a map, each value as {@code parse} reads it; the first of a key. */
    static <T> Map<String, T> pairs(String list, Function<String, T> parse) {
        return list(list, item -> {
            var p = item.split("=", 2);
            return Map.entry(p[0], parse.apply(p[1]));
        }).stream().collect(toMap(Map.Entry::getKey, Map.Entry::getValue, (a, b) -> a));
    }

    /** Whether the step from {@code node} by (dx, dy) is one a gates.tsv row closes. */
    boolean closed(int node, int dx, int dy) {
        int closed = closedSteps.get(node);
        for (int d = 0; closed != MISSING && d < DX.length; d++) {
            if (DX[d] == dx && DY[d] == dy) {
                return (closed & 1 << d) != 0;
            }
        }
        return false;
    }

    /** Tiles a walk reaches out in the open, not shut in by walls. */
    static final int OPEN = 120;

    /**
     * Whether walking from a tile reaches {@code limit} tiles ({@link #OPEN}: out in the open), or one that {@code way}
     * leads out of; when not, {@code way} saw each tile walked to once.
     */
    static boolean reaches(CollisionMap map, int node, IntPredicate way, int limit) {
        // Run for many tiles: no boxing.
        int[] queue = new int[limit];
        var seen = new IntMap(2 * limit);
        queue[0] = node;
        seen.put(node, 0);
        for (int head = 0, tail = 1; head < tail; head++) {
            int at = queue[head];
            if (way.test(at)) {
                return true;
            }
            for (int d = 0; d < 4; d++) {
                int next = pack(x(at) + DX[d], y(at) + DY[d], z(at));
                if (map.canStep(x(at), y(at), z(at), DX[d], DY[d]) && seen.get(next) == MISSING) {
                    seen.put(next, 0);
                    if (++tail >= limit) {
                        return true;
                    }
                    queue[tail - 1] = next;
                }
            }
        }
        return false;
    }

    /** A bundled table's lines split at tabs, without {@code #} comments; what could be read. */
    static List<String[]> rows(String resource) {
        var rows = new ArrayList<String[]>();
        InputStream in = RouteFiles.open(resource);
        if (in != null) {
            try {
                rows(in, 0, rows::add);
            } catch (IOException e) {
                // Those read so far.
            }
        }
        return rows;
    }

    /** Each row of a bundled table as {@code parse} reads it; a row it cannot read (throws, gives null) is left out. */
    static <T> List<T> table(String resource, Function<String[], T> parse) {
        return each(rows(resource), parse);
    }

    static <I, T> List<T> each(List<I> items, Function<I, T> parse) {
        var read = new ArrayList<T>();
        for (var item : items) {
            try {
                T row = parse.apply(item);
                if (row != null) {
                    read.add(row);
                }
            } catch (RuntimeException e) {
                // That one only.
            }
        }
        return Collections.unmodifiableList(read);
    }

    /** Each line but {@code #} comments, split as {@code line.split("\t", limit)} does; closes {@code in}. */
    static void rows(InputStream in, int limit, Consumer<String[]> each) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8))) {
            for (String line = reader.readLine(); line != null; line = reader.readLine()) {
                if (!line.startsWith("#")) {
                    each.accept(line.split("\t", limit));
                }
            }
        }
    }

    /** A cell's space-separated integers ("2920 4700" {@literal ->} {2920, 4700}). */
    static int[] ints(String cell) {
        return Arrays.stream(cell.trim().split("\\s+")).mapToInt(Integer::parseInt).toArray();
    }

    /** Folded y: most dungeons lie 6400 tiles north of what is above them. */
    static int fy(int node) {
        int y = y(node);
        return y >= 6400 ? y - 6400 : y;
    }

    /** Round the fold: one step from y 6399 to 6400 goes from the top of the folded range to its bottom. */
    static int folded(int a, int b) {
        int dy = abs(fy(a) - fy(b));
        return max(abs(x(a) - x(b)), min(dy, 6400 - dy));
    }

    /** Jumps the heuristic must know (a tile costing {@code step}), else it would overestimate and miss the best way. */
    static boolean shortCut(Edge e, int step) {
        if (e.from == Edge.ANYWHERE) {
            return false;
        }
        int length = folded(e.from, e.to);
        return length > LONG_JUMP || e.cost < length * step;
    }

    /** {@code out}: more ways out of a pocket than the passages (a request's own: fairy rings, boats, shortcuts). */
    int resolveGoal(int target, IntPredicate out) {
        if (isSea(target)) {
            return target;
        }
        int x = x(target), y = y(target), z = z(target);
        if (map.walkable(x, y, z)) {
            return target;
        }
        // No ground on this floor around the spot, but the very spot is ground on another floor (a dungeon's raised part
        // the map shows as floor 1, ours as floor 2: the Brimhaven Dungeon's at 2633 9491): that floor's spot.
        if (map.walkableNear(x, y, z, 2) < 0) {
            for (int dz = 1; dz < 4; dz++) {
                for (int other : new int[]{z - dz, z + dz}) {
                    if (other >= 0 && other <= 3 && map.walkable(x, y, other) && !pocket(pack(x, y, other), out)) {
                        return pack(x, y, other);
                    }
                }
            }
        }
        int near = nearestOpen(x, y, z, SNAP_RADIUS, out);
        if (near >= 0 && !pocket(near, out)) {
            return near;
        }
        if (z == 0 && sea != null && sea.sailable(x / CELL, y / CELL, 99)) {
            // Open water with only an islet or a ledge near (a sea creature): sailed to, not walked to the islet.
            return seaAt(x, y);
        }
        // Only a pocket here: the spot may be given on another floor than the ground it marks.
        int there = otherFloor(x, y, z, 3, true, out);
        if (there >= 0 || near >= 0) {
            return there >= 0 ? there : near;
        }
        // A spot given on the wrong floor: the same spot on another floor first.
        near = otherFloor(x, y, z, 1, false, out);
        if (near < 0) {
            near = otherFloor(x, y, z, SNAP_RADIUS, false, out);
        }
        return near;
    }

    /** {@code open}: the nearest open non-pocket tile, else any walkable one. */
    int otherFloor(int x, int y, int z, int radius, boolean open, IntPredicate out) {
        for (int dz = 1; dz < 4; dz++) {
            for (int other : new int[]{z - dz, z + dz}) {
                int near = other < 0 || other > 3 ? -1
                    : open ? nearestOpen(x, y, other, radius, out) : map.walkableNear(x, y, other, radius);
                if (near >= 0 && !(open && pocket(near, out))) {
                    return near;
                }
            }
        }
        return -1;
    }

    /** A start the data calls unwalkable (a boat's deck, a stepping stone) begins from the nearest open tile. */
    int startNode(int start) {
        if (start < 0 || isSea(start) || map.walkable(x(start), y(start), z(start))) {
            return start;
        }
        int near = nearestOpen(x(start), y(start), z(start), 5, at -> false);
        return near >= 0 ? near : start;
    }

    /** Nearest walkable non-pocket tile round (not on) the spot, else the first walkable one met, else -1. */
    int nearestOpen(int x, int y, int z, int radius, IntPredicate out) {
        int open = map.nearest(x, y, z, 1, radius, x, y, at -> pocket(at, out), false);
        return open >= 0 ? open : map.nearest(x, y, z, 1, radius, x, y, null, true);
    }

    /** A small shut-in area (behind bank booths) with no passages; ground left by an Agility shortcut is not one. */
    boolean pocket(int node) {
        return pocket(node, at -> false);
    }

    boolean pocket(int node, IntPredicate out) {
        return !reaches(map, node, at -> passagesByOrigin.get(at) != null || shortcutStarts.get(at) != MISSING
            || out.test(at), OPEN);
    }

    /** Where a request's own jumps start (fairy rings, boats, a shortcut's icon): ways out of a pocket for its target. */
    static IntPredicate waysOut(RouteRequest request) {
        var starts = new IntMap(64);
        request.edges.forEach(e -> starts.put(e.from, 0));
        return at -> starts.get(at) != MISSING;
    }

    Route find(RouteRequest request, BooleanSupplier cancelled) {
        return find(request, cancelled, Integer.MAX_VALUE);
    }

    /**
     * The same, giving up (as at the node limit, without a verdict) once no way under {@code costLimit} half ticks can
     * be found: looking for the quickest of several places, a place that cannot beat the best so far stops early.
     */
    Route find(RouteRequest request, BooleanSupplier cancelled, int costLimit) {
        return outside(request, kept(request, cancelled, costLimit), cancelled, costLimit);
    }

    Route kept(RouteRequest request, BooleanSupplier cancelled, int costLimit) {
        Route route = walkOrSail(request, cancelled, costLimit);
        // Kept out of the Wilderness, yet no way around it gets there (the Mage Arena's bank, Entrana's dungeon without a
        // boat): through it after all, and the route says so.
        // Not when it only stopped at a cost limit: a way around may cost more, and the Wilderness is no cheaper way.
        if (avoids(request) && route.keptOut && (route.outcome == NEAREST
            || route.outcome == NONE) && !route.limited && !cancelled.getAsBoolean()) {
            Route through = walkOrSail(request.viaWild(), cancelled, costLimit);
            // Out of reach only if the search through it tried everything too; then its proof is the one kept (the one
            // kept out counts every Wilderness tile as out of reach, so a way in there would not be searched again).
            return through.outcome == FOUND ? through.withViaWild(true) : through.outcome == CANCELLED ? route
                : through.exhausted ? route.withReached(through.reached) : route.withExhausted(false).withReached(null);
        }
        return route;
    }

    /**
     * A target the search proved shut off (ground the game never lets one walk, past a cave's wall: an icon drawn there):
     * the route to the nearest open ground outside it instead, which that search gave up on before getting to.
     */
    Route outside(RouteRequest request, Route route, BooleanSupplier cancelled, int costLimit) {
        int target = request.target;
        if (route.outcome != NEAREST || route.reached == null || !route.reached.complement || target < 0 || isSea(target)) {
            return route;
        }
        // The first open tile round the target that the target is not reached from.
        int near = map.nearest(x(target), y(target), z(target), 1, SNAP_RADIUS, 0, 0,
            at -> !route.reached.contains(at) || pocket(at) || cancelled.getAsBoolean(), true);
        if (near < 0) {
            return route;
        }
        var ways = route.viaWild ? request.viaWild() : request;
        Route there = walkOrSail(ways.between(request.start, near).withBank(request.bank), cancelled, costLimit);
        // Still out of reach itself: the proof stays, so it is not searched again from here.
        return there.outcome != FOUND ? route : there.near(route);
    }

    Route walkOrSail(RouteRequest request, BooleanSupplier cancelled, int costLimit) {
        Route route = search(request, cancelled, costLimit);
        // Left without their boat (a place on land): sail only when walking does not get there (an island).
        if (request.boat != null && (route.outcome == NEAREST || route.outcome == NONE) && !route.limited
            && !cancelled.getAsBoolean()) {
            Route sailed = search(request.boat, cancelled, costLimit);
            if (sailed.outcome == FOUND) {
                return sailed;
            }
            Route walked = sailed.keptOut && !route.keptOut ? route.withKeptOut(true) : route;
            // Out of reach only if the boat's search tried everything too (not when it stopped at a limit).
            return sailed.outcome == CANCELLED || sailed.exhausted ? walked : walked.withExhausted(false).withReached(null);
        }
        return route;
    }

    /** Whether a search for this request stays out of the Wilderness: asked to, and it neither starts nor ends there. */
    boolean avoids(RouteRequest request) {
        int start = startNode(request.start);
        return request.noWild && !wilderness(request.target) && !(start >= 0 && wilderness(start));
    }

    Route search(RouteRequest request, BooleanSupplier cancelled, int costLimit) {
        int target = request.target, goal = resolveGoal(target, waysOut(request));
        var all = new ArrayList<Edge>(passages.size() + request.edges.size() + request.startEdges.size());
        all.addAll(passages);
        int requestOffset = all.size();
        all.addAll(request.edges);
        int startOffset = all.size();
        all.addAll(request.startEdges);
        var requestByOrigin = EdgeIndex.of(request.edges, requestOffset, false);
        int towards = goal >= 0 ? goal : target, step = request.running ? RUN : WALK;
        // Walking, each tile costs a whole tick; at sea a half one (a block of 4 tiles costs 2 ticks).
        int scale = request.sailingLevel < 0 ? step : RUN;
        var jumps = new ArrayList<Edge>(scale == RUN ? heuristicPassages : walkingPassages);
        var key = new ArrayList<Integer>(List.of(towards, scale));
        for (Edge e : request.edges) {
            if (shortCut(e, scale)) {
                jumps.add(e);
                key.addAll(List.of(e.from, e.to, e.cost));
            }
        }
        // Worked out without the map's lock: a tour's searches must not hold up the player's.
        var made = bounds.get(key);
        if (made == null) {
            made = Heuristic.bounds(jumps, towards, scale);
            bounds.putIfAbsent(key, made);
        }
        var heuristic = new Heuristic(towards, scale, made[0], made[1]);

        var nodes = new NodeTable();
        var open = new LongHeap();
        int start = startNode(request.start);
        // Out of the Wilderness, unless the route starts or ends there (from a house, start is -1: not in it).
        boolean avoid = avoids(request);
        if (start >= 0) {
            relax(nodes, open, heuristic, start, 0, NodeTable.START);
        }
        // Whether a step or jump into the Wilderness was left out (else going through it gets nowhere further).
        boolean keptOut = jumps(IntStream.range(startOffset, all.size()).toArray(), all, nodes, open, heuristic, 0, avoid);
        // Back from the goal, in turns with the search: once it runs out, the goal is in reach from exactly what it
        // flooded. No goal (no ground near the target): out of reach from anywhere.
        var back = goal >= 0 ? new Backward(goal, all, requestOffset, request, avoid) : null;
        Reached proof = goal >= 0 ? null : new Reached(new NodeSet(), true);
        int stopAt = goal >= 0 ? Integer.MAX_VALUE : NEAREST_NODES, best = -1;
        long bestScore = Long.MAX_VALUE;
        int popped = 0;
        boolean limited = false;
        int found = -1;
        while (!open.isEmpty() && popped < stopAt) {
            long item = open.pop();
            int node = (int) item, g = nodes.cost(node);
            if ((int) (item >>> 32) != g + heuristic.h(node)) {
                continue;
            }
            if ((int) (item >>> 32) > costLimit) {
                // Every way left costs at least this (the heuristic never overestimates): nothing under the limit.
                limited = true;
                break;
            }
            if ((++popped & (TURN - 1)) == 0) {
                if (cancelled.getAsBoolean()) {
                    return new Route(CANCELLED, List.of(), 0, target, -1, false, false, popped);
                }
                if (back != null && back.flood(TURN)) {
                    if (back.reaches(start, startOffset)) {
                        // In reach: the search alone finds the way.
                        back = null;
                    } else {
                        // Out of reach: on a little further for the nearest spot the way gets to, then done.
                        proof = new Reached(back.seen, true);
                        keptOut |= back.keptOut;
                        stopAt = popped + NEAREST_NODES;
                        back = null;
                    }
                }
            }
            if (node == goal) {
                found = node;
                break;
            }
            if (!isSea(node)) {
                long score = (long) (distance(node, target) + (z(node) != z(target) ? 32 : 0)) << 32 | g;
                if (score < bestScore) {
                    bestScore = score;
                    best = node;
                }
            }
            if (nodes.size > request.nodeLimit) {
                limited = true;
                break;
            }
            if (isSea(node)) {
                int cx = cellX(node), cy = cellY(node);
                for (int d = 0; d < 8; d++) {
                    int nx = cx + DX[d], ny = cy + DY[d];
                    if (sea.sailable(nx, ny, request.sailingLevel)) {
                        relax(nodes, open, heuristic, sea(nx, ny), g + SAIL, -1 - d);
                    }
                }
            } else {
                int x = x(node), y = y(node), z = z(node), closed = closedSteps.get(node);
                for (int d = 0; d < 8; d++) {
                    if (closed != MISSING && (closed & 1 << d) != 0) {
                        continue;
                    }
                    if (map.canStep(x, y, z, DX[d], DY[d])) {
                        int next = pack(x + DX[d], y + DY[d], z);
                        if (avoid && wilderness(next)) {
                            keptOut = true;
                            continue;
                        }
                        int cost = step + (d < 4 && map.door(x, y, z, DX[d], DY[d]) ? DOOR : 0)
                            + (map.isObstacle(x + DX[d], y + DY[d], next) ? OBSTACLE : 0);
                        relax(nodes, open, heuristic, next, g + cost, -1 - d);
                    }
                }
                keptOut |= jumps(passagesByOrigin.get(node), all, nodes, open, heuristic, g, avoid);
            }
            keptOut |= jumps(requestByOrigin.get(node), all, nodes, open, heuristic, g, avoid);
        }
        // Tried everything, or proved from the goal's side: what was reached (or not) tells where else the target is out
        // of reach.
        boolean tried = !limited && open.isEmpty(), exhausted = found < 0 && (proof != null || tried);
        Reached reached = found >= 0 ? null : tried ? new Reached(nodes.reached(), false) : proof;
        int end = found >= 0 ? found : best;
        var steps = end < 0 ? List.<Step>of() : steps(nodes, all, startOffset, end, found >= 0 ? target : -1, avoid);
        Route route = end < 0 ? new Route(NONE, steps, 0, target, -1, exhausted, limited, popped, reached)
            : new Route(found >= 0 ? FOUND : NEAREST, steps, nodes.cost(end), target,
            steps.isEmpty() ? end : steps.get(steps.size() - 1).last(), exhausted, limited, popped, reached);
        return keptOut ? route.withKeptOut(true) : route;
    }

    /** Nodes the search pops between turns of the flood back from the goal (and checks for a cancel); a power of two. */
    static final int TURN = 4096;
    /**
     * Nodes the search goes on for once the goal is proved out of reach, for the nearest spot it gets to (the far side
     * of a locked door): the way there is what the player sees. A flood of the world would be about 1.7 million.
     */
    static final int NEAREST_NODES = 100_000;

    /**
     * The nodes the goal can be reached from, flooded back from it over the same ways the search takes forward (walking,
     * sailing, passages, the request's jumps), a turn at a time. Done, it holds them all: the goal is in reach from the
     * start or a teleport's landing only if they are in it.
     */
    final class Backward {
        final NodeSet seen = new NodeSet();
        int[] queue = new int[TURN];
        int head, tail;
        final List<Edge> all;
        final EdgeIndex requestByDestination;
        final int sailingLevel;
        final boolean avoid;
        /** A step or jump out of the Wilderness was left out: through it, the goal may be in reach from more. */
        boolean keptOut;

        Backward(int goal, List<Edge> all, int requestOffset, RouteRequest request, boolean avoid) {
            this.all = all;
            requestByDestination = EdgeIndex.of(request.edges, requestOffset, true);
            sailingLevel = request.sailingLevel;
            this.avoid = avoid;
            visit(goal);
        }

        void visit(int node) {
            if (seen.add(node)) {
                if (tail == queue.length) {
                    if (head > queue.length / 2) {
                        System.arraycopy(queue, head, queue, 0, tail - head);
                        tail -= head;
                        head = 0;
                    } else {
                        queue = Arrays.copyOf(queue, queue.length * 2);
                    }
                }
                queue[tail++] = node;
            }
        }

        /** Floods up to {@code budget} nodes more; whether it is done (nothing more leads to the goal). */
        boolean flood(int budget) {
            while (head < tail && budget-- > 0) {
                int node = queue[head++];
                if (isSea(node)) {
                    // Sailed into from any block around it, when it can be sailed.
                    int cx = cellX(node), cy = cellY(node);
                    if (sailingLevel >= 0 && sea.sailable(cx, cy, sailingLevel)) {
                        for (int d = 0; d < 8; d++) {
                            visit(sea(cx + DX[d], cy + DY[d]));
                        }
                    }
                } else {
                    int x = x(node), y = y(node), z = z(node);
                    for (int d = 0; d < 8; d++) {
                        int px = x - DX[d], py = y - DY[d];
                        if (!map.canStep(px, py, z, DX[d], DY[d])) {
                            continue;
                        }
                        int from = pack(px, py, z), closed = closedSteps.get(from);
                        if (closed == MISSING || (closed & 1 << d) == 0) {
                            visitFrom(from);
                        }
                    }
                }
                jumpsTo(passagesByDestination.get(node));
                jumpsTo(requestByDestination.get(node));
            }
            return head == tail;
        }

        void jumpsTo(int[] edges) {
            if (edges != null) {
                for (int i : edges) {
                    int from = all.get(i).from;
                    if (from != Edge.ANYWHERE) {
                        visitFrom(from);
                    }
                }
            }
        }

        /** Kept out of the Wilderness, the search never stands there: not a node the goal is reached from. */
        void visitFrom(int from) {
            if (avoid && wilderness(from)) {
                keptOut = true;
            } else {
                visit(from);
            }
        }

        /** Done: whether the goal is in reach from the start or from where a jump from anywhere lands. */
        boolean reaches(int start, int startOffset) {
            if (start >= 0 && seen.contains(start)) {
                return true;
            }
            for (int i = startOffset; i < all.size(); i++) {
                int to = all.get(i).to;
                if (!(avoid && wilderness(to)) && seen.contains(to)) {
                    return true;
                }
            }
            return false;
        }
    }

    /** Relaxes the jumps; whether one into the Wilderness was left out. */
    static boolean jumps(int[] edges, List<Edge> all, NodeTable nodes, LongHeap open, Heuristic heuristic, int g,
        boolean noWild) {
        if (edges == null) {
            return false;
        }
        boolean keptOut = false;
        for (int i : edges) {
            Edge e = all.get(i);
            if (!(noWild && wilderness(e.to))) {
                relax(nodes, open, heuristic, e.to, g + e.cost, i);
            } else {
                keptOut = true;
            }
        }
        return keptOut;
    }

    static void relax(NodeTable nodes, LongHeap open, Heuristic heuristic, int to, int cost, int via) {
        if (cost < nodes.cost(to)) {
            nodes.put(to, cost, via);
            open.push(key(cost + heuristic.h(to), to));
        }
    }

    static long key(int f, int node) {
        return (long) f << 32 | (node & 0xffffffffL);
    }

    /** The node before on the way found: where its jump or step began; -1 at the start (or a jump from anywhere). */
    static int parent(NodeTable nodes, List<Edge> all, int startOffset, int node) {
        int via = nodes.via(node), d = -1 - via;
        return via >= startOffset || via == NodeTable.START ? -1 : via >= 0 ? all.get(via).from : isSea(node)
            ? sea(cellX(node) - DX[d], cellY(node) - DY[d])
            : pack(x(node) - DX[d], y(node) - DY[d], z(node));
    }

    List<Step> steps(NodeTable nodes, List<Edge> all, int startOffset, int end, int target, boolean avoid) {
        // The walk drawn as the game walks it keeps to the steps the search kept to: no shut gate, no Wilderness.
        Shut shut = (x, y, z, dx, dy) -> closed(pack(x, y, z), dx, dy)
            || avoid && wilderness(pack(x + dx, y + dy, z));
        var reversed = new ArrayList<Step>();
        var run = new ArrayList<Integer>();
        int node = end;
        run.add(node);
        while (true) {
            int via = nodes.via(node), parent = parent(nodes, all, startOffset, node);
            if (via >= 0) {
                flush(reversed, run, nodes, shut);
                Edge e = all.get(via);
                int from = parent >= 0 ? parent : node;
                reversed.add(new Step(Step.Kind.valueOf(e.kind.name()), new int[]{from, node}, e.name,
                    e.detail, e.time, 0, List.of(), e.category));
                run.clear();
            }
            if (parent < 0) {
                break;
            }
            run.add(parent);
            node = parent;
        }
        flush(reversed, run, nodes, shut);
        Collections.reverse(reversed);
        int x = x(target), y = y(target), z = z(target);
        // A target one cannot stand on (a ladder clicked on the map): the free tiles beside it with no wall between.
        int[] beside = target < 0 || isSea(target) || map.walkable(x, y, z) ? new int[0] : IntStream.range(0, 4)
            .filter(d -> map.walkable(x + DX[d], y + DY[d], z) && map.straightOpen(x + DX[d], y + DY[d], z, -DX[d], -DY[d]))
            .map(d -> pack(x + DX[d], y + DY[d], z)).toArray();
        for (int i = 1; i <= reversed.size(); i++) {
            // Where the game walks as a passage (its sides) or that target is clicked where the walk to it starts.
            var walk = reversed.get(i - 1);
            var jump = i < reversed.size() ? reversed.get(i) : null;
            int[] game = walk.kind != Step.Kind.WALK ? null : path(map, shut, walk.first(), jump == null ? beside
                : all.stream().filter(e -> e.from >= 0 && e.to == jump.last() && Objects.equals(e.name, jump.name))
                .mapToInt(e -> e.from).toArray());
            if (game != null && game.length <= walk.points.length) {
                int doors = (int) IntStream.range(1, game.length).filter(k -> map.door(x(game[k - 1]), y(game[k - 1]),
                    z(game[k]), x(game[k]) - x(game[k - 1]), y(game[k]) - y(game[k - 1]))).count();
                reversed.set(i - 1, new Step(Step.Kind.WALK, game, null, walk.detail,
                    walk.cost * (game.length - 1) / (walk.points.length - 1), doors, walk.obstacles, null));
                if (jump != null) {
                    jump.points[0] = game[game.length - 1];
                }
            }
        }
        return reversed;
    }

    /** {@code run} is collected backwards. */
    void flush(List<Step> reversed, List<Integer> run, NodeTable nodes, Shut shut) {
        if (run.size() >= 2) {
            int[] points = new int[run.size()];
            for (int i = 0; i < points.length; i++) {
                points[i] = run.get(points.length - 1 - i);
            }
            int cost = nodes.cost(points[points.length - 1]) - nodes.cost(points[0]);
            boolean sailing = isSea(points[0]);
            var obstacles = new ArrayList<Obstacle>();
            StringBuilder detail = new StringBuilder();
            if (!sailing) {
                points = straighten(map, shut, follow(map, shut, points));
                for (int point : points) {
                    String obstacle = map.obstacle(point);
                    if (obstacle != null) {
                        obstacles.add(new Obstacle(point, obstacle));
                        if (detail.indexOf(obstacle) < 0) {
                            detail.append(detail.length() > 0 ? "; " : "").append(obstacle);
                        }
                    }
                }
            }
            // Doors on the walk as drawn.
            int doors = 0;
            for (int i = 1; i < points.length; i++) {
                int a = points[i - 1], b = points[i], dx = x(b) - x(a), dy = y(b) - y(a);
                if (!isSea(a) && (dx == 0 || dy == 0) && map.door(x(a), y(a), z(a), dx, dy)) {
                    doors++;
                }
            }
            reversed.add(new Step(sailing ? Step.Kind.SAIL : Step.Kind.WALK, points, null,
                sailing ? hazards(points) : detail.length() > 0 ? detail.toString() : null, cost, doors, obstacles, null));
        }
        // Only the last point stays.
        run.subList(0, max(0, run.size() - 1)).clear();
    }

    String hazards(int[] points) {
        var names = new LinkedHashSet<String>();
        for (int i = 0; i < points.length; i += 3) {
            var area = sea.nearest(x(points[i]), y(points[i]));
            if (area != null && area.level > 0 && !area.hazard.isEmpty()) {
                names.add(area.hazard + " (" + area.name + ", " + area.level + " Sailing)");
            }
        }
        return names.isEmpty() ? null : "Crosses " + String.join(", ", names);
    }

    /** Folded distance, or via a jump's backward-searched bound; jump bounds cached per 8×8 block. */
    @RequiredArgsConstructor
    static final class Heuristic {
        final int goal;
        /** What a tile walked costs at least. */
        final int scale;
        final int[] origins, bounds;
        /** Per 128 × 128 folded tiles, its 8 × 8 blocks' bounds once worked out (-1 not yet): a flood needs 30,000. */
        final int[][] blocks = new int[1 << 14][];

        /** Per jump origin, the least cost from there to the goal by jumps, walking between them as the crow flies. */
        static int[][] bounds(List<Edge> jumps, int goal, int scale) {
            int n = jumps.size();
            long[] bound = new long[n];
            boolean[] done = new boolean[n];
            int[] from = new int[n], to = new int[n], cost = new int[n];
            for (int i = 0; i < n; i++) {
                Edge e = jumps.get(i);
                from[i] = e.from;
                to[i] = e.to;
                cost[i] = e.cost;
                bound[i] = (long) e.cost + scale * folded(e.to, goal);
            }
            // Backward Dijkstra over the jumps.
            for (int round = 0; round < n; round++) {
                int pick = -1;
                for (int i = 0; i < n; i++) {
                    if (!done[i] && (pick < 0 || bound[i] < bound[pick])) {
                        pick = i;
                    }
                }
                done[pick] = true;
                for (int i = 0; i < n; i++) {
                    bound[i] = done[i] ? bound[i]
                        : min(bound[i], cost[i] + scale * folded(to[i], from[pick]) + bound[pick]);
                }
            }
            // Each origin once, in the order first met, with its least bound.
            var byOrigin = new LinkedHashMap<Integer, Integer>();
            for (int i = 0; i < n; i++) {
                byOrigin.merge(from[i], (int) min(Integer.MAX_VALUE, bound[i]), Math::min);
            }
            return new int[][]{byOrigin.keySet().stream().mapToInt(Integer::intValue).toArray(),
                byOrigin.values().stream().mapToInt(Integer::intValue).toArray()};
        }

        int h(int node) {
            int direct = scale * folded(node, goal);
            if (origins.length == 0) {
                return direct;
            }
            int bx = x(node) / BLOCK, by = fy(node) / BLOCK, block = (bx >> 4) << 7 | by >> 4;
            int cell = (bx & 15) << 4 | by & 15;
            var area = blocks[block];
            if (area == null) {
                area = new int[256];
                Arrays.fill(area, -1);
                blocks[block] = area;
            }
            int cached = area[cell];
            if (cached < 0) {
                int cx = bx * BLOCK + BLOCK / 2, cy = by * BLOCK + BLOCK / 2, min = Integer.MAX_VALUE;
                for (int i = 0; i < origins.length; i++) {
                    int d = max(abs(x(origins[i]) - cx), abs(fy(origins[i]) - cy));
                    min = min(min, scale * max(0, d - BLOCK / 2) + bounds[i]);
                }
                cached = min;
                area[cell] = cached;
            }
            return min(direct, cached);
        }
    }
}

package com.hdmapreforged;

import java.util.*;
import java.util.function.*;

/**
 * The spirit trees one plants (Port Sarim, Etceteria, Brimhaven, Hosidius, the Farming Guild) that stand grown for this
 * account. The game says so only near the patch: its farming varbit, read where RuneLite's Time Tracking reads it
 * (FarmingWorld: the patch's regions and varbit), is 20 for a grown tree one travels by ("Spirit Tree[Travel,...]",
 * PatchImplementation.SPIRIT_TREE); any other value (growing, diseased, dead, to check, weeds) is none. Kept per account
 * (RS profile key {@link #KEY}); a patch not visited since is not known, so not used.
 */
final class Planted {
    static final String KEY = "plantedSpiritTrees";
    /** The patch state of a grown spirit tree one can travel by. */
    static final int GROWN = 20;
    /** As the travel table's stops are named: the patch's varbit, then its regions (list "spirit tree patches"). */
    static final RouteFiles.Table<Map<String, int[]>> PATCHES = new RouteFiles.Table<>(() -> Pathfinder.pairs(
        "spirit tree patches", Pathfinder::ints));

    volatile Set<String> grown = Collections.emptySet();

    /** A stop of the travel table that needs a tree planted ("Only after planting a spirit tree here"). */
    static boolean planted(Poi stop) {
        return stop.type == PoiType.SPIRIT_TREE && stop.note != null && stop.note.startsWith("Only after planting");
    }

    Set<String> grown() {
        return grown;
    }

    void load(String saved) {
        grown = saved == null || saved.isBlank() ? Collections.emptySet()
            : Collections.unmodifiableSet(new TreeSet<>(Arrays.asList(saved.split(","))));
    }

    String text() {
        return String.join(",", grown);
    }

    /** In {@code region}: reads its patch, if it has one. Whether what is known changed. Client thread. */
    boolean update(int region, IntUnaryOperator varbit) {
        for (var patch : PATCHES.get().entrySet()) {
            int[] read = patch.getValue();
            for (int i = 1; i < read.length; i++) {
                if (read[i] == region) {
                    String name = patch.getKey();
                    boolean stands = varbit.applyAsInt(read[0]) == GROWN;
                    if (stands == grown.contains(name)) {
                        return false;
                    }
                    var next = new TreeSet<>(grown);
                    if (stands) {
                        next.add(name);
                    } else {
                        next.remove(name);
                    }
                    grown = Collections.unmodifiableSet(next);
                    return true;
                }
            }
        }
        return false;
    }
}

package com.hdmapreforged;

import static java.awt.BasicStroke.*;
import static java.lang.Math.*;

import java.awt.*;
import java.awt.geom.*;

/** The local player on the map as a yellow target, or an arrow at the view's edge when out of sight. */
final class PlayerMarker {
    static final Color YELLOW = new Color(255, 214, 64), SHADOW = new Color(0, 0, 0, 170);
    static final Font FONT = new Font(Font.SANS_SERIF, Font.BOLD, 11);

    /** {@code otherFloor}: drawn fainter and dashed; {@code home}: in a box saying so, where the house stands. */
    static void paint(Graphics2D g, TextSprites text, double x, double y, double zoom, boolean otherFloor, boolean home) {
        double ring = 12 + max(0, min(3, zoom)) * 1.5;
        if (home) {
            box(g, x, y, ring, YELLOW);
            label(g, text, "Home", x, y - ring - 16);
        }
        var dash = otherFloor ? new float[]{4f, 3f} : null;
        // A glow, so it reads on bright and dark areas alike.
        g.setColor(new Color(255, 214, 64, otherFloor ? 30 : 60));
        g.fill(circle(x, y, ring + 5));
        for (int pass = 0; pass < 2; pass++) {
            g.setColor(pass == 0 ? SHADOW : YELLOW);
            g.setStroke(new BasicStroke(pass == 0 ? 5f : 2.6f, CAP_BUTT, JOIN_ROUND, 10f, dash, 0f));
            g.draw(circle(x, y, ring));
        }
        double in = ring - 5, out = ring + 5;
        for (int pass = 0; pass < 2; pass++) {
            g.setStroke(new BasicStroke(pass == 0 ? 2.4f : 1.4f, CAP_ROUND, JOIN_ROUND));
            g.setColor(pass == 0 ? SHADOW : YELLOW);
            for (int i = 0; i < 4; i++) {
                double a = PI / 2 * i;
                g.draw(new Line2D.Double(x + cos(a) * in, y + sin(a) * in, x + cos(a) * out,
                    y + sin(a) * out));
            }
        }
        g.setColor(otherFloor ? new Color(255, 214, 64, 150) : YELLOW);
        g.fill(circle(x, y, 5.5));
        g.setColor(Color.BLACK);
        g.setStroke(new BasicStroke(2f));
        g.draw(circle(x, y, 5.5));
        label(g, text, otherFloor ? "You (other floor)" : "You", x, y + ring + 8);
    }

    /** The box round a marker in a house, at its portal: room above for its label. */
    static void box(Graphics2D g, double x, double y, double ring, Color color) {
        var box = new RoundRectangle2D.Double(x - ring - 12, y - ring - 26, ring * 2 + 24, ring * 2 + 44, 10, 10);
        g.setColor(SHADOW);
        g.fill(box);
        g.setColor(color);
        g.setStroke(new BasicStroke(1.5f));
        g.draw(box);
    }

    /** Radius {@code r} round {@code (x, y)}; the party's markers and the route's ends draw with it too. */
    static Ellipse2D circle(double x, double y, double r) {
        return new Ellipse2D.Double(x - r, y - r, r * 2, r * 2);
    }

    /**
     * An arrow at {@code (x, y)} pointing at {@code angle} (radians, screen coordinates), {@code scale} times its size;
     * {@code label} may be null.
     */
    static void pointer(Graphics2D g, TextSprites text, double x, double y, double angle, double scale, Color color,
        String label) {
        var arrow = new Path2D.Double();
        arrow.moveTo(12, 0);
        arrow.lineTo(-8, -9);
        arrow.lineTo(-4, 0);
        arrow.lineTo(-8, 9);
        arrow.closePath();
        var at = AffineTransform.getTranslateInstance(x, y);
        at.rotate(angle);
        at.scale(scale, scale);
        Shape shape = at.createTransformedShape(arrow);
        g.setColor(SHADOW);
        g.setStroke(new BasicStroke(4f, CAP_ROUND, JOIN_ROUND));
        g.draw(shape);
        g.setColor(color);
        g.fill(shape);
        g.setColor(Color.BLACK);
        g.setStroke(new BasicStroke(1.2f));
        g.draw(shape);
        if (label != null) {
            label(g, text, label, x - cos(angle) * 22, y - sin(angle) * 22 + 4);
        }
    }

    static void label(Graphics2D g, TextSprites text, String label, double cx, double top) {
        g.setFont(FONT);
        var metrics = g.getFontMetrics();
        text.draw(g, label, FONT, (float) (cx - metrics.stringWidth(label) / 2.0), (float) (top + metrics.getAscent() / 2.0),
            YELLOW);
    }
}

package com.hdmapreforged;

import java.util.*;
import lombok.*;

/** What a route may use, taken on the client thread and read elsewhere. Immutable. */
@AllArgsConstructor(access = AccessLevel.PRIVATE)
final class PlayerState {
    static final PlayerState UNKNOWN = new PlayerState(ItemSnapshot.NONE, 1, false, new int[0], true, false, -1,
        false, Set.of(), true);

    @With
    final ItemSnapshot items;
    @With
    final int sailingLevel;
    /** Pandemonium done: the player can sail their own boat. */
    @With
    final boolean sailing;
    final int[] boats;
    /** Per boat of {@link #boats}: its teleport focus, 0 none, 1 (Summon Boat), 2 greater (also Teleport to Boat). */
    @With
    final int[] boatFocus;
    final boolean running;
    @With
    final boolean inHouse;
    /** In a house: where its portal leads out; outside: one's own house portal. -1 when not known. */
    final int houseExit;
    @With
    final boolean ownHouse;
    final Set<String> houseFeatures;
    /** House teleports land inside (the house option Teleport Inside, as it is at first); else at the house portal. */
    final boolean landsInside;
    /**
     * In an area whose way out leads back to where one came from (ReturnAreas: the Rune essence mine): where that is;
     * else -1.
     */
    @With
    final int returnExit;
    /** With the bank's items too ({@link #withBank}): what is carried without them; else null. */
    @With
    final ItemSnapshot carried;

    PlayerState(ItemSnapshot items, int sailingLevel, boolean sailing, int[] boats, boolean running, boolean inHouse,
        int houseExit, boolean ownHouse, Set<String> houseFeatures, boolean landsInside) {
        this(items, sailingLevel, sailing, boats.clone(), new int[boats.length], running, inHouse, houseExit, ownHouse,
            Collections.unmodifiableSet(new LinkedHashSet<>(houseFeatures)), landsInside, -1, null);
    }

    /** The same, with other items or Sailing. */
    PlayerState with(ItemSnapshot items, int sailingLevel, boolean sailing) {
        return withItems(items).withSailingLevel(sailingLevel).withSailing(sailing);
    }

    /** The same with the bank's items too, keeping what is carried apart (to say what to take out). */
    PlayerState withBank(Map<Integer, Long> bank) {
        return withItems(items.plus(bank)).withCarried(items);
    }

    /**
     * The same in one's own house ({@code inside}: a route starting on its plan), or out of any house (a route's later
     * part, on from a bank, starts outside).
     */
    PlayerState inOwnHouse(boolean inside) {
        return withInHouse(inside).withOwnHouse(inside);
    }
}

package com.hdmapreforged;

import lombok.*;
import java.util.*;
import net.runelite.api.coords.*;

/** An icon on the map. */
@RequiredArgsConstructor
final class Poi {
    @RequiredArgsConstructor
    static final class Link {
        final String label;
        final WorldPoint point;
        /** Null when no map draws it. */
        final BaseMap map;
        final Needs needs;
    }

    final PoiType type;
    final String name;
    final WorldPoint location;
    final BaseMap map;
    /** Highlighted together (such as all Ardougne cloak teleports); may be null. */
    final String group;
    final Needs needs;
    final String wikiQuery;
    /** Where an entrance or passage leads, or null. */
    final BaseMap target;
    final String note;
    final List<Link> links = new ArrayList<>();
    /**
     * Where the map draws it when not at {@link #location}: a teleport or transport on an upper floor of a building on
     * the surface is drawn on the ground floor (where its map icon stands), so it is seen on the map; routes go to its
     * location. Null: drawn at its location.
     */
    WorldPoint drawnAt;

    /** The game's picture the map draws it with: an item's id, a sprite's as {@code ~id}; 0 none (its type's icon). */
    int picture;

    /** What the Icons panel shows and hides it by: a teleport's group ("Amulet of glory"), else its type's name. */
    String toggle() {
        return type == PoiType.TELEPORT && group != null ? group : type.displayName;
    }

    /** Where the map draws it. */
    WorldPoint drawn() {
        return drawnAt != null ? drawnAt : location;
    }

    /** Teleports stacked on this icon; empty for a single one. */
    final List<Poi> members = new ArrayList<>();
    /** Other things at the same place this icon stands for. */
    final List<Poi> nearby = new ArrayList<>();

    List<Link> links() {
        return Collections.unmodifiableList(links);
    }

    List<Poi> members() {
        return members.isEmpty() ? Collections.singletonList(this) : Collections.unmodifiableList(members);
    }

    List<Poi> nearby() {
        return Collections.unmodifiableList(nearby);
    }

    /** Icons with the things they stand for. */
    static List<Poi> flatten(List<Poi> pois) {
        var all = new ArrayList<Poi>(pois.size() + 16);
        for (var poi : pois) {
            all.add(poi);
            all.addAll(poi.nearby);
        }
        return all;
    }

    /** A spot of the game on the water (a Barracuda Trial's start, salvage): sailed to, not walked to its shore. */
    boolean atSea() {
        return type == PoiType.SALVAGE || name.startsWith("Barracuda Trial");
    }

    boolean hasGroup(String group) {
        return memberOf(group) != null;
    }

    Poi memberOf(String group) {
        if (group == null) {
            return null;
        }
        for (var member : members()) {
            if (group.equals(member.group)) {
                return member;
            }
        }
        for (var other : nearby) {
            var member = other.memberOf(group);
            if (member != null) {
                return member;
            }
        }
        return null;
    }

    boolean isOn(BaseMap view) {
        return view != null && map != null && (view.id == BaseMap.FULL || map == view);
    }

    public String toString() {
        return name;
    }
}

package com.hdmapreforged;

import static com.hdmapreforged.IconLayer.*;
import static java.awt.BasicStroke.*;
import static java.awt.image.BufferedImage.*;
import static java.awt.geom.AffineTransform.*;
import static java.awt.RenderingHints.*;
import static java.lang.Math.*;

import java.awt.*;
import java.awt.geom.*;
import java.awt.image.*;
import java.io.*;
import java.util.*;
import java.util.List;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.*;
import javax.imageio.ImageIO;

/** Vector map icons, so they stay sharp at every zoom level and interface scale. */
final class PoiIcons {
    static final Color OUTLINE = new Color(20, 18, 16), GLYPH = new Color(255, 255, 255, 240);

    /** Rendered badges by type, size and screen scale. */
    static final Map<Long, BufferedImage> SPRITES = new ConcurrentHashMap<>();
    /** The pixels they hold together: zooming makes a size per quarter pixel, and 4000 large ones were tens of MB. */
    static final AtomicLong SPRITE_PIXELS = new AtomicLong();

    /**
     * {@link #paint} from a cached image: painting hundreds of badges shape by shape was most of a frame's cost.
     * {@code picture}: the game's ({@link Poi#picture}), a spell's sprite or an item's (our own pixel art of it, or in a
     * frame), drawn instead once it is had.
     * {@code emphasis}: 0 none, 1 the selected's ring, 2 the hovered's or a group member's.
     */
    static void paintCached(Graphics2D g, PoiType type, int picture, double cx, double cy, double size, int emphasis,
        boolean locked) {
        var transform = g.getTransform();
        double device = device(transform);
        // Quarter pixels of badge size, so zooming changes the image in small steps.
        int quarter = (int) round(size * 4);
        var sprite = picture(picture);
        long key = (long) (sprite == null ? 0 : (picture < 0 ? ~picture | 0x20000 : picture) & 0x3ffff) << 46
            | (long) type.ordinal() << 40
            | (locked ? 1L << 39 : 0) | (long) quarter << 16 | round(device * 10) << 2 | emphasis;
        double drawnSize = quarter / 4.0;
        // Room around the badge for the emphasis ring.
        double extent = drawnSize + (ceil(drawnSize * 0.35) + 2) * 2;
        BufferedImage cached = SPRITES.get(key);
        if (cached == null) {
            // At most 4000 sprites and 4 million pixels.
            if (SPRITES.size() > 4000 || SPRITE_PIXELS.get() > 4_000_000) {
                SPRITES.clear();
                SPRITE_PIXELS.set(0);
            }
            cached = sprite(extent, extent, device, sg -> {
                if (sprite != null && (picture < 0 || sprite.getWidth() == ICON_PIXELS)) {
                    // A game sprite, or our own picture of an item: pixel art of a game icon's size.
                    paintGameIcon(sg, sprite, extent / 2, extent / 2, drawnSize, RINGS[emphasis]);
                } else if (sprite != null) {
                    paintPicture(sg, sprite, extent / 2, extent / 2, drawnSize, RINGS[emphasis]);
                } else {
                    paint(sg, type, extent / 2, extent / 2, drawnSize, RINGS[emphasis], locked);
                }
            });
            SPRITES.put(key, cached);
            SPRITE_PIXELS.addAndGet((long) cached.getWidth() * cached.getHeight());
        }
        blit(g, transform, cached, cx - extent / 2, cy - extent / 2);
    }

    /** The game's pictures by {@link Poi#picture} for the Icons panel, as the game has them; {@link #NONE} while asked for. */
    static final Map<Integer, BufferedImage> PICTURES = new ConcurrentHashMap<>();
    static final BufferedImage NONE = new BufferedImage(1, 1, TYPE_INT_ARGB);
    /** Asks the game for a picture (an item's, or a sprite's as ~id), calling back with it on any thread. */
    static BiConsumer<Integer, Consumer<BufferedImage>> load = (id, done) -> { };
    /** Each picture had, so the maps are drawn again. */
    static Runnable loaded = () -> { };

    /** Null while not had (asked for once): our own pixel art of it from {@code pictures/} if we have one, else the game's. */
    static BufferedImage picture(int id) {
        if (id == 0) {
            return null;
        }
        if (PICTURES.putIfAbsent(id, NONE) == null) {
            var own = PoiIcons.class.getResourceAsStream("pictures/" + id + ".png");
            if (own != null) {
                try (own) {
                    PICTURES.put(id, ImageIO.read(own));
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
                return PICTURES.get(id);
            }
            load.accept(id, image -> {
                if (image == null) {
                    return;
                }
                PICTURES.put(id, image);
                loaded.run();
            });
        }
        var had = PICTURES.get(id);
        return had == NONE ? null : had;
    }

    /** Draws a screen-resolution sprite on whole screen pixels: at fractions Java2D resamples it each draw (slow). */
    static void blit(Graphics2D g, BufferedImage sprite, double x, double y) {
        blit(g, g.getTransform(), sprite, x, y);
    }

    /** {@code transform}: the graphics' own. */
    static void blit(Graphics2D g, AffineTransform transform, BufferedImage sprite, double x, double y) {
        double tx = transform.getTranslateX(), ty = transform.getTranslateY();
        if (transform.getType() <= TYPE_TRANSLATION && tx == rint(tx) && ty == rint(ty)) {
            // Screen scale 1 on whole pixels: drawn in place, without swapping the transform (costly).
            g.drawImage(sprite, (int) round(x), (int) round(y), null);
            return;
        }
        if ((transform.getType() & (TYPE_GENERAL_ROTATION | TYPE_QUADRANT_ROTATION
            | TYPE_GENERAL_TRANSFORM | TYPE_FLIP)) != 0) {
            double device = device(transform);
            var place = new AffineTransform(transform);
            place.translate(x, y);
            place.scale(1 / device, 1 / device);
            g.drawImage(sprite, place, null);
            return;
        }
        long sx = round(transform.getScaleX() * x + tx), sy = round(transform.getScaleY() * y + ty);
        g.setTransform(getTranslateInstance(sx, sy));
        g.drawImage(sprite, 0, 0, null);
        g.setTransform(transform);
    }

    /** A white dot with a coloured rim, marking where a line ends; from a cached image. */
    static void paintDot(Graphics2D g, double cx, double cy, Color rim) {
        double device = device(g.getTransform());
        long key = (1L << 62) | ((long) (rim.getRGB() & 0xffffffffL) << 8) | (int) round(device * 10);
        double extent = 13;
        blit(g, SPRITES.computeIfAbsent(key, k -> sprite(extent, extent, device, sg -> {
            var dot = new Ellipse2D.Double(extent / 2 - 4.5, extent / 2 - 4.5, 9, 9);
            sg.setColor(Color.WHITE);
            sg.fill(dot);
            sg.setColor(rim);
            sg.setStroke(new BasicStroke(2f));
            sg.draw(dot);
        })), cx - extent / 2, cy - extent / 2);
    }

    /**
     * A game sprite with the game's sign for what one cannot use yet, in its own pixels as the game draws it: red on the
     * pixels just inside its outline, all round, and a band three pixels wide from top right to bottom left. Once per
     * sprite.
     */
    static BufferedImage locked(BufferedImage icon) {
        return LOCKED_SPRITES.computeIfAbsent(icon, k -> {
            int w = icon.getWidth(), h = icon.getHeight();
            var out = new BufferedImage(w, h, TYPE_INT_ARGB);
            for (int y = 0; y < h; y++) {
                for (int x = 0; x < w; x++) {
                    int rgb = icon.getRGB(x, y);
                    boolean red = drawn(icon, x, y) && !edge(icon, x, y) && (abs(x + y - (w + h - 2) / 2.0) <= 1
                        || edge(icon, x + 1, y) || edge(icon, x - 1, y) || edge(icon, x, y + 1) || edge(icon, x, y - 1));
                    out.setRGB(x, y, red ? LOCKED.getRGB() : rgb);
                }
            }
            return out;
        });
    }

    /** Whether the pixel is on the sprite's outline: drawn, beside one that is not. */
    static boolean edge(BufferedImage icon, int x, int y) {
        return drawn(icon, x, y)
            && !(drawn(icon, x + 1, y) && drawn(icon, x - 1, y) && drawn(icon, x, y + 1) && drawn(icon, x, y - 1));
    }

    static boolean drawn(BufferedImage icon, int x, int y) {
        return x >= 0 && y >= 0 && x < icon.getWidth() && y < icon.getHeight() && icon.getRGB(x, y) >>> 24 != 0;
    }

    static final Map<BufferedImage, BufferedImage> LOCKED_SPRITES = Collections.synchronizedMap(new WeakHashMap<>());
    static final Color LOCKED = new Color(230, 20, 20);

    /** Screen pixels per unit, clamped to a sane range; shared with {@link TextSprites}. */
    static double device(AffineTransform transform) {
        return max(1, min(4, abs(transform.getScaleX())));
    }

    /** A picture of {@code width} by {@code height} units, {@code device} pixels a unit (rounded up), drawn antialiased. */
    static BufferedImage sprite(double width, double height, double device, Consumer<Graphics2D> draw) {
        BufferedImage sprite = new BufferedImage((int) ceil(width * device), (int) ceil(height * device),
            TYPE_INT_ARGB);
        var sg = sprite.createGraphics();
        sg.setRenderingHint(KEY_ANTIALIASING, VALUE_ANTIALIAS_ON);
        sg.scale(device, device);
        draw.accept(sg);
        sg.dispose();
        return sprite;
    }

    static void clearCache() {
        SPRITES.clear();
        PICTURES.clear();
        // Keyed by the icons cleared here, which would stay reachable through their rings.
        OUTLINES.clear();
    }

    /** The game's own map icon for the type if it has one, else our badge for it, pixel art of the same size. */
    static void paint(Graphics2D g, PoiType type, double cx, double cy, double size, Color ring, boolean locked) {
        BufferedImage game = GameIcons.get(type), icon = game != null ? game : badge(type);
        paintGameIcon(g, locked ? locked(icon) : icon, cx, cy, size, ring);
    }

    static final Map<PoiType, BufferedImage> BADGES = new ConcurrentHashMap<>();

    /** A type without a game icon, as pixel art of a game icon's size: a disc in its colour, outlined, its glyph within. */
    static BufferedImage badge(PoiType type) {
        return BADGES.computeIfAbsent(type, t -> {
            int size = (int) ICON_PIXELS;
            var badge = new BufferedImage(size, size, TYPE_INT_ARGB);
            var g = badge.createGraphics();
            g.drawImage(disc(size, t.color, OUTLINE), 0, 0, null);
            g.setRenderingHint(KEY_ANTIALIASING, VALUE_ANTIALIAS_ON);
            g.setRenderingHint(KEY_STROKE_CONTROL, VALUE_STROKE_PURE);
            g.setColor(GLYPH);
            g.setStroke(new BasicStroke(1.2f, CAP_ROUND, JOIN_ROUND));
            draw(g, glyph(t.name(), PoiType.t("t11")), size / 2.0, size / 2.0, size / 2.0 * 0.62);
            g.dispose();
            return badge;
        });
    }

    /** {@code ring}: the colour of a pixel ring round the icon, or null. */
    static void paintGameIcon(Graphics2D g, BufferedImage icon, double cx, double cy, double size, Color ring) {
        // Always the size of a game icon: a game icon's 15 pixels in whole steps, a spell's sprite (more pixels) also
        // smoothly in between.
        double scale = size / max(icon.getWidth(), icon.getHeight());
        if (ring != null) {
            pixels(g, outline(icon, ring, scale), cx, cy, scale);
        }
        pixels(g, icon, cx, cy, scale);
    }

    /**
     * An item's picture in a game icon's round frame: the frame and ring as pixel art of a game icon's size, the picture
     * in its own pixels enlarged by whole steps as far as the frame has room (smaller, smoothed).
     */
    static void paintPicture(Graphics2D g, BufferedImage image, double cx, double cy, double size, Color ring) {
        int base = (int) ICON_PIXELS;
        double fit = size / base, scale = fit >= 1 ? max(1, round(fit)) : fit;
        if (ring != null) {
            pixels(g, outline(frame(), ring, scale), cx, cy, scale);
        }
        pixels(g, frame(), cx, cy, scale);
        pixels(g, image, cx, cy, (base - 2) * scale / max(image.getWidth(), image.getHeight()));
    }

    static final Color FRAME = new Color(0xbfbfbf);
    static final Map<BufferedImage, BufferedImage> FRAMES = Collections.synchronizedMap(new WeakHashMap<>());

    /** The game's round frame as its own icons have it (a bank's, painted grey within); our disc while none is loaded. */
    static BufferedImage frame() {
        BufferedImage model = GameIcons.get(PoiType.BANK);
        model = model != null ? model : GameIcons.get(PoiType.ANVIL);
        if (model == null) {
            return disc((int) ICON_PIXELS, FRAME, Color.BLACK);
        }
        return FRAMES.computeIfAbsent(model, m -> {
            var frame = new BufferedImage(m.getWidth(), m.getHeight(), TYPE_INT_ARGB);
            for (int y = 0; y < m.getHeight(); y++) {
                for (int x = 0; x < m.getWidth(); x++) {
                    frame.setRGB(x, y, !drawn(m, x, y) ? 0 : edge(m, x, y) ? m.getRGB(x, y) : FRAME.getRGB());
                }
            }
            return frame;
        });
    }

    /** The rings of {@link #paintCached}'s emphasis: none, the selected's yellow, the hovered's white. */
    static final Color[] RINGS = {null, PlayerMarker.YELLOW, new Color(255, 255, 255, 210)};
    static final Color RING_EDGE = new Color(0, 0, 0, 150);
    static final Map<List<Object>, BufferedImage> OUTLINES = Collections.synchronizedMap(new HashMap<>());

    /**
     * A ring in {@code color} following an icon's outline two pixels out (round for a round icon, a triangle for a
     * tablet's), a dark pixel on either side, in the icon's own pixels and centred as it: drawn at the icon's
     * {@code scale}, and two pixels wide below scale 2, where one would be hard to see.
     */
    static BufferedImage outline(BufferedImage icon, Color color, double scale) {
        int width = scale < 2 ? 2 : 1;
        return OUTLINES.computeIfAbsent(List.of(icon, color.getRGB(), width), k -> {
            int pad = 3 + width;
            var ring = new BufferedImage(icon.getWidth() + 2 * pad, icon.getHeight() + 2 * pad, TYPE_INT_ARGB);
            for (int y = 0; y < ring.getHeight(); y++) {
                for (int x = 0; x < ring.getWidth(); x++) {
                    double d = pad + 1;
                    for (int iy = max(0, y - pad - pad); iy < min(icon.getHeight(), y + 1); iy++) {
                        for (int ix = max(0, x - pad - pad); ix < min(icon.getWidth(), x + 1); ix++) {
                            d = drawn(icon, ix, iy) ? min(d, hypot(x - pad - ix, y - pad - iy)) : d;
                        }
                    }
                    ring.setRGB(x, y, d > 2 && d <= 2 + width ? color.getRGB() : d > 1 && d <= 3 + width ? RING_EDGE.getRGB() : 0);
                }
            }
            return ring;
        });
    }

    /** Pixel art centred on (cx, cy), {@code scale} times its size: enlarged crisp, in whole pixels; smaller, smoothed. */
    static void pixels(Graphics2D g, BufferedImage image, double cx, double cy, double scale) {
        double w = image.getWidth() * scale, h = image.getHeight() * scale;
        var copy = (Graphics2D) g.create();
        copy.setRenderingHint(KEY_INTERPOLATION, scale >= 1
            ? VALUE_INTERPOLATION_NEAREST_NEIGHBOR : VALUE_INTERPOLATION_BILINEAR);
        copy.drawImage(image, new AffineTransform(scale, 0, 0, scale, round(cx - w / 2), round(cy - h / 2)), null);
        copy.dispose();
    }

    static final Map<List<Object>, BufferedImage> DISCS = new ConcurrentHashMap<>();

    /**
     * A pixel-art disc {@code size} pixels across, as the game draws its icons' frames: {@code edge} on its outermost
     * ring of pixels, {@code fill} within (null: a ring alone). Made once per size and colours.
     */
    static BufferedImage disc(int size, Color fill, Color edge) {
        return DISCS.computeIfAbsent(List.of(size, fill == null ? 0 : fill.getRGB(), edge.getRGB()), k -> {
            var disc = new BufferedImage(size, size, TYPE_INT_ARGB);
            double c = (size - 1) / 2.0, r = size / 2.0;
            for (int x = 0; x < size; x++) {
                for (int y = 0; y < size; y++) {
                    double d = hypot(x - c, y - c);
                    if (d > r - 1 && d <= r) {
                        disc.setRGB(x, y, edge.getRGB());
                    } else if (d <= r - 1 && fill != null) {
                        disc.setRGB(x, y, fill.getRGB());
                    }
                }
            }
            return disc;
        });
    }

    /** Draws a glyph from {@code poi_glyphs.txt} in units of {@code s} around {@code (x, y)}; the file lists the ops. */
    static void draw(Graphics2D g, String ops, double x0, double y0, double s0) {
        // The origin and unit; U moves them until the path is painted.
        double x = x0, y = y0, s = s0;
        Path2D pen = new Path2D.Double();
        for (String op : ops.split(";")) {
            var t = op.trim().split(" ");
            var a = new double[8];
            for (int i = 1; i < t.length; i++) {
                a[i] = Double.parseDouble(t[i]);
            }
            double px = x + s * a[1], py = y + s * a[2], w = s * a[3], h = s * a[4];
            boolean fill = Character.isUpperCase(t[0].charAt(0));
            switch (t[0]) {
                case "g":
                    pen = new GeneralPath();
                    break;
                case "m":
                    pen.moveTo(px, py);
                    break;
                case "l":
                    pen.lineTo(px, py);
                    break;
                case "q":
                    pen.quadTo(px, py, x + w, y + h);
                    break;
                case "b":
                    pen.curveTo(px, py, x + w, y + h, x + s * a[5], y + s * a[6]);
                    break;
                case "z":
                    pen.closePath();
                    break;
                case "P":
                case "p":
                    shape(g, pen, fill);
                    pen = new Path2D.Double();
                    x = x0;
                    y = y0;
                    s = s0;
                    break;
                case "U":
                    x = px;
                    y = py;
                    s = w;
                    break;
                case "R":
                case "r":
                    shape(g, new Rectangle2D.Double(px, py, w, h), fill);
                    break;
                case "O":
                case "o":
                    shape(g, new Ellipse2D.Double(px, py, w, h), fill);
                    break;
                case "L":
                    g.draw(new Line2D.Double(px, py, x + w, y + h));
                    break;
                case "A":
                case "a":
                    shape(g, new Arc2D.Double(px, py, w, h, a[5], a[6], (int) a[7]), fill);
                    break;
                case "W":
                case "w":
                    shape(g, new RoundRectangle2D.Double(px, py, w, h, s * a[5], s * a[5]), fill);
                    break;
                case "c":
                    g.fill(PlayerMarker.circle(px, py, w));
                    break;
                case "C":
                    g.setColor(OUTLINE);
                    break;
                case "K":
                    g.setColor(new Color((int) a[1], (int) a[2], (int) a[3]));
                    break;
                case "s":
                    g.setStroke(a[2] == 1 ? new BasicStroke((float) a[1], CAP_ROUND, JOIN_ROUND, 1,
                        a[3] > 0 ? new float[]{(float) a[3], (float) a[4]} : null, 0) : new BasicStroke((float) a[1]));
                    break;
                default:
                    throw new IllegalArgumentException(op);
            }
        }
    }

    /** Upper-case ops fill, lower-case ones outline. */
    static void shape(Graphics2D g, Shape shape, boolean fill) {
        if (fill) {
            g.fill(shape);
        } else {
            g.draw(shape);
        }
    }

    static final Map<String, String[]> GLYPHS = PoiType.rows("poi_glyphs.txt");

    /** A glyph's ops, or {@code otherwise}: a blank line or one without its tab is no glyph. */
    static String glyph(String name, String otherwise) {
        var cells = GLYPHS.get(name);
        return cells == null || cells.length < 2 ? otherwise : cells[1];
    }

    /** A small image of an icon, for buttons and lists. */
    static BufferedImage image(PoiType type, int size) {
        return sprite(size + 2, size + 2, 1, g -> {
            g.setRenderingHint(KEY_STROKE_CONTROL, VALUE_STROKE_PURE);
            paint(g, type, (size + 2) / 2.0 - 0.5, (size + 2) / 2.0 - 1, size - 1, null, false);
        });
    }

    static BufferedImage icon(int size, String name) {
        return sprite(size, size, 1, g -> glyph(g, name, 0, 0));
    }

    /** A glyph of the file's in pixels round (x, y). */
    static void glyph(Graphics2D g, String name, double x, double y) {
        draw(g, glyph(name, null), x, y, 1);
    }
}

package com.hdmapreforged;

import java.awt.*;
import java.io.*;
import java.nio.charset.*;
import java.util.*;

enum PoiType {
    TELEPORT, FAIRY_RING, SPIRIT_TREE, GNOME_GLIDER, BALLOON, QUETZAL, MUSHTREE, OBELISK, BOAT, CHARTER, CANOE, CARPET,
    MINECART, PORTAL, LEVER, GUIDE, TRANSPORT, DUNGEON_ENTRANCE, MAP_EXIT, MOORING, SALVAGE, RUNECRAFT_ALTAR, AGILITY_COURSE,
    AGILITY_SHORTCUT, FARMING_PATCH, MINIGAME, BANK, ALTAR, ANVIL,
    // The game's own icons: drawn by IconLayer from the game's sprites, not as our badges.
    SHOP, QUEST_START, MAP_LINK, GAME_ICON,
    /** A search result without an icon of its own: only selected, never drawn. */
    FOUND,
    /** One's grave while it stands: drawn by {@link GraveMarker}. */
    GRAVE;

    final String displayName;
    final Layer layer;
    final Color color;
    /** The game map element whose icon stands for this type (GameIcons); -1 none. */
    final int element;
    /** For routes: a trip's half ticks, its kind of jump, and the setting weighing it (RouteSource.Saving). */
    final int cost;
    final Edge.Kind kind;
    final int saving;

    PoiType() {
        String[] cells = Rows.BY_TYPE.get(name());
        displayName = cells[1];
        layer = Layer.valueOf(cells[2]);
        color = new Color(Integer.parseInt(cells[3], 16));
        element = cells[4].isEmpty() ? -1 : Integer.parseInt(cells[4]);
        cost = Integer.parseInt(cells[5]);
        kind = Edge.Kind.valueOf(cells[6]);
        saving = Integer.parseInt(cells[7]);
    }

    /** A game map icon's key with no type: the name the Icons panel shows it by (empty: its own) and its group; or null. */
    static String[] key(String name) {
        return Rows.BY_TYPE.get(name);
    }

    /** The types' names, layers, colours and game icons, bundled (data/poi_types.tsv), then the keys'. */
    private static final class Rows {
        static final Map<String, String[]> BY_TYPE = rows("data/poi_types.tsv");
        static final Map<String, String[]> TEXTS = rows("data/texts.tsv");
    }

    /** A longer text of the plugin's by its key, with {@code args} in place of its %s (data/texts.tsv, kept out of the code the review bot counts). */
    static String t(String key, Object... args) {
        return String.format(Rows.TEXTS.get(key)[1], args);
    }

    /** A bundled table's rows by their first cell. */
    static Map<String, String[]> rows(String file) {
        var rows = new HashMap<String, String[]>();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(
            PoiType.class.getResourceAsStream(file), StandardCharsets.UTF_8))) {
            reader.lines().filter(line -> !line.startsWith("#")).map(line -> line.split("\t"))
                .forEach(cells -> rows.put(cells[0], cells));
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        return rows;
    }

    /** Obelisks send you to a random other obelisk unless you can choose. */
    boolean isRandomDestination() {
        return this == OBELISK;
    }

    /** Fairy rings to obelisks, in the order above; every stop of one reaches every other. */
    static final Set<PoiType> NETWORKS = EnumSet.range(FAIRY_RING, OBELISK);
}

package com.hdmapreforged;

import java.util.*;

/** Where a boat lies at each Sailing port (ports.tsv, from the game cache), keyed by SAILING_BOAT_n_PORT values. */
final class Ports {
    static final String RESOURCE = RouteFiles.DIR + "ports.tsv";

    /** Port id → packed tile of the boat; none without the table. */
    static Map<Integer, Integer> load() {
        var ports = new HashMap<Integer, Integer>();
        for (var c : Pathfinder.rows(RESOURCE)) {
            try {
                // Short rows and blank lines fail here too.
                var p = c[2].trim().split("\\s+");
                ports.put(Integer.parseInt(c[0].trim()), Tiles.pack(Integer.parseInt(p[0]), Integer.parseInt(p[1]), 0));
            } catch (NumberFormatException | ArrayIndexOutOfBoundsException e) {
                // Skip the row.
            }
        }
        return Collections.unmodifiableMap(ports);
    }
}

package com.hdmapreforged;

import net.runelite.api.coords.*;

/** Where world points appear in the frame being painted; add 0.5 to a tile for its middle. */
interface Projection {
    double screenX(double worldX);

    double screenY(double worldY);

    /** Log2 of screen pixels per game tile. */
    double zoom();

    BaseMap map();

    int plane();

    int width();

    int height();

    boolean shows(WorldPoint point);

    /** Where a game point is drawn on the map in view (the Kalphite Lair is drawn beside the desert caves). */
    default WorldPoint shown(WorldPoint point) {
        return point;
    }
}

package com.hdmapreforged;

import lombok.*;

/**
 * Where a search proved its target out of reach from: with the same ways, from any of these nodes the target stays out
 * of reach. Either all a search that tried everything reached (what it could get to from there it got to from its
 * start), or everything but the nodes the target can be reached from, when the search flooded back from the target
 * instead ({@code complement}). Immutable once made.
 */
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
final class Reached {
    final NodeSet nodes;
    final boolean complement;

    boolean contains(int node) {
        return node >= 0 && nodes.contains(node) != complement;
    }
}

package com.hdmapreforged;

import java.util.*;
import java.util.concurrent.*;

/**
 * Which maps really show a 64×64 region where map bounds overlap (empty: checked, none), and where several share a
 * region, which draws each 8×8 zone: a map version's regions.json from the map server as Gson binds it (built from its
 * tiles by the test sources' RegionResolver; regions.tsv beside it is the released plugins'). Read only once made.
 */
class RegionTable {
    static final int[] NONE = new int[0];

    static final int ZONES = 8, ZONE = 8;
    /** A zone's owners as a bit mask over the region's owner list, one character (up to 6 owners). */
    static final String MASKS = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_-";

    final Map<Integer, int[]> owners = new ConcurrentHashMap<>();
    /** 64 mask characters, zone (x, y) at index x * 8 + y. */
    final Map<Integer, String> zones = new ConcurrentHashMap<>();
    /**
     * Per region, by zone and floor ({@code (zone * 4 + floor)}): the map and floor drawing that floor's ground where the
     * zone's own map does not, packed as {@code (map id + 2) << 2 | floor}; 0 where the zone's map draws it.
     */
    final Map<Integer, int[]> floors = new ConcurrentHashMap<>();
    /**
     * By tile and floor ({@link #tileKey}): the map and floor drawing that floor's ground at that one tile where the map
     * shown there (after the zone's floor line) draws nothing, packed as the zones' ({@code (map id + 2) << 2 | floor});
     * for strips narrower than a zone (along Cam Torum's walls).
     */
    final Map<Integer, Integer> tileFloors = new ConcurrentHashMap<>();

    static int regionId(int x, int y) {
        return ((x >> 6) << 8) | (y >> 6);
    }

    /** Owner map ids, empty when none, or null when the table does not list the region. */
    int[] owners(int region) {
        return owners.get(region);
    }

    /**
     * The owners drawing a tile's zone, or when none does, the zones around it (an entrance just beside a drawing);
     * null when zones are not known; empty when none draws anything near.
     */
    int[] zoneOwners(int x, int y) {
        int region = regionId(x, y);
        String text = zones.get(region);
        var ids = owners.get(region);
        if (text == null || ids == null) {
            return null;
        }
        int zx = (x & 63) / ZONE, zy = (y & 63) / ZONE, mask = MASKS.indexOf(text.charAt(zx * ZONES + zy));
        if (mask == 0) {
            for (int dx = -1; dx <= 1; dx++) {
                for (int dy = -1; dy <= 1; dy++) {
                    int nx = zx + dx, ny = zy + dy;
                    if (nx >= 0 && ny >= 0 && nx < ZONES && ny < ZONES) {
                        mask |= MASKS.indexOf(text.charAt(nx * ZONES + ny));
                    }
                }
            }
        }
        int count = Integer.bitCount(mask & ((1 << Math.min(6, ids.length)) - 1));
        var found = new int[count];
        int n = 0;
        for (int i = 0; i < ids.length && i < 6; i++) {
            if ((mask & 1 << i) != 0) {
                found[n++] = ids[i];
            }
        }
        return found;
    }

    /**
     * Where the ground a floor walks in this spot's zone is drawn when the zone's own map does not draw it on that floor
     * (an upper floor the game draws a floor lower, as the Brimhaven Dungeon's raised paths; a floor walked under the one
     * the game's map shows, as in Cam Torum): {map id, floor drawn}; null where the zone's map draws it.
     */
    int[] floorOverride(int x, int y, int floor) {
        if (floor < 0 || floor > 3) {
            return null;
        }
        Integer tile = tileFloors.isEmpty() ? null : tileFloors.get(tileKey(x, y, floor));
        if (tile != null) {
            return new int[]{(tile >> 2) - 2, tile & 3};
        }
        var packed = floors.get(regionId(x, y));
        int v = packed == null ? 0 : packed[((x & 63) / ZONE * ZONES + (y & 63) / ZONE) * 4 + floor];
        return v == 0 ? null : new int[]{(v >> 2) - 2, v & 3};
    }

    /** A tile and floor as one number (as the route data packs them). */
    static int tileKey(int x, int y, int floor) {
        return floor << 28 | x << 14 | y;
    }
}

package com.hdmapreforged;

import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import java.util.regex.*;
import java.util.stream.*;
import lombok.*;

/** Turns requirement columns ({@link Needs}) into readable lines. */
final class Requirements {
    static final int MAX_ALTERNATIVES = 3;
    static final Pattern SPACES = Pattern.compile("\\s+");
    /** {@link #skillsAndQuests} per requirement: a route request asks for thousands, of a few hundred kinds. */
    static final Map<Needs, List<Line>> CHECKABLE = new ConcurrentHashMap<>();

    @RequiredArgsConstructor
    static final class Line {
        final String text, skill;
        final int level;
        final String quest;
    }

    /** Lines such as {@code "25 Magic"}, {@code "3 × Air rune"} and {@code "Quest: Sea Slug"}. */
    static List<Line> describe(Needs needs, IntFunction<String> itemNames) {
        var lines = new ArrayList<Line>();
        for (String skill : needs.skills.split(";")) {
            var parts = SPACES.split(skill.trim(), 2);
            if (parts.length == 2 && isNumber(parts[0])) {
                String name = parts[1].trim();
                String shown = name.equals("Quest") ? " quest points"
                    : name.contains("+") ? " " + name.replace("+", " and ") + " together" : " " + name;
                lines.add(new Line(parts[0] + shown, name, Integer.parseInt(parts[0]), null));
            } else if (!skill.trim().isEmpty()) {
                lines.add(new Line(skill.trim(), null, 0, null));
            }
        }
        items(needs.items, itemNames).forEach(item -> lines.add(new Line(item, null, 0, null)));
        for (String quest : needs.quests.split(";")) {
            if (!quest.trim().isEmpty()) {
                lines.add(new Line("Quest: " + quest.trim(), null, 0, quest.trim()));
            }
        }
        return lines;
    }

    /** The lines {@link Unlocks} can tick off: skill levels and quests. */
    static List<Line> skillsAndQuests(Needs needs) {
        var lines = CHECKABLE.get(needs);
        if (lines == null) {
            lines = Collections.unmodifiableList(describe(new Needs(needs.skills, "", needs.quests, ""), id -> null));
            if (CHECKABLE.size() < Unlocks.CACHED) {
                CHECKABLE.put(needs, lines);
            }
        }
        return lines;
    }

    /** {@code "556=3&&554=1"}: all needed; {@code "1706=1||1708=1"}: alternatives. {@code itemNames} may return null. */
    static List<String> items(String column, IntFunction<String> itemNames) {
        // A blank column has no alternatives: no lines.
        var lines = new ArrayList<String>();
        for (String all : ItemSnapshot.ALL.split(column)) {
            var alternatives = new LinkedHashSet<String>();
            int quantity = 1;
            for (String alternative : ItemSnapshot.ANY.split(all)) {
                var parts = alternative.trim().split("=");
                if (parts[0].isEmpty()) {
                    continue;
                }
                if (parts.length > 1) {
                    try {
                        quantity = Integer.parseInt(parts[1].trim());
                    } catch (NumberFormatException ignored) {
                    }
                }
                alternatives.add(itemName(parts[0].trim(), itemNames));
            }
            if (alternatives.isEmpty()) {
                continue;
            }
            var names = new ArrayList<String>(alternatives);
            String text = String.join(" or ", names.subList(0, Math.min(MAX_ALTERNATIVES, names.size())));
            if (names.size() > MAX_ALTERNATIVES) {
                text += " or others";
            }
            lines.add(quantity > 1 ? quantity + " × " + text : text);
        }
        return lines;
    }

    static String itemName(String token, IntFunction<String> itemNames) {
        String name = isNumber(token) ? itemNames.apply(Integer.parseInt(token)) : null;
        // Charged variants such as "Amulet of glory(4)" collapse into one entry.
        return name == null ? "Item " + token : name.replaceFirst("\\s*\\(\\d+\\)$", "");
    }

    static List<Integer> itemIds(String column) {
        return Arrays.stream(column.split("&&|\\|\\|")).map(token -> token.split("=")[0].trim())
            .filter(Requirements::isNumber).map(Integer::parseInt).collect(Collectors.toList());
    }

    /** Each item a column names, with the most of it any part asks for ("563=3&&556" adds 563: 3, 556: 1), into {@code most}. */
    static void itemAmounts(String column, Map<Integer, Long> most) {
        for (String token : column.split("&&|\\|\\|")) {
            String[] parts = token.split("=");
            if (isNumber(parts[0].trim())) {
                long n = parts.length > 1 && parts[1].trim().matches("\\d{1,12}") ? Long.parseLong(parts[1].trim()) : 1;
                most.merge(Integer.parseInt(parts[0].trim()), n, Math::max);
            }
        }
    }

    static boolean isNumber(String text) {
        return !text.isEmpty() && text.length() <= 9 && text.chars().allMatch(Character::isDigit);
    }
}

package com.hdmapreforged;

import java.util.*;
import lombok.*;

/**
 * Areas whose way out leads back to where one came from (return_areas.tsv): the Rune essence mine's portals return one to
 * the wizard who sent one there, the Shipyard's portal to the shipwright. Read once. Immutable.
 */
final class ReturnAreas {
    static final String RESOURCE = RouteFiles.DIR + "return_areas.tsv";

    @AllArgsConstructor(access = AccessLevel.PACKAGE)
    static final class Area {
        final String name;
        final int minX, minY, maxX, maxY, plane;
        /** The exit objects' tiles, packed. */
        final int[] exits;
        /** The step's name ("Use Portal"). */
        final String exitName;

        boolean contains(int node) {
            return node >= 0 && !Tiles.isSea(node) && Tiles.z(node) == plane && Tiles.x(node) >= minX
                && Tiles.x(node) <= maxX && Tiles.y(node) >= minY && Tiles.y(node) <= maxY;
        }
    }

    static final RouteFiles.Table<List<Area>> AREAS = new RouteFiles.Table<>(ReturnAreas::read);

    /** The area holding the tile, or null. */
    static Area at(int node) {
        return AREAS.get().stream().filter(area -> area.contains(node)).findFirst().orElse(null);
    }

    static List<Area> read() {
        return Pathfinder.table(RESOURCE, cells -> {
            var box = Pathfinder.ints(cells[1]);
            var tiles = cells[2].trim().split(";");
            int[] exits = new int[tiles.length];
            for (int i = 0; i < tiles.length; i++) {
                exits[i] = Tiles.parse(tiles[i].trim());
            }
            return new Area(cells[0].trim(), box[0], box[1], box[2], box[3], box[4], exits, cells[3].trim());
        });
    }
}

package com.hdmapreforged;

/**
 * Where the player stood before coming into an area whose way out leads back there (ReturnAreas: the Rune essence mine,
 * the Shipyard), so a route from inside knows where the exit leads. Not known when the player was inside already (logged
 * in there). Client thread only.
 */
final class ReturnTracker {
    int lastOutside = -1;
    ReturnAreas.Area inside;
    int exit = -1;

    void update(int node) {
        var area = node < 0 ? null : ReturnAreas.at(node);
        if (area != null) {
            if (inside != area) {
                // Came in (or into another such area): from where one stood just before, if one was outside then.
                exit = inside == null && lastOutside >= 0 ? lastOutside : -1;
                inside = area;
            }
            return;
        }
        inside = null;
        exit = -1;
        if (node >= 0) {
            lastOutside = node;
        }
    }

    /** Where the exit of the area the player is in leads (where they came from), or -1. */
    int exit() {
        return inside == null ? -1 : exit;
    }
}

package com.hdmapreforged;

import static com.hdmapreforged.Tiles.*;
import static lombok.AccessLevel.*;

import java.util.*;
import java.util.stream.*;
import lombok.*;

/** The result of a search: the steps, and how the target was reached (or why not). */
@AllArgsConstructor(access = PRIVATE)
final class Route {
    enum Outcome {
        FOUND,
        NEAREST,
        NONE,
        CANCELLED
    }

    @AllArgsConstructor
    static final class Obstacle {
        final int at;
        final String text;
    }

    @AllArgsConstructor
    static final class Step {
        enum Kind {
            WALK, SAIL, STAIRS, ENTRANCE, TELEPORT, TRANSPORT, SHIP, BOARD, DISEMBARK, HOUSE,
            /** Take from the bank what the steps after it need ({@link BankDetour}): both points the bank's tile. */
            BANK
        }

        final Kind kind;
        /** Packed: all tiles walked or sea blocks sailed, or the two ends of a jump. */
        final int[] points;
        @With(PACKAGE)
        final String name;
        @With(PACKAGE)
        final String detail;
        final int cost, doors;
        final List<Obstacle> obstacles;
        /** Teleport or transport kind ("Hot air balloon"), to leave out all of that kind; or null. */
        final String category;

        int first() {
            return points[0];
        }

        int last() {
            return points[points.length - 1];
        }

        boolean isJump() {
            return kind != Kind.WALK && kind != Kind.SAIL;
        }
    }

    final Outcome outcome;
    @With(PACKAGE)
    final List<Step> steps;
    /** Half ticks. */
    final int cost, target, end;
    @With(PACKAGE)
    final boolean exhausted;
    final boolean limited;
    final int nodes;
    /** Where a search that proved the target out of reach proved it out of reach from; else null. */
    @With(PACKAGE)
    final Reached reached;
    /** Through the Wilderness though the player keeps out of it: no way around it gets there. */
    @With(PACKAGE)
    final boolean viaWild;
    /** The search left out a step or jump into the Wilderness (kept out of it): through it, it may get further. */
    @With(PACKAGE)
    final boolean keptOut;

    /** Without the extra weight of teleports kept for longer trips. */
    int time() {
        return steps.stream().mapToInt(step -> step.cost).sum();
    }

    Route(Outcome outcome, List<Step> steps, int cost, int target, int end, boolean exhausted, boolean limited,
        int nodes) {
        this(outcome, steps, cost, target, end, exhausted, limited, nodes, null);
    }

    Route(Outcome outcome, List<Step> steps, int cost, int target, int end, boolean exhausted, boolean limited, int nodes,
        Reached reached) {
        this(outcome, Collections.unmodifiableList(steps), cost, target, end, exhausted, limited, nodes, reached, false,
            false);
    }

    /** This route, ending near the target of {@code shut}, which proved it out of reach. */
    Route near(Route shut) {
        return new Route(Outcome.NEAREST, steps, cost, shut.target, end, shut.exhausted, limited, nodes, shut.reached,
            viaWild, keptOut);
    }

    static final int NEAR = 12;

    /**
     * Up to its first teleport (or way of one's house): what comes after is drawn in the game once it is taken, so a
     * route out of the house and back in (to its fairy ring) does not draw both visits at once.
     */
    Route untilTeleport() {
        for (int s = 0; s < steps.size() - 1; s++) {
            var kind = steps.get(s).kind;
            if (kind == Step.Kind.TELEPORT || kind == Step.Kind.HOUSE) {
                return withSteps(steps.subList(0, s + 1));
            }
        }
        return this;
    }

    /** What is still ahead of the player, like a navigation app; the route itself when the player is not near it. */
    Route ahead(int player) {
        if (player < 0 || steps.isEmpty()) {
            return this;
        }
        int bestStep = -1, bestIndex = 0;
        long bestDistance = (long) (NEAR + 1) * (NEAR + 1);
        // Past a bank step nothing in one's house counts while one is in it: the route may go from the house to the bank
        // and back (its fairy ring), and in the house before it the bank is still to do.
        boolean banked = false, home = HousePlan.contains(player);
        for (int s = 0; s < steps.size(); s++) {
            Step step = steps.get(s);
            if (step.kind == Step.Kind.BANK) {
                // Done only once what it takes out is used: standing at the bank it is still to do.
                banked = true;
                continue;
            }
            if (step.isJump()) {
                int landing = step.last(), from = step.first();
                // Nearer where it starts (a gate, a door): not crossed yet.
                boolean before = from >= 0 && !isSea(from) && sameLevel(player, from)
                    && distance(player, from) < distance(player, landing);
                if (banked && home && HousePlan.contains(landing)) {
                    continue;
                }
                // Into one's house (a teleport, its portal): anywhere in it, it was taken, wherever the game put one.
                boolean entered = from >= 0 && !HousePlan.contains(from) && HousePlan.contains(landing) && home;
                if (sameLevel(player, landing) && (distance(player, landing) <= 2 || entered) && !before) {
                    bestStep = s + 1;
                    bestIndex = 0;
                    bestDistance = 0;
                }
                continue;
            }
            for (int i = 0; i < step.points.length; i++) {
                int point = step.points[i];
                if (!sameLevel(player, point) || banked && home && HousePlan.contains(point)) {
                    continue;
                }
                long dx = x(player) - x(point), dy = y(player) - y(point), d = dx * dx + dy * dy;
                if (isSea(point)) {
                    d /= (long) CELL * CELL;
                }
                // Ties go to the later point, so a route passing a spot twice follows the player forward.
                if (d <= bestDistance) {
                    bestStep = s;
                    bestIndex = i;
                    bestDistance = d;
                }
            }
        }
        if (bestStep < 0 || bestStep == 0 && bestIndex == 0) {
            return this;
        }
        var left = new ArrayList<Step>();
        for (int s = bestStep; s < steps.size(); s++) {
            Step step = steps.get(s);
            if (s == bestStep && bestIndex > 0) {
                var rest = Arrays.copyOfRange(step.points, bestIndex, step.points.length);
                if (rest.length < 2) {
                    continue;
                }
                var obstaclesLeft = step.obstacles.stream()
                    .filter(o -> Arrays.stream(rest).anyMatch(p -> p == o.at)).collect(Collectors.toList());
                step = new Step(step.kind, rest, step.name, step.detail, step.cost * rest.length / step.points.length,
                    step.doors, obstaclesLeft, step.category);
            }
            left.add(step);
        }
        return withSteps(Collections.unmodifiableList(left)).withReached(null);
    }

    static boolean sameLevel(int a, int b) {
        return isSea(a) || isSea(b) || z(a) == z(b);
    }

    /**
     * Whether this search proved the target out of reach from the node too (it reached the node and tried everything,
     * or flooded back from the target and never came to the node), as long as the same ways may be used.
     */
    boolean reached(int node) {
        return reached != null && reached.contains(node);
    }

    boolean snapped() {
        return end >= 0 && end != target;
    }

    boolean has(Step.Kind kind) {
        return first(kind) != null;
    }

    Step first(Step.Kind kind) {
        return steps.stream().filter(step -> step.kind == kind).findFirst().orElse(null);
    }

    public String toString() {
        StringBuilder sb = new StringBuilder(outcome + " " + (cost + 1) / 2 + " ticks, " + nodes + " nodes");
        for (Step step : steps) {
            sb.append("\n  ").append(step.kind).append(' ').append(step.name == null ? "" : step.name).append(' ')
                .append(format(step.first())).append(" -> ").append(format(step.last()));
        }
        return sb.toString();
    }
}

package com.hdmapreforged;

import static com.hdmapreforged.PoiType.t;
import static com.hdmapreforged.Route.Outcome.*;
import static com.hdmapreforged.Tiles.*;

import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.*;
import lombok.*;
import lombok.experimental.*;
import lombok.extern.slf4j.*;

/**
 * When to search, so it never happens too often: one search at a time; when the player strays, automatic searches
 * with a doubling pause, at most {@link #MAX_AUTOMATIC} in a row (again once back on the way, or walked on toward the
 * target), none where a search proved the target out of reach (until a user action, or until the ways it may use
 * change) and none in instances other than the house (their positions are template copies). Called on one thread
 * (Swing); results come back through {@code callbacks}, also when a search fails.
 */
@Slf4j
@RequiredArgsConstructor
@Accessors(fluent = true)
final class RouteController {
    static final long FIRST_BACKOFF_MS = 3_000, MAX_BACKOFF_MS = 60_000;
    static final int MAX_AUTOMATIC = 6;
    /** Tiles from the route before the player counts as having left it: 10 away, as Shortest Path. */
    static final int STRAY = 9;

    final Executor searches, callbacks;
    final Pathfinder pathfinder;
    /** Builds a search for a target, or null when there is no start. */
    final IntFunction<RouteRequest> requests;
    final Consumer<RouteController> changed;
    final LongSupplier clock;

    @Getter
    int target = -1;
    @Getter
    Route route;
    /** Where the route starts, or -1: before a first teleport the player stands there, on none of its steps. */
    int from = -1;
    /** What the route's search was asked; whether it was an automatic search asked the same ways as the one before. */
    RouteRequest asked;
    /** Whether the route came from an automatic search with the same ways as the one before: only the player moved. */
    @Getter
    boolean onlyMoved;
    AtomicBoolean running;
    /** A user search asked for while another ran; started when that one ends. */
    boolean pendingUser;
    int automatic;
    long backoff = FIRST_BACKOFF_MS, nextAutomatic;
    /** Where the player was when an automatic search was last thought of, and the tick before; -1 none. */
    int searchedAt = -1, lastPlayer = -1;
    /** The last tick's move was a jump; a jump from a steady spot (a teleport) not yet searched from. */
    boolean jumped, teleported;
    /**
     * A search that tried everything without getting there, and what it was asked: from anywhere it reached, the
     * target stays out of reach while the same ways may be used.
     */
    Route unreachable;
    RouteRequest unreachableAsked;
    /** A message instead of a route, or null. */
    @Getter
    String status;
    /** A search could not start for want of a position, and when to try again. */
    boolean noStart;
    long nextStartTry;

    void setTarget(int target) {
        userAction();
        this.target = target;
        route = null;
        status = "Searching…";
        start(true);
        changed.accept(this);
    }

    /** A route planned already (a custom route's next part, from {@code from}): shown as found, without a search. */
    void show(int target, int from, Route planned) {
        userAction();
        cancelRunning();
        this.target = target;
        this.from = from;
        route = planned;
        status = null;
        changed.accept(this);
    }

    void clear() {
        userAction();
        target = -1;
        route = null;
        status = null;
        noStart = false;
        cancelRunning();
        changed.accept(this);
    }

    void cancelRunning() {
        if (running != null) {
            running.set(true);
            running = null;
        }
        pendingUser = false;
    }

    /** A setting that changes routes (or unlocks, bank) changed: search again once. */
    void settingsChanged() {
        userAction();
        if (target >= 0) {
            start(true);
        }
    }

    void userAction() {
        unreachable = null;
        unreachableAsked = null;
        asked = null;
        onlyMoved = false;
        searchedAt = -1;
        freshWaits();
    }

    /** Automatic searches may start at once again, and wait as for the first. */
    void freshWaits() {
        automatic = 0;
        backoff = FIRST_BACKOFF_MS;
        nextAutomatic = 0;
    }

    /**
     * The player went into or out of the house: the ways from here are others (its portal, box and fairy ring first), so
     * any search runs again from here at once, without the waits of a stray; only the route's own next jump from
     * where one was (its teleport into the house, its fairy ring out), landed where it lands, keeps the route.
     */
    void placeChanged(int player) {
        var next = route == null || running != null ? null
            : route.ahead(lastPlayer).steps.stream().filter(Route.Step::isJump).findFirst().orElse(null);
        if (target >= 0 && (next == null || player < 0 || !near(player, next.last(), STRAY))) {
            freshWaits();
            start(true);
        }
    }

    /** {@code player} packed or -1; starts a search when the player left the route. */
    void playerMoved(int player, boolean automaticAllowed) {
        int before = lastPlayer;
        lastPlayer = player;
        // Teleported (or up or down) from a steady spot: off the route there it is searched at once, also when a search
        // ran then; a position jumping about every tick keeps its waits.
        boolean jump = before >= 0 && player >= 0 && !near(player, before, STRAY);
        if (jump) {
            teleported = !jumped;
        }
        jumped = jump;
        if (target >= 0 && running == null && route == null && noStart && player >= 0 && automaticAllowed) {
            // Asked for where the position was unknown: retried now and then once it is known.
            long now = clock.getAsLong();
            if (now >= nextStartTry) {
                nextStartTry = now + FIRST_BACKOFF_MS;
                status = "Searching…";
                start(true);
                changed.accept(this);
            }
            return;
        }
        if (jump && teleported && running != null && target >= 0 && automaticAllowed && player >= 0) {
            // Teleported (into the house, say) while a search from the old spot runs: it is for where one no longer
            // is, so it is replaced at once by one from here (the house's own ways first).
            start(true);
            return;
        }
        if (target < 0 || running != null || !automaticAllowed || player < 0 || route == null) {
            return;
        }
        if (onRoute(player)) {
            // Back on the way: long trips get their automatic searches again.
            backoff = FIRST_BACKOFF_MS;
            automatic = 0;
            teleported = false;
            return;
        }
        long now = clock.getAsLong();
        if (teleported) {
            teleported = false;
            freshWaits();
        }
        if (searchedAt >= 0 && before >= 0 && near(player, before, 4) && !near(player, searchedAt, STRAY)
            && Pathfinder.folded(player, target) < Pathfinder.folded(searchedAt, target)) {
            // Walked on toward the target past where the last search began (its route came too late to be on): a new
            // stray, no wait. Walking elsewhere keeps the waits and the cap, as does jumping about (a glitching position).
            freshWaits();
        }
        if (automatic >= MAX_AUTOMATIC || now < nextAutomatic) {
            return;
        }
        searchedAt = player;
        nextAutomatic = now + backoff;
        var request = requests.apply(target);
        // A search that tried everything reached where this one would start, with the same ways.
        if (request != null && unreachable != null && unreachableAsked.sameWays(request)
            && unreachable.reached(pathfinder.startNode(request.start))) {
            // Out of reach from here with these ways (proved): looked at again after the wait, not searched.
            return;
        }
        automatic++;
        backoff = Math.min(MAX_BACKOFF_MS, backoff * 2);
        start(request, false);
    }

    static final int ARRIVED = 3;

    /** Within {@link #ARRIVED} tiles of the route's end (or the tile asked for), on the same floor. */
    boolean arrived(int player) {
        if (player < 0 || route == null || isSea(player)) {
            return false;
        }
        // A route that cannot get there ends where it gets stuck: no arrival.
        int end = route.outcome != FOUND ? -1 : route.end >= 0 ? route.end : target;
        return end >= 0 && Tiles.near(player, end, ARRIVED) || target >= 0 && Tiles.near(player, target, ARRIVED);
    }

    boolean onRoute(int player) {
        // With no steps: already there, or no start found, which a later position may fix. Its start: before a first
        // teleport.
        if (route.end >= 0 && near(player, route.end, STRAY) || from >= 0 && near(player, from, STRAY)) {
            return true;
        }
        for (var step : route.steps) {
            if (step.isJump()) {
                if (near(player, step.last(), STRAY) || step.first() != step.last() && near(player, step.first(), STRAY)) {
                    return true;
                }
                continue;
            }
            for (int point : step.points) {
                if (near(player, point, isSea(point) ? STRAY + CELL : STRAY)) {
                    return true;
                }
            }
        }
        return false;
    }

    static boolean near(int a, int b, int radius) {
        return Route.sameLevel(a, b) && distance(a, b) <= radius;
    }

    void start(boolean user) {
        if (running != null) {
            if (user) {
                // The newest user request wins: start it when the old one ends.
                running.set(true);
                pendingUser = true;
            }
            return;
        }
        start(requests.apply(target), user);
    }

    void start(RouteRequest request, boolean user) {
        noStart = request == null;
        if (request == null) {
            status = t("noPosition");
            changed.accept(this);
            return;
        }
        var cancel = new AtomicBoolean();
        running = cancel;
        int searched = target;
        try {
            searches.execute(() -> {
                Route result = null;
                try {
                    result = BankDetour.find(pathfinder, request, cancel::get, Integer.MAX_VALUE);
                } catch (Throwable e) {
                    log.warn("Route search to {} failed", format(searched), e);
                } finally {
                    Route done = result != null ? result : new Route(NONE, List.of(), 0, searched, -1,
                        false, false, 0);
                    callbacks.execute(() -> finished(cancel, searched, request, user, done));
                }
            });
        } catch (RejectedExecutionException e) {
            running = null;
        }
    }

    void finished(AtomicBoolean search, int searched, RouteRequest request, boolean user, Route result) {
        if (running == search) {
            running = null;
        }
        if (pendingUser && running == null) {
            pendingUser = false;
            if (target >= 0) {
                start(true);
                return;
            }
        }
        if (search.get() || searched != target || result.outcome == CANCELLED) {
            return;
        }
        onlyMoved = !user && asked != null && asked.sameWays(request);
        route = result;
        from = request.start;
        asked = request;
        if (result.exhausted && result.outcome != FOUND) {
            unreachable = result;
            unreachableAsked = request;
        }
        status = null;
        changed.accept(this);
    }
}

